(window.NTDATA=window.NTDATA||{});(NTDATA.arar=NTDATA.arar||{}).lk={"1":{"1":"Քանի որ մեզանում կատարված դեպքերի պատմությունը վերաշարադրելը շատերը ձեռնարկեցին,","2":"ինչպես ականատեսներն ու Խոսքին սպասավոր եղողներն էին սկզբից ավանդել մեզ,","3":"ես էլ, որ սկզբից ճշգրտորեն հետևում էի ամեն բանի, ուզեցի կարգով գրել քեզ, ո՛վ պատվականդ Թեոփիլե,","4":"որպեսզի ճանաչես հավաստիությունը այն խոսքերի, որոնց աշակերտեցիր։","5":"Հրեաստանի Հերովդես թագավորի օրոք մի քահանա կար, անունը՝ Զաքարիա, Աբիայի քահանայական դասից. նրա կինն Ահարոնի սերնդից էր, անունը՝ Եղիսաբեթ։","6":"Երկուսն էլ Աստծու առաջ արդար էին, Տիրոջ բոլոր պատվիրանների և օրենքների մեջ անարատ էին ընթանում։","7":"Նրանք զավակ չունեին, որովհետև Եղիսաբեթն ամուլ էր, և երկուսն էլ ծեր էին։","8":"Եվ երբ Աստծու առաջ քահանայություն անելու իր հերթը հասավ,","9":"քահանայության սովորության համաձայն՝ իրեն վիճակվեց, որ Տիրոջ տաճարը մտնի՝ խնկարկություն անելու։","10":"Խնկարկության ժամանակ ժողովրդի ամբողջ բազմությունը դրսում աղոթք էր անում։","11":"Եվ Տիրոջ հրեշտակը նրան երևաց՝ խնկի սեղանի աջ կողմում կանգնած։","12":"Զաքարիան, տեսնելով, շփոթվեց, և նրա մեջ ահ ընկավ։","13":"Հրեշտակը նրան ասաց. «Մի՛ վախեցիր, Զաքա՛րիա, որովհետև քո աղոթքը լսվեց, և քո կինը՝ Եղիսաբեթը, քեզ մի որդի կծնի, և նրա անունը Հովհաննես կդնես։","14":"Նա քեզ համար ուրախություն և ցնծություն կլինի. նրա ծնունդով շատերը կուրախանան,","15":"որովհետև նա Տիրոջ առաջ մեծ կլինի, գինի և ցքի չի խմի ու դեռ իր մոր որովայնից Սուրբ Հոգով կլցվի","16":"և Իսրայելի որդիներից շատերին իրենց Տեր Աստծու կողմը կդարձնի։","17":"Ինքն էլ Եղիայի հոգով ու զորությամբ նրա առաջից պիտի գնա։ Հայրերին ու որդիներին կհաշտեցնի, արդարների իմաստությունը անհնազանդներին ընդունելի կդարձնի, որպեսզի Տիրոջն ընդունելու պատրաստ ժողովուրդ կազմի»։","18":"Զաքարիան հրեշտակին ասաց. «Ես դա ինչպե՞ս իմանամ. չէ՞ որ ես ծեր եմ, կնոջս տարիքն էլ անցել է»։","19":"Հրեշտակը պատասխանեց նրան ու ասաց. «Ես Գաբրիելն եմ, որ Աստծու առաջ եմ կանգնում. ուղարկվել եմ քեզ հետ խոսելու և այս բաների մասին քեզ ավետիս տալու։","20":"Եվ ահա համր կլինես ու չես կարողանա խոսել մինչև այն օրը, երբ այս բաները լինեն, քանի որ չհավատացիր իմ այս խոսքերին, որոնք իրենց ժամանակին պիտի իրականանան»։","21":"Ժողովուրդը Զաքարիային էր սպասում, և տաճարում զարմանում էին, որ նա ուշանում է։","22":"Երբ դուրս եկավ, նրանց հետ չէր կարողանում խոսել, և իմացան, որ տաճարում տեսիլք էր տեսել։ Նա նշաններով էր խոսում նրանց հետ և մնում էր պապանձված։","23":"Բայց երբ նրա ծառայության օրերն ավարտվեցին, գնաց իր տուն։","24":"Այն օրերից հետո նրա կինը՝ Եղիսաբեթը, հղիացավ։ Հինգ ամիս իր հղիությունը գաղտնի էր պահում և ասում.","25":"«Տերն այս օրերին ինձ այսպես արեց, ինձ վրա նայեց, որ մարդկանց առաջ իմ նախատինքը վերացնի»։","26":"Վեցերորդ ամսին Գաբրիել հրեշտակն Աստծու կողմից ուղարկվեց Գալիլեայի մի քաղաք, որի անունը Նազարեթ էր,","27":"մի կույսի մոտ, որ նշանված էր Դավթի տնից Հովսեփ անունով մի մարդու հետ, և այն կույսի անունը Մարիամ էր։","28":"Հրեշտակը, նրա մոտ գալով, ասաց. «Ուրախացի՛ր, ո՛վ շնորհընկալ, Տերը քեզ հետ է»։","29":"Մարիամը, տեսնելով հրեշտակին, նրա խոսքերից շփոթվեց ու մտքում խորհում էր, թե այս ողջույնն ի՛նչ է նշանակում։","30":"Եվ հրեշտակը նրան ասաց. «Մի՛ վախեցիր, Մարիա՛մ, որովհետև Աստծուց շնորհ ստացար։","31":"Ահա կհղիանաս, որդի կծնես և նրա անունը Հիսուս կդնես։","32":"Նա մեծ կլինի ու Բարձրյալի Որդի կկոչվի։ Եվ Տերը՝ Աստված, նրան կտա Դավթի՝ նրա հոր աթոռը,","33":"և նա կթագավորի Հակոբի տան վրա հավիտյան։ Եվ նրա թագավորությանը վերջ չի լինի»։","34":"Մարիամը հրեշտակին ասաց. «Այդ ինչպե՞ս կլինի. չէ՞ որ ես դեռ տղամարդ չեմ ճանաչում»։","35":"Հրեշտակը պատասխանեց նրան. «Սուրբ Հոգին կգա քեզ վրա, և Բարձրյալի զորությունը հովանի կլինի քեզ, դրա համար քեզնից ծնվողն էլ սուրբ է և Աստծու Որդի կկոչվի։","36":"Եվ ահա քո ազգականը՝ Եղիսաբեթը, նա էլ հղիացավ իր ծեր օրով, և նա, որ ամուլ էր համարվում, վեցերորդ ամսվա մեջ է։","37":"Որովհետև Աստծու համար ոչ մի անկարելի բան չկա»։","38":"Մարիամն էլ ասաց. «Ահա Տիրոջ աղախինն եմ. թող քո ասածի համաձայն լինի ինձ»։ Եվ հրեշտակը հեռացավ նրա մոտից։","39":"Այդ օրերին Մարիամը վեր կացավ, շտապ գնաց լեռնային Հուդայի մի քաղաք։","40":"Մտավ Զաքարիայի տուն ու Եղիսաբեթին ողջունեց։","41":"Երբ Եղիսաբեթը Մարիամի ողջույնը լսեց, երեխան նրա որովայնում խաղաց, և Եղիսաբեթը Սուրբ Հոգով լցվեց։","42":"Բարձրաձայն գոչեց ու ասաց. «Օրհնյա՜լ ես դու կանանց մեջ, և օրհնյա՜լ է քո որովայնի պտուղը։","43":"Այս որտեղի՞ց էր, որ իմ Տիրոջ մայրն ինձ մոտ եկավ։","44":"Որովհետև երբ քո ողջույնի ձայնն իմ ականջներին հասավ, երեխան իմ որովայնում ցնծությունից խաղաց։","45":"Եվ երանի՜ նրան, որ հավատաց, որովհետև կկատարվեն այն բաները, որոնք Տիրոջ կողմից ասվել են իրեն»։","46":"Եվ Մարիամն ասաց. «Թող իմ անձը Տիրոջը փառավորի։","47":"Իմ հոգին ցնծաց իմ Փրկիչ Աստծով,","48":"որովհետև իր աղախնի խոնարհությունը նկատեց, և այսուհետև բոլոր սերունդներն ինձ երանի պիտի տան։","49":"Որովհետև Հզորն ինձ համար մեծամեծ գործեր արեց. և սուրբ է նրա անունը։","50":"Եվ նրա ողորմությունը սերնդեսերունդ իրենից երկյուղածների վրա է։","51":"Իր բազկով զորություն ցույց տվեց, ցրեց ամբարտավաններին՝ իրենց սրտի խորհուրդներով։","52":"Զորավորներին աթոռներից իջեցրեց ու խոնարհներին բարձրացրեց։","53":"Քաղցածներին բարիքներով լիացրեց ու հարուստներին դատարկ արձակեց։","54":"Օգնության հասավ իր ծառային՝ Իսրայելին՝ հիշելով իր ողորմությունները,","55":"ինչպես որ ասել է մեր հայրերին Աբրահամի ու նրա սերունդների վերաբերյալ հավիտյան»։","56":"Մարիամը նրա մոտ մնաց գրեթե երեք ամիս և իր տուն վերադարձավ։","57":"Եղիսաբեթի ծննդաբերելու ժամանակը լրացավ, և նա որդի ծնեց։","58":"Նրա հարևաններն ու ազգականները լսեցին, որ Տերը մեծ ողորմություն է արել նրան, և նրա հետ ուրախանում էին։","59":"Ութերորդ օրը եկան երեխային թլփատելու և նրան իր հոր անունով Զաքարիա էին կոչում,","60":"բայց նրա մայրն ասաց. «Ո՛չ, այլ Հովհաննես պիտի կոչվի»։","61":"Եվ նրան ասացին. «Քո ազգում ոչ ոք չկա, որ այդ անունով կոչվի»։","62":"Նրա հորը նշաններով հարցրին, թե ի՛նչ կկամենա, որ նա կոչվի։","63":"Նա տախտակ խնդրեց և վրան գրեց՝ ասելով. «Դրա անունը Հովհաննես է»։ Եվ ամենքը զարմացան։","64":"Եվ նրա բերանն ու լեզուն իսկույն բացվեցին, և խոսում էր՝ Աստծուն օրհնելով։","65":"Եվ ահ ընկավ նրանց շուրջն ապրող բոլորի սրտերը։ Ամբողջ լեռնային Հուդայում պատմվում էր այս ամենի մասին։","66":"Եվ բոլոր լսողները պատմվածն իրենց սրտերի մեջ էին պահում և ասում. «Արդյոք ի՞նչ պիտի լինի այս մանուկը»։ Եվ Տիրոջ ձեռքը նրա հետ էր։","67":"Նրա հայրը՝ Զաքարիան, Սուրբ Հոգով լցվեց, մարգարեացավ ու ասաց.","68":"«Օրհնյա՜լ է Տերը՝ Իսրայելի Աստվածը, որ այցելության եկավ և իր ժողովրդին փրկություն բերեց։","69":"Եվ իր ծառայի՝ Դավթի տնից մեզ համար փրկության եղջյուր կանգնեցրեց,","70":"ինչպես որ դարեր առաջ իր սուրբ մարգարեների բերանով ասել էր.","71":"Փրկություն կտա մեր թշնամիներից, բոլոր մեզ ատողների ձեռքից,","72":"ողորմություն կանի մեր հայրերին և կիրականացնի իր սուրբ ուխտը։","73":"Պահեց այն երդումը, որ տվել էր մեր հայր Աբրահամին, որպեսզի մեզ արժանավորի,","74":"մեր թշնամիների ձեռքից ազատվելուց հետո իրեն աներկյուղ պաշտենք՝","75":"որպես մեր կյանքի բոլոր օրերին նրա առաջ սրբությամբ ու արդարությամբ կանգնածներ։","76":"Եվ դու, ո՛վ մանուկ, Բարձրյալի մարգարե պիտի կոչվես, որովհետև Տիրոջ առաջից պիտի գնաս՝ նրա ճանապարհները պատրաստելու,","77":"որպեսզի նրա ժողովրդին, մեղքերի թողությամբ, փրկության գիտությունը տաս։","78":"Շնորհիվ մեր Աստծու գթառատ ողորմածության՝ ծագող արեգակը կայցելի մեզ բարձունքից՝","79":"խավարում և մահվան ստվերում նստողներին լույս տալու և մեր ոտքերը դեպի խաղաղության ճանապարհն ուղղելու»։","80":"Եվ մանուկն աճում էր ու հոգով զորանում և անապատներում էր մինչև այն օրը, երբ նա երևաց Իսրայելին։"},"2":{"1":"Այն օրերին Օգոստոս կայսրից հրաման արձակվեց, որ ամբողջ երկրում մարդահամար անցկացվի։","2":"Այս առաջին մարդահամարը եղավ Ասորիքի կուսակալ Կյուրենիոսի ժամանակ։","3":"Եվ բոլորը գնում էին արձանագրվելու՝ ամեն մեկն իր քաղաքը։","4":"Հովսեփն էլ Գալիլեայից՝ Նազարեթ քաղաքից, գնաց Հուդա՝ Դավթի քաղաքը, որ Բեթլեհեմ է կոչվում. որովհետև նա Դավթի տնից ու սերնդից էր.","5":"որպեսզի այնտեղ արձանագրվեր իր նշանածի՝ Մարիամի հետ, որ հղի էր։","6":"Երբ նրանք այնտեղ էին, նրա ծննդաբերելու օրերը լրացան։","7":"Եվ ծնեց իր անդրանիկ որդուն, խանձարուրի մեջ փաթաթեց, դրեց մսուրի մեջ, որովհետև իջևանատանը նրանց համար տեղ չկար։","8":"Այնտեղ դաշտում մնացող հովիվներ կային, որոնք գիշերն իրենց հոտերն էին պահում։","9":"Եվ ահա Տիրոջ հրեշտակը նրանց առաջ կանգնեց. Տիրոջ փառքը ծագեց նրանց շուրջը, ու մեծ վախ ապրեցին։","10":"Եվ հրեշտակը նրանց ասաց. «Մի՛ վախեցեք, որովհետև ահա ձեզ մեծ ուրախություն եմ ավետում, որ ամբողջ ժողովրդինն է լինելու.","11":"այսօր Դավթի քաղաքում ձեզ համար Փրկիչ ծնվեց, որ է Օծյալ Տերը։","12":"Սա ձեզ համար նշան կլինի. մի երեխա կգտնեք խանձարուրով փաթաթված ու մսուրի մեջ դրված»։","13":"Եվ հանկարծ այն հրեշտակի հետ հայտնվեց երկնավոր զորքի մի բազմություն, որ օրհնում էր Աստծուն և ասում.","14":"«Փա՜ռք Բարձրյալ Աստծուն, երկրի վրա՝ խաղաղություն, ու մարդկանց մեջ՝ հաճություն»։","15":"Եվ երբ հրեշտակները նրանց մոտից երկինք բարձրացան, հովիվներն իրար ասացին. «Եկեք մինչև Բեթլեհեմ գնանք ու տեսնենք տեղի ունեցածը, որը Տերը ցույց տվեց մեզ»։","16":"Շտապելով եկան և գտան Մարիամին ու Հովսեփին և երեխային՝ մսուրի մեջ պառկած։","17":"Եվ երբ տեսան, ճանաչեցին նրան այն խոսքից, որ իրենց ասվել էր երեխայի մասին։","18":"Բոլոր լսողներն էլ զարմացան հովիվների պատմածների վրա։","19":"Իսկ Մարիամն այդ ամենը պահում էր իր սրտում և մտորում։","20":"Հովիվները հետ դարձան՝ Աստծուն փառաբանելով և օրհնելով այն ամենի համար, որ լսեցին ու տեսան, ինչպես որ ասվել էր իրենց։","21":"Երբ ութ օրերը լրացան, և մանուկը պետք է թլփատվեր, նրա անունը Հիսուս դրվեց, ինչպես որ դեռ որովայնում հղացվելուց առաջ կոչվել էր հրեշտակի կողմից։","22":"Իսկ երբ Մովսեսի օրենքի համաձայն Մարիամի մաքրվելու օրերը լրացան, մանկանը բերեցին Երուսաղեմ՝ Տիրոջը ներկայացնելու,","23":"ինչպես Տիրոջ օրենքում է գրված. «Ամեն արու, որ արգանդ բացի, Տիրոջ համար սուրբ կկոչվի» (Ելք 13.2, 12)։","24":"Եվ Տիրոջ օրենքում ասվածի համաձայն պետք է մի զույգ տատրակ կամ աղավնու երկու ձագ ընծա տալ (Ղևտ. 12.8)։","25":"Այն ժամանակ Երուսաղեմում մի մարդ կար, որի անունը Սիմեոն էր։ Այդ մարդն արդար ու աստվածավախ էր և Իսրայելի մխիթարությունն էր ակնկալում, և Սուրբ Հոգին նրա վրա էր։","26":"Սուրբ Հոգին նրան հայտնել էր, որ մահ չի տեսնելու, մինչև որ Տիրոջ Օծյալին չտեսնի։","27":"Եվ Հոգով առաջնորդվելով՝ տաճար եկավ, և երբ ծնողները Հիսուս մանկանը բերեցին, որ կատարեն, ինչ որ օրենքի սովորության համաձայն էր,","28":"Սիմեոնը գիրկն առավ նրան, օրհնեց Աստծուն և ասաց.","29":"«Հիմա, ո՛վ Տեր, արձակի՛ր քո ծառային քո խոստման համաձայն՝ խաղաղությամբ։","30":"Որովհետև իմ աչքերը տեսան քո փրկությունը,","31":"որ պատրաստեցիր բոլոր ժողովուրդների առաջ։","32":"Լույս՝ հեթանոսներին լուսավորելու, և փառք Իսրայելին՝ քո ժողովրդին»։","33":"Հովսեփն ու նրա մայրը զարմացած էին այն խոսքերի համար, որ նրա մասին ասվում էին։","34":"Եվ Սիմեոնն օրհնեց նրանց ու ասաց նրա մորը՝ Մարիամին. «Ահա սա է, որ պատճառ է լինելու Իսրայելում շատերի անկման կամ բարձրացման և նշան հակառակության։","35":"Քո հոգու միջով էլ սուր պիտի անցնի, ինչպես որ շատերի սրտերի խորհուրդները պիտի հայտնի դառնան»։","36":"Այնտեղ էր նաև մարգարեուհի Աննան՝ Փանուելի աղջիկը, Ասերի ցեղից։ Նա ինքը բավական տարիքն առած էր և իր կուսության ժամանակից յոթ տարի էր ապրել ամուսնու հետ։","37":"Գրեթե ութսունչորս տարեկան այրի էր. տաճարից չէր հեռանում, ծոմապահությամբ ու աղոթքով գիշեր-ցերեկ Աստծուն էր ծառայում։","38":"Սա ևս նույն ժամին եկավ. Տիրոջը գոհություն էր հայտնում և մանկան մասին խոսում բոլոր նրանց հետ, ովքեր Երուսաղեմի փրկությանն էին սպասում։","39":"Եվ երբ ամեն բան Տիրոջ օրենքի համաձայն կատարեցին, վերադարձան Գալիլեա՝ իրենց Նազարեթ քաղաքը։","40":"Իսկ մանուկն աճում էր ու զորանում՝ լի իմաստությամբ, և Աստծու շնորհը նրա վրա էր։","41":"Նրա ծնողներն ամեն տարի Զատկի տոնին Երուսաղեմ էին գնում։","42":"Եվ երբ նա տասներկու տարեկան դարձավ, նրանք, տոնի սովորության համաձայն, Երուսաղեմ գնացին։","43":"Երբ տոնակատարության օրերը լրացան, և նրանք վերադարձան, մանուկ Հիսուսը Երուսաղեմում մնաց. նրա ծնողները չիմացան այդ մասին։","44":"Կարծելով, թե նա ուղեկիցների հետ է, մեկ օրվա ճանապարհ եկան, ապա նրան փնտրեցին ազգականների ու ծանոթների մեջ։","45":"Երբ նրան չգտան, հետ դարձան Երուսաղեմ՝ նրան փնտրելու։","46":"Երեք օր հետո նրան գտան տաճարում վարդապետների մեջտեղում նստած. լսում էր նրանց ու հարցեր տալիս։","47":"Բոլոր նրան լսողները զարմանում էին նրա իմաստության ու պատասխանների վրա։","48":"Երբ ծնողները նրան տեսան, ապշեցին։ Նրա մայրն ասաց. «Որդյա՛կ, ինչո՞ւ մեզ հետ այդպես արեցիր. ահավասիկ հայրդ ու ես տագնապած քեզ էինք փնտրում»։","49":"Եվ նա ասաց նրանց. «Ինչո՞ւ էիք ինձ փնտրում, չգիտեի՞ք, որ ես պետք է իմ Հոր տանը լինեմ»։","50":"Իսկ նրանք չհասկացան այն խոսքը, որ իրենց ասաց։","51":"Եվ նրանց հետ իջավ ու Նազարեթ գնաց. և նրանց հնազանդ էր։ Նրա մայրն այս բոլոր բաները պահում էր իր սրտում։","52":"Հիսուսն Աստծու ու մարդկանց առաջ զարգանում էր իմաստությամբ, հասակով ու շնորհով։"},"3":{"1":"Տիբերիոս կայսեր կառավարման տասնհինգերորդ տարում, երբ Պոնտացի Պիղատոսը Հրեաստանի կուսակալն էր, և Հերովդեսը՝ Գալիլեայի չորրորդապետը, նրա եղբայր Փիլիպպոսը՝ չորրորդապետն իտուրացիների և տրաքոնացիների երկրում, Լյուսանիասը՝ չորրորդապետն Աբիլենեի,","2":"Աննասի ու Կայիափայի քահանայապետության օրերին, Աստծու խոսքը եղավ Զաքարիայի որդի Հովհաննեսին անապատում։","3":"Նա եկավ Հորդանանի բոլոր կողմերը՝ մեղքերի թողության համար ապաշխարության մկրտությունը քարոզելով,","4":"ինչպես գրված է Եսայի մարգարեի պատգամների գրքում, որ ասում է. «Անապատում կանչողի ձայնն է. \"Պատրաստե՛ք Տիրոջ ճանապարհը, ուղի՛ղ դարձրեք նրա շավիղները։","5":"Ամեն ձոր թող լցվի, և ամեն լեռ ու բլուր խոնարհվեն. շեղ ճանապարհները թող ուղիղ լինեն, և խորդուբորդները՝ հարթ դառնան։","6":"Եվ ամեն մարդ Աստծու փրկությունը կտեսնի\"» (Ես. 40.3-5)։","7":"Եվ ժողովրդի այն բազմություններին, որոնք դուրս էին եկել նրանից մկրտվելու, ասաց. «Իժերի՛ ծնունդներ, ո՞վ ձեզ սովորեցրեց փախչել գալիք բարկությունից։","8":"Արդ ապաշխարության արժանի պտուղնե՛ր արարեք ու մի՛ սկսեք ձեր մեջ ասել. \"Մենք Աբրահամին մեզ հայր ունենք\"։ Որովհետև ասում եմ ձեզ, որ Աստված այս քարերից կարող է Աբրահամի համար որդիներ դուրս բերել։","9":"Բայց արդեն կացինն էլ ծառերի արմատին է հասել. արդ ամեն ծառ, որ բարի պտուղ չի տալիս, կկտրվի ու կրակը կգցվի»։","10":"Եվ ժողովուրդը նրան հարցնում էր. «Հապա ի՞նչ անենք»։","11":"Նա պատասխանեց նրանց ու ասաց. «Ով երկու հագուստ ունի, մեկը թող չունեցողին տա, և ով ուտելիք ունի, թող նույնն անի»։","12":"Մաքսավորները եկան մկրտվելու ու նրան ասացին. «Վարդապե՛տ, մենք ի՞նչ անենք»։","13":"Նա ասաց նրանց. «Ձեզ հրամայվածից ավելին մի՛ պահանջեք»։","14":"Զինվորներն էլ էին նրան հարցնում. «Հապա մե՞նք ինչ անենք»։ Նրանց էլ ասաց. «Ոչ մեկի մի՛ հարստահարեք, ոչ էլ զրպարտություն արեք. ձեր վարձո՛վ բավարարվեք»։","15":"Ժողովուրդը սպասման մեջ էր, և բոլորն իրենց սրտում մտածում էին Հովհաննեսի մասին. «Գուցե Քրիստոսը նա՞ է»։","16":"Հովհաննեսը բոլորին ասաց. «Ես ձեզ ջրով եմ մկրտում, բայց ինձանից ավելի զորավորն է գալիս, որի կոշիկների կապերն արձակելու արժանի չեմ. նա ձեզ Սուրբ Հոգով ու կրակով կմկրտի։","17":"Հոսելին իր ձեռքին է, և նա իր կալը կսրբի, ցորենն իր ամբարի մեջ կհավաքի, իսկ հարդն անշեջ հրով կայրի»։","18":"Եվ ուրիշ շատ բաներ հորդորելով քարոզում էր ժողովրդին։","19":"Բայց Հերովդես չորրորդապետը, որ Հովհաննեսի կողմից հանդիմանվել էր իր եղբոր՝ Փիլիպպոսի կնոջ՝ Հերովդիայի համար և բոլոր չար գործերի համար, որ արել էր,","20":"այդ ամենին սա էլ ավելացրեց. Հովհաննեսին բանտում փակեց։","21":"Ամբողջ ժողովրդի մկրտվելուց հետո Հիսուսն էլ մկրտվեց և երբ աղոթում էր, երկինքը բացվեց,","22":"և Սուրբ Հոգին մարմնավոր տեսքով՝ որպես աղավնի իջավ նրա վրա, և երկնքից ձայն եղավ, որ ասում էր. «Դու ես իմ սիրելի Որդին, որ ունի իմ բարեհաճությունը»։","23":"Երբ Հիսուսը իր գործն սկսեց, երեսուն տարեկան էր, և ինչպես կարծվում էր, որդին էր Հովսեփի, Հեղիի,","24":"Մատթատի, Ղևիի, Մեղքիի, Հաննեի, Հովսեփի,","25":"Մատաթիայի, Ամովսի, Նավումի, Եսղիի, Նանգեի,","26":"Մաաթի, Մատաթիայի, Սեմեիի, Հովսեփի, Հուդայի,","27":"Հովհաննայի, Րեսայի, Զորաբաբելի, Սաղաթիելի, Ներեիի,","28":"Մեղքիի, Ադդեիի, Կովսամի, Եղմովդադի, Էրի,","29":"Հովսեսի, Եղիազարի, Հովրիմի, Մատթատի, Ղևիի,","30":"Սիմեոնի, Հուդայի, Հովսեփի, Հովնանի, Եղիակիմի,","31":"Մելիայի, Մայնանի, Մատտաթայի, Նաթանի, Դավթի,","32":"Հեսսեի, Օվբեդի, Բոոսի, Սաղմոնի, Նաասոնի,","33":"Ամինադաբի, Արամի, Եսրոնի, Փարեսի, Հուդայի,","34":"Հակոբի, Իսահակի, Աբրահամի, Թարայի, Նաքովրի,","35":"Սերուքի, Ռագավի, Փաղեկի, Եբերի, Սաղայի,","36":"Կայնանի, Արփաքսադի, Սեմի, Նոյի, Ղամեքի,","37":"Մաթուսաղայի, Ենովքի, Հարեդի, Մաղաղիելի, Կայնանի,","38":"Ենովսի, Սեթի, Ադամի, և նա՝ Աստծու։"},"4":{"1":"Հիսուսը, Սուրբ Հոգով լցված, Հորդանանից վերադարձավ և Հոգով անապատ առաջնորդվեց։","2":"Սատանայի կողմից քառասուն օր փորձվեց և այն օրերին ոչինչ չկերավ, իսկ երբ օրերը լրացան, քաղց զգաց։","3":"Եվ սատանան նրան ասաց. «Եթե Աստծու Որդի ես, այս քարին ասա՛, որ հաց դառնա»։","4":"Եվ Հիսուսը նրան ասաց. «Գրված է. \"Մարդ միայն հացով չի ապրում, այլև Աստծու ամեն խոսքով \" (Բ Օր. 8.3)»։","5":"Եվ սատանան նրան մի բարձր լեռ տարավ ու մի վայրկյանում նրան աշխարհի բոլոր թագավորությունները ցույց տվեց։","6":"Եվ սատանան նրան ասաց. «Այս ամբողջ իշխանությունն ու սրանց փառքը քեզ կտամ, որովհետև ինձ է տրված, և ում ցանկանում եմ, տալիս եմ այն։","7":"Արդ եթե դու իմ առաջ ընկած երկրպագես, ամբողջը քոնը կլինի»։","8":"Հիսուսը պատասխանեց նրան ու ասաց. «Գրված է. \"Տիրոջը՝ քո Աստծուն, պետք է երկրպագես ու միայն նրան պաշտես\" (Բ Օր. 6.13)»։","9":"Տարավ նրան Երուսաղեմ, կանգնեցրեց տաճարի աշտարակի վրա ու նրան ասաց. «Եթե Աստծու Որդի ես, այստեղից քեզ ցա՛ծ գցիր,","10":"որովհետև գրված է. \"Քեզ համար իր հրեշտակներին կհրամայի, որ քեզ պահեն,","11":"որ քեզ ձեռքերի վրա վերցնեն, որպեսզի ոտքդ երբեք քարի չդիպչի\" (Սաղ. 91.11-12)»։","12":"Հիսուսը նրան ասաց. «Ասված է. \"Տիրոջը՝ քո Աստծուն, մի՛ փորձիր\" (Բ Օր. 6.16)»։","13":"Եվ երբ սատանան ամեն փորձություն կատարեց, նրանից միառժամանակ հեռացավ։","14":"Եվ Հիսուսը Հոգու զորությամբ վերադարձավ Գալիլեա, ու նրա համբավը տարածվեց այն գավառի բոլոր կողմերում։","15":"Եվ նրանց ժողովարաններում ուսուցանում էր՝ բոլորի կողմից փառաբանվելով։","16":"Եկավ Նազարեթ, որտեղ մեծացել էր, և իր սովորության համաձայն՝ շաբաթ օրը ժողովարան մտավ ու ելավ ընթերցելու։","17":"Նրան Եսայի մարգարեի գիրքը տվեցին, և երբ գիրքը բացեց, գտավ այն տեղը, որտեղ գրված էր.","18":"«Տիրոջ Հոգին ինձ վրա է, որովհետև ի՛նձ օծեց և ի՛նձ ուղարկեց աղքատներին բարի լուրը ավետելու, սրտով բեկյալներին բժշկելու, գերիներին ազատություն քարոզելու և կույրերին՝ տեսողություն, հարստահարվածներին ազատ արձակելու,","19":"Տիրոջն ընդունելի տարին քարոզելու» (Ես. 61.1-2)։","20":"Եվ փակելով Գիրքը՝ պաշտոնյային տվեց ու նստեց. ժողովարանում բոլորի աչքերը նրան էին սևեռված։","21":"Եվ սկսեց նրանց ասել. «Այսօր այս գրվածքը կատարվեց, որ ձեր ականջներով լսեք»։","22":"Բոլորը համաձայնվում էին նրա հետ ու զարմանում այն շնորհալի խոսքերի վրա, որ դուրս էին գալիս նրա բերանից, և ասում էին. «Սա Հովսեփի որդին չէ՞»։","23":"Եվ ասաց նրանց. «Իհարկե, ինձ այս առակը կասեք. \"Բժի՛շկ, բժշկի՛ր ինքդ քեզ\"։ Կափառնաումում եղած որքա՜ն բաներ լսեցինք, այստեղ՝ քո հայրենիքո՛ւմ էլ արա»։","24":"Եվ ասաց. «Ճշմարիտ եմ ասում ձեզ. ոչ մի մարգարե ընդունելի չէ իր հայրենիքում։","25":"Արդարև ասում եմ ձեզ, որ Եղիայի օրոք Իսրայելում շատ այրիներ կային։ Այն ժամանակ երկինքը երեք տարի ու վեց ամիս փակվեց, և ամբողջ երկրով մեկ մեծ սով եղավ։","26":"Եվ Եղիան նրանցից ոչ ոքի մոտ չուղարկվեց, այլ միայն սիդոնացիների Սարեփթա քաղաքը՝ մի այրի կնոջ մոտ։","27":"Եղիսե մարգարեի ժամանակ Իսրայելում շատ բորոտներ կային, ու նրանցից ոչ ոք չմաքրվեց, բացի Նեեման Ասորուց»։","28":"Երբ այս լսեցին, ժողովարանում բոլորը բարկությամբ լցվեցին։","29":"Եվ վեր կացան, նրան քաղաքից դուրս հանեցին ու տարան մինչև այն լեռնագագաթը, որի վրա իրենց քաղաքն էր կառուցված, որպեսզի գահավեժ անեն նրան։","30":"Իսկ նա, նրանց միջով անցնելով, գնաց։","31":"Եվ իջավ Գալիլեայի Կափառնաում քաղաքը և շաբաթ օրերին ուսուցանում էր նրանց։","32":"Նրա վարդապետության վրա զարմանում էին, որովհետև նրա խոսքն իշխանությամբ էր։","33":"Ժողովարանում մի մարդ կար, որ պիղծ դևի ոգի ուներ. նա բարձրաձայն աղաղակեց.","34":"«Օ՜հ, մեզ հետ ի՞նչ գործ ունես, Հիսո՛ւս Նազովրեցի, մեզ կորստյան մատնելո՞ւ եկար. գիտեմ քեզ, թե ով ես. Աստծու Սուրբն ես»։","35":"Հիսուսը նրան սաստեց ու ասաց. «Պապանձվի՛ր ու դո՛ւրս ելիր դրանից»։ Դևը նրան մեջտեղում գետին զարկեց ու նրանից դուրս ելավ և նրան ոչ մի վնաս չտվեց։","36":"Բոլորին զարմանք պատեց. միմյանց հետ խոսում էին և ասում. «Ի՞նչ խոսք է սա, որ իշխանությամբ ու զորությամբ պիղծ ոգիներին սաստում է, և նրանք դուրս են գալիս»։","37":"Եվ նրա համբավը տարածվում էր շրջակա բոլոր գավառներում։","38":"Եվ ժողովարանից ելավ ու մտավ Սիմոնի տունը։ Սիմոնի զոքանչը բռնվել էր սաստիկ տենդով, և նրա համար խնդրեցին նրան։","39":"Հիսուսը կանգնեց նրա մոտ, սաստեց տենդին, ու տենդը նրան թողեց։ Նա իսկույն վեր կացավ ու ծառայում էր նրանց։","40":"Եվ մայրամուտին բոլոր նրանք, ովքեր տեսակ-տեսակ ցավերով հիվանդներ ունեին, նրա մոտ էին բերում նրանց. իսկ նա ձեռքը դնում էր նրանցից յուրաքանչյուրի վրա և բժշկում նրանց։","41":"Շատերի միջից էլ դևեր էին դուրս գալիս, աղաղակում էին ու ասում. «Դու ես Աստծու Որդին»։ Իսկ նա, սաստելով, նրանց թույլ չէր տալիս խոսել, որովհետև գիտեին նրան, որ Քրիստոսն է։","42":"Երբ լույսը բացվեց, Հիսուսը ելավ գնաց մի ամայի տեղ։ Եվ ժողովուրդը փնտրում էր նրան։ Եկան նրա մոտ և չէին թողնում նրան, որ իրենցից հեռանար։","43":"Իսկ նա նրանց ասաց. «Ես ուրիշ քաղաքների էլ պետք է Աստծու արքայությունը քարոզեմ, որովհետև հենց դրա համար եմ ուղարկվել»։","44":"Եվ քարոզում էր Հրեաստանի ժողովարաններում։"},"5":{"1":"Երբ ժողովուրդն Աստծու խոսքը լսելու համար խռնվում էր նրա շուրջը, նա կանգնած էր Գեննեսարեթի լճի ափին։","2":"Եվ լճափին երկու նավ տեսավ. ձկնորսներն էլ դրանց միջից դուրս էին եկել և ուռկաններն էին լվանում։","3":"Նա այդ նավերից մեկի մեջ մտավ, որ Սիմոնինն էր, ու նրան խնդրեց ցամաքից մի քիչ հեռացնել այն. նստեց ու նավի միջից ուսուցանում էր ժողովրդին։","4":"Եվ երբ խոսելուց դադարեց, Սիմոնին ասաց. «Քշի՛ր դեպի խորքը, ու ձեր ուռկանները գցե՛ք որսալու»։","5":"Սիմոնը նրան պատասխանեց. «Վարդապե՛տ, ամբողջ գիշեր չարչարվել ենք ու ոչինչ չենք բռնել, բայց քո խոսքի համար ուռկանը կգցեմ»։","6":"Եվ երբ այդ արեցին, մեծ քանակությամբ ձկներ լցվեցին, ու նրանց ուռկանները պատռվում էին։","7":"Մյուս նավի մեջ գտնվողներին նշան էին անում, որ գան իրենց օգնելու։ Նրանք եկան և երկու նավերն այնքան լցրին, որ սուզվում էին։","8":"Եվ Սիմոն Պետրոսը, այդ տեսնելով, Հիսուսի ծնկներին ընկավ ու ասաց. «Տե՛ր, հեռո՛ւ գնա ինձանից, որովհետև ես մեղավոր մարդ եմ»։","9":"Քանզի ահը պատեց նրան և բոլորին, ովքեր նրա հետ էին, այն ձկների համար, որ բռնել էին.","10":"նույնպես և Զեբեդեոսի որդիներին՝ Հակոբոսին ու Հովհաննեսին, որոնք Սիմոնի ընկերներն էին։ Հիսուսը Սիմոնին ասաց. «Մի՛ վախեցիր. այսուհետև մարդկանց պիտի որսաս»։","11":"Եվ նավերը ցամաք հանեցին, ամեն ինչ թողեցին ու նրան հետևեցին։","12":"Երբ Հիսուսը քաղաքներից մեկում էր, ահա բորոտությամբ պատված մի մարդ, տեսնելով Հիսուսին, երեսի վրա ընկած, նրան աղաչեց ու ասաց. «Տե՛ր, եթե կամենաս, կարող ես ինձ մաքրել»։","13":"Եվ նա, իր ձեռքը մեկնելով, դիպավ նրան ու ասաց. «Կամենում եմ, մաքրվի՛ր»։ Եվ բորոտությունն իսկույն նրա վրայից անցավ։","14":"Հիսուսը նրան պատվիրեց, որ ոչ ոքի չասի, այլ. «Գնա՛, քեզ քահանայի՛ն ցույց տուր և քո մաքրվելու համար ընծա՛ մատուցիր, ինչպես որ Մովսեսն է հրամայել, նրանց իբրև վկայություն նրանց»։","15":"Իսկ նրա համբավն ավելի էր տարածվում, և շատ ժողովուրդ էր հավաքվում նրան լսելու ու իրենց հիվանդություններից բժշկվելու։","16":"Իսկ նա հեռանում էր ամայի տեղեր և աղոթում։","17":"Մի օր, երբ նա ուսուցանում էր, նստած էին փարիսեցիներն ու օրենքի ուսուցիչները, որ եկել էին Գալիլեայի ու Հրեաստանի բոլոր գյուղաքաղաքներից և Երուսաղեմից։ Եվ բժշկելու համար Տիրոջ զորությունը նրա հետ էր։","18":"Եվ ահա մարդիկ մահիճով մի մարդու էին բերում, որ անդամալույծ էր, և ուզում էին նրան ներս մտցնել ու Հիսուսի առաջ դնել։","19":"Երբ այն ամբոխի պատճառով նրան ներս մտցնելու միջոց չգտան, բարձրացան տանիք և կտուրի բացվածքից նրան մահիճով իջեցրին մեջտեղը՝ Հիսուսի առաջ։","20":"Նրանց հավատը տեսնելով՝ ասաց. «Ո՛վ մարդ, քո մեղքերը քեզ ներված են»։","21":"Դպիրներն ու փարիսեցիները սկսեցին խորհել ու ասել. «Ո՞վ է սա, որ հայհոյանքներ է ասում. ո՞վ կարող է մեղքերը ներել, եթե ոչ՝ միայն Աստված»։","22":"Իսկ Հիսուսը, նրանց մտքերը գիտենալով, ասաց. «Ի՞նչ եք ձեր սրտերում խորհում։","23":"Ո՞րն է ավելի հեշտ՝ ասել \"Քեզ ներված լինեն քո մեղքերը\", թե՞ ասել \"Վե՛ր կաց ու քայլի՛ր\"։","24":"Բայց որպեսզի իմանաք, որ Մարդու Որդին իշխանություն ունի երկրի վրա մեղքերը ներելու (անդամալույծին ասաց). \"Քե՛զ եմ ասում, վե՛ր կաց, վերցրո՛ւ մահիճդ ու քո տո՛ւն գնա\"»։","25":"Եվ նա իսկույն վեր կացավ նրանց առաջ, իր վրա վերցրեց այն, ինչի վրա պառկած էր և իր տուն գնաց՝ Աստծուն փառաբանելով։","26":"Եվ բոլորն ապշահար եղան և փառավորում էին Աստծուն. ահով լցվեցին ու ասում էին. «Այսօր արտասովոր բաներ տեսանք»։","27":"Դրանից հետո Հիսուսը դուրս ելավ ու մի մաքսավորի տեսավ՝ Ղևի անունով, որ նստած էր մաքսատանը, և նրան ասաց. «Իմ հետևի՛ց արի»։","28":"Նա ամեն բան թողեց, վեր կացավ և նրա հետևից գնաց։","29":"Ղևին իր տանը նրա համար մեծ ընդունելություն արեց. և մեծ թվով մաքսավորներ և ուրիշներ նրանց հետ սեղան էին նստել։","30":"Փարիսեցիներն ու դպիրները նրա աշակերտների մոտ տրտնջում էին ու ասում. «Ինչո՞ւ եք մաքսավորների ու մեղավորների հետ ուտում և խմում»։","31":"Հիսուսը պատասխանեց նրանց. «Առողջները բժշկի կարիք չունեն, այլ հիվանդները։","32":"Ես չեմ եկել արդարներին կանչելու, այլ մեղավորներին՝ ապաշխարության»։","33":"Իսկ նրանք ասացին նրան. «Հովհաննեսի աշակերտները հաճախ ծոմ են պահում, աղոթում, նույնպես էլ՝ փարիսեցիներինը, իսկ քո աշակերտներն ուտում են և խմում»։","34":"Հիսուսն ասաց նրանց. «Մի՞թե կարող եք հարսանքավորներին ծոմ պահել տալ, քանի դեռ փեսան նրանց հետ է։","35":"Բայց կգան օրեր, երբ փեսան նրանցից կվերցվի, ապա այդ օրերին ծոմ կպահեն»։","36":"Նրանց մի առակ էլ ասաց. «Ոչ ոք հին հագուստի վրա նոր հագուստից կարկատան չի գցի, այլապես և՛ նորը կպատռվի, և՛ նոր կտորը հնի հետ չի հարմարվի։","37":"Եվ ոչ ոք հին տիկերի մեջ նոր գինի չի լցնի, այլապես նոր գինին տիկերը կպայթեցնի, գինին կթափվի, տիկերն էլ կփչանան։","38":"Այլ նոր գինին նոր տիկերի մեջ պետք է լցվի, և երկուսն էլ կպահվեն։","39":"Ոչ ոք հինը խմելուց հետո նորը չի ուզի, որովհետև կասի, թե հինն ավելի լավն է»։"},"6":{"1":"Շաբաթ օր էր, երբ Հիսուսն անցնում էր արտերի միջով. նրա աշակերտները հասկ էին պոկում, ափի մեջ տրորում և ուտում։","2":"Փարիսեցիներից ոմանք նրանց ասացին. «Ինչո՞ւ եք անում այն, ինչ օրինավոր չէ անել շաբաթ օրով»։","3":"Հիսուսը նրանց պատասխանեց. «Դուք չե՞ք կարդացել, թե ինչ արեց Դավիթը, երբ քաղց զգացին ինքը և իր հետ եղողները.","4":"ինչպես նա Աստծու տունը մտավ, վերցրեց առաջավորաց հացերն ու կերավ և տվեց իր հետ եղողներին, որ ուտելու իրավունք չունեին, բացի քահանաներից»։","5":"Եվ նրանց ասաց. «Մարդու Որդին նաև շաբաթ օրվա տերն է»։","6":"Մի ուրիշ շաբաթ օր նա ժողովարան մտավ և ուսուցանում էր. այնտեղ մի մարդ կար, որի աջ ձեռքը չորացած էր։","7":"Դպիրներն ու փարիսեցիները հետևում էին նրան՝ տեսնելու, թե արդյոք շաբաթ օրով պիտի բժշկի՞, որպեսզի նրան ամբաստանելու բան գտնեն։","8":"Իսկ նա, որ գիտեր նրանց մտքերը, չորացած ձեռքով մարդուն ասաց. «Վե՛ր կաց ու մեջտեղում կանգնի՛ր»։ Նա վեր կացավ և կանգնեց։","9":"Հիսուսը նրանց ասաց. «Ձեզ եմ հարցնում. ի՞նչն է օրինավոր շաբաթ օրով՝ բարի՞ք անելը, թե՞ չարիք, հոգի ապրեցնե՞լը, թե՞ կորստյան մատնելը»։","10":"Եվ շուրջը հավաքված բոլորի վրա նայելով՝ այն մարդուն ասաց. «Ձեռքդ մեկնի՛ր»։ Նա մեկնեց, և նրա ձեռքը մյուսի նման առողջացավ։","11":"Նրանք կատաղությամբ լցվեցին և միմյանց հետ խոսում էին, թե Հիսուսին ի՛նչ անեն։","12":"Այդ օրերին Հիսուսը լեռը ելավ աղոթելու և ամբողջ գիշերն անցկացրեց Աստծուն աղոթելով։","13":"Երբ լույսը բացվեց, կանչեց իր աշակերտներին, ընտրեց նրանցից տասներկուսին, որոնց և առաքյալներ անվանեց.","14":"Սիմոնին, որին էլ Պետրոս անվանեց, և Անդրեասին՝ նրա եղբորը, Հակոբոսին ու Հովհաննեսին, Փիլիպպոսին և Բարթողոմեոսին,","15":"Մատթեոսին և Թովմասին, Ալփեոսի որդի Հակոբոսին և Սիմոնին՝ Նախանձահույզ կոչվածին,","16":"Հակոբոսի որդի Հուդային և Հուդա Իսկարիովտացուն, որը և մատնիչ եղավ։","17":"Եվ նրանց հետ իջնելով՝ կանգ առավ մի տափարակ տեղ, որտեղ նրա աշակերտների մի մեծ խումբ, ինչպես նաև Հրեաստանից ու Երուսաղեմից, Տյուրոսի ու Սիդովնի ծովեզերքից ժողովրդի մի մեծ բազմություն","18":"եկել էին նրան լսելու և իրենց հիվանդություններից բժշկվելու։ Եվ պիղծ ոգիներից տառապողները բժշկվում էին։","19":"Ամբողջ ժողովուրդն ուզում էր նրան դիպչել, որովհետև նրանից զորություն էր դուրս գալիս ու բժշկում էր բոլորին։","20":"Հիսուսն աչքերը դեպի իր աշակերտները բարձրացրեց ու ասաց. «Երանի՜ աղքատներիդ, որովհետև ձերն է Աստծու արքայությունը։","21":"Երանի՜ նրանց, ովքեր քաղցած են այժմ, որովհետև պիտի հագենաք։ Երանի՜ նրանց, ովքեր լալիս են այժմ, որովհետև պիտի ծիծաղեք։","22":"Երանի՜ ձեզ, երբ մարդիկ ձեզ ատեն, երբ ձեզ մերժեն ու նախատեն և Մարդու Որդու պատճառով ձեր անունը վարկաբեկեն։","23":"Այդ օրն ուրա՛խ եղեք ու ցնծացե՛ք, որովհետև ձեր վարձը մեծ է երկնքում, որովհետև մարգարեների հանդեպ նրանց հայրերը նույն կերպ էին վարվում։","24":"Բայց վա՛յ ձեզ՝ հարուստներիդ, որովհետև դուք ձեր մխիթարությունն արդեն ստացել եք։","25":"Վա՛յ ձեզ, որ այժմ հագեցած եք, որովհետև քաղցելու եք։ Վա՛յ ձեզ, որ այժմ ծիծաղում եք, որովհետև պիտի սգաք և լացեք։","26":"Վա՛յ ձեզ, երբ բոլոր մարդիկ ձեր մասին բարի խոսեն, որովհետև սուտ մարգարեներին նրանց հայրերն այդպես էին անում։","27":"Բայց ասում եմ ձեզ, դուք, որ լսում եք. սիրե՛ք ձեր թշնամիներին, բարի՛ք արեք ձեզ ատողներին։","28":"Օրհնե՛ք ձեզ անիծողներին, աղոթե՛ք ձեզ նեղողների համար։","29":"Քո մի երեսին խփողին մյո՛ւսն էլ մոտեցրու. նրան, ով քո վերարկուն վրայիցդ հանում է, մի՛ արգելիր նրան շապիկդ էլ վերցնել։","30":"Ամենքին, ով քեզանից ուզում է, տո՛ւր, քեզնից վերցնողից էլ հետ մի՛ պահանջիր։","31":"Ինչպես ուզում եք, որ մարդիկ ձեզ անեն, նույնն էլ դո՛ւք արեք նրանց։","32":"Եվ եթե դուք ձեզ սիրողների՛ն սիրեք, ո՞րն է ձեր արած շնորհը, քանի որ մեղավորներն էլ են իրենց սիրողներին սիրում։","33":"Եվ եթե ձեր բարերարների՛ն բարիք անեք, ո՞րն է ձեր արած շնորհը, քանի որ մեղավորներն էլ են նույնն անում։","34":"Եվ եթե փոխ եք տալիս նրանց, որոնցից ակնկալում եք հետ առնել, ո՞րն է ձեր արած շնորհը, քանի որ մեղավորներն էլ են մեղավորներին փոխ տալիս, որպեսզի հավասար չափով հետ առնեն։","35":"Բայց դուք սիրե՛ք ձեր թշնամիներին, բարի՛ք գործեք և ոչինչ չակնկալելո՛վ փոխ տվեք, ու ձեր վարձը շատ կլինի, և դուք Բարձրյալի որդիները կլինեք, որովհետև նա գթառատ է ապերախտների ու չարերի հանդեպ։","36":"Ուրեմն ողորմա՛ծ եղեք, ինչպես որ ձեր Հայրն է ողորմած։","37":"Եվ մի՛ դատեք ու չեք դատվի, մի՛ պատժեք ու չեք պատժվի, ներե՛ք և ներված կլինեք։","38":"Տվե՛ք, և կտրվի ձեզ. ձեր գոգը կլցվի լա՛վ չափով՝ լեփ-լեցուն, առատ, որովհետև ինչ չափով որ չափեք, նույնով էլ ձեզ կչափվի»։","39":"Նրանց մի առակ էլ ասաց. «Մի՞թե կարող է կույրը կույրին առաջնորդել. չէ՞ որ երկուսն էլ փոսը կընկնեն։","40":"Աշակերտն իր ուսուցչից բարձր չէ, բայց կատարյալ դարձած ամեն ոք իր ուսուցչի պես կլինի։","41":"Եվ ինչո՞ւ քո եղբոր աչքի միջի շյուղը տեսնում ես, իսկ քո աչքի միջի գերանը չես նկատում։","42":"Կամ ինչպե՞ս կարող ես եղբորդ ասել՝ \"Եղբա՛յր, թող քո աչքի միջի շյուղը հանեմ\", բայց քո աչքի միջի գերանը չես տեսնում։ Կեղծավո՛ր, նախ քո աչքից գերանը հանի՛ր և հետո լավ կտեսնես, թե ինչպես քո եղբոր աչքից շյուղը հանես։","43":"Որովհետև չկա բարի ծառ, որ չար պտուղ տա, ոչ էլ չար ծառ, որ բարի պտուղ տա։","44":"Քանզի յուրաքանչյուր ծառ իր պտղից է ճանաչվում. որովհետև փշերից թուզ չեն քաղում, ոչ էլ մորենուց խաղող են հավաքում։","45":"Բարի մարդն իր սրտի բարի գանձից բարին է բխեցնում, իսկ չար մարդն իր սրտի չար կուտակվածից չարն է բխեցնում, որովհետև բերանը սրտի կուտակվածից է խոսում։","46":"Եվ ինչո՞ւ եք ինձ \"Տե՛ր, Տե՛ր\" կանչում, բայց չեք անում այն, ինչ ասում եմ։","47":"Ամեն ոք, ով ինձ մոտ է գալիս ու իմ խոսքերը լսում և դրանք կատարում, ցույց կտամ ձեզ, թե ո՛ւմ է նման։","48":"Նման է տուն կառուցող մի մարդու, որ հողը փորեց ու խորացրեց և հիմքը ժայռի վրա դրեց։ Երբ հեղեղ եղավ, գետը խփեց տանը, բայց չկարողացավ շարժել այն, որովհետև լավ էր կառուցված։","49":"Բայց նա, ով լսում է և չի կատարում, նման է մի մարդու, որ տուն է կառուցում հողի վրա առանց հիմքի. գետը խփեց, և այն իսկույն փլվեց, և այդ տան կործանումը մեծ եղավ»։"},"7":{"1":"Երբ Հիսուսը վերջացրեց իր բոլոր խոսքերը ժողովրդին, որ լսում էր, մտավ Կափառնաում։","2":"Մի հարյուրապետի ծառա, որ շատ սիրելի էր նրա համար, հիվանդացել և մերձիմահ էր։","3":"Նա, Հիսուսի մասին լսելով, հրեաների երեցներից ուղարկեց նրա մոտ՝ խնդրելով նրան, որ գա, իր ծառային փրկի։","4":"Նրանք, Հիսուսի մոտ գալով, նրան թախանձալից խնդրում էին և ասում. «Նա արժանի է, որ այդ նրան անես,","5":"որովհետև սիրում է մեր ազգը և ժողովարանը նա՛ կառուցեց մեզ համար»։","6":"Հիսուսը գնաց նրանց հետ. երբ տնից արդեն շատ հեռու չէր, հարյուրապետը նրա մոտ բարեկամներ ուղարկեց՝ ասելով. «Տե՛ր, նեղություն մի՛ կրիր, որովհետև արժանի չեմ, որ իմ հարկի տակ մտնես։","7":"Դրա համար էլ ինձ արժանի չհամարեցի քեզ մոտ գալու։ Այլ՝ խոսքո՛վ ասա, և ծառաս կբժշկվի։","8":"Որովհետև ես էլ իշխանության ենթակա մարդ եմ և իմ ձեռքի տակ զինվորներ ունեմ. սրան ասում եմ՝ գնա՛, և գնում է, մյուսին՝ արի՛, և գալիս է, իմ ծառային՝ այս բա՛նն արա, և անում է»։","9":"Հիսուսը, այս լսելով, նրա վրա զարմացավ, դարձավ իրեն հետևող ժողովրդին ու ասաց. «Ասում եմ ձեզ, որ Իսրայելում անգամ այսպիսի հավատ չգտա»։","10":"Եվ այն ուղարկված մարդիկ տուն վերադարձան ու հիվանդ ծառային բժշկված գտան։","11":"Հետևյալ օրը Հիսուսը գնում էր մի քաղաք, որ Նային էր կոչվում. նրա հետ գնում էին աշակերտները ու բազում ժողովուրդ։","12":"Եվ երբ մոտեցավ քաղաքի դարպասին, ահա մի մեռել էին դուրս բերում, որ միակ որդին էր իր մոր, և նա այրի էր. քաղաքից բազում ժողովուրդ նրա հետ էր։","13":"Տերը, նրան տեսնելով, գթաց ու ասաց. «Մի՛ լար»։","14":"Եվ մոտենալով դիպավ դագաղին. դագաղը տանողները կանգնեցին։ Եվ ասաց. «Պատանի՛, քե՛զ եմ ասում, վե՛ր կաց»։","15":"Մեռելը վեր կացավ, նստեց ու սկսեց խոսել։ Եվ Հիսուսը նրան իր մորը տվեց։","16":"Ահը պատեց բոլորին, և Աստծուն փառավորում էին՝ ասելով. «Մի մեծ մարգարե է մեր մեջ հայտնվել», և «Աստված այցելել է իր ժողովրդին»։","17":"Եվ նրա այս համբավն ամբողջ Հրեաստանով ու նրա շրջակայքով մեկ տարածվեց։","18":"Հովհաննեսին նրա աշակերտներն այս բոլորի մասին պատմեցին։ Հովհաննեսն իր աշակերտներից երկուսին իր մոտ կանչեց,","19":"Տիրոջ մոտ ուղարկեց՝ ասելու. «Դո՞ւ ես, որ գալու է, թե՞ ուրիշին սպասենք»։","20":"Այդ մարդիկ, նրա մոտ գալով, ասացին. «Հովհաննես Մկրտիչը մեզ քեզ մոտ է ուղարկել և ասում է. \"Դո՞ւ ես, որ գալու է, թե՞ ուրիշին սպասենք\"»։","21":"Նույն ժամին նա շատերին բժշկեց հիվանդություններից, տառապանքներից ու չար ոգիներից, բազում կույրերի տեսողություն շնորհեց։","22":"Եվ Հիսուսը պատասխանեց ու ասաց նրանց. «Գնացեք պատմե՛ք Հովհաննեսին, ինչ որ տեսաք ու լսեցիք. որ կույրերը տեսնում են, կաղերը՝ քայլում, բորոտները մաքրվում են, խուլերը՝ լսում, մեռյալները հարություն են առնում, ու աղքատներին Բարի լուրն է ավետվում։","23":"Եվ երանի՜ նրան, ով իմ պատճառով չի ընկնի»։","24":"Երբ Հովհաննեսի պատգամավորները գնացին, սկսեց ժողովրդին Հովհաննեսի մասին խոսել. «Ի՞նչ տեսնելու համար ելաք անապատ գնացիք՝ քամուց շարժվող մի եղե՞գ։","25":"Հապա ի՞նչ տեսնելու համար ելաք գնացիք՝ փափուկ զգեստներ հագած մի մարդո՞ւ. ահավասիկ նրանք, ովքեր փառավոր հագուստների ու փափուկ կենցաղի մեջ են, թագավորների պալատներում են։","26":"Հապա ի՞նչ տեսնելու համար ելաք գնացիք՝ մի մարգարեի՞. այո՛, ասում եմ ձեզ, որ առավել քան մարգարեն։","27":"Դա նա է, ում մասին գրված է. \"Ահա քո առջևից ուղարկում եմ իմ պատգամաբերին, որպեսզի քո առաջ քո ճանապարհը պատրաստի\" (Մղք. 3.1)։","28":"Ասում եմ ձեզ, որ կանանցից ծնվածների մեջ Հովհաննես Մկրտչից ավելի մեծ մարգարե չկա, բայց Աստծու արքայության մեջ ամենափոքրն ավելի մեծ է, քան նա»։","29":"Երբ ամբողջ բազմությունը, նույնիսկ մաքսավորները, Հովհաննեսին լսեցին, ընդունեցին Աստծու արդարությունը՝ Հովհաննեսի մկրտությամբ մկրտվելով։","30":"Փարիսեցիներն ու օրենսգետները, ընդհակառակը, Հովհաննեսից չմկրտվելով, մերժեցին այն, ինչ Աստված կամենում էր նրանց համար։","31":"«Արդ այս սերնդի մարդկանց ո՞ւմ նմանեցնեմ, ո՞ւմ են նման։","32":"Նման են այն երեխաներին, որոնք նստում են հրապարակներում, միմյանց ձայն են տալիս և ասում. \"Մենք ձեզ համար փող հնչեցրինք, բայց դուք չպարեցիք, ողբ ասացինք, բայց լաց չեղաք\"։","33":"Քանզի Հովհաննես Մկրտիչը եկավ, ո՛չ հաց էր ուտում, ո՛չ էլ գինի խմում, և ասում եք. \"Դև ունի\"։","34":"Եկավ Մարդու Որդին. ուտում է և խմում, բայց ասում եք. \"Ահա ուտող և գինի խմող մի մարդ, մաքսավորների ու մեղավորների բարեկամ\"։","35":"Բայց իմաստությունն արդարացվեց նրա բոլոր որդիների կողմից»։","36":"Փարիսեցիներից մեկը նրան խնդրում էր, որ իր հետ հաց ուտի։ Նա, մտնելով փարիսեցու տուն, սեղան նստեց։","37":"Եվ ահա այդ քաղաքում մի մեղավոր կին կար. երբ իմացավ, որ նա փարիսեցու տանը սեղան է նստել, մի ալաբաստրյա շիշ անուշահոտ յուղ բերելով","38":"և հետևից նրա ոտքերի մոտ կանգնելով՝ լաց լինելով սկսեց արտասուքով նրա ոտքերը թրջել ու իր գլխի մազերով սրբել. նրա ոտքերն էր համբուրում և յուղով օծում։","39":"Իսկ փարիսեցին, որ նրան հրավիրել էր, այդ տեսնելով, իր մտքում ասաց. «Եթե սա մարգարե լիներ, ապա կիմանար, թե ո՛վ կամ ինչպիսի՛ կին է իրեն դիպչում, որովհետև նա մեղավոր է»։","40":"Հիսուսը պատասխանեց նրան ու ասաց. «Սիմո՛ն, մի բան ունեմ քեզ ասելու»։ Նա էլ ասաց. «Ասա՛, Վարդապե՛տ»։ Ու ասաց.","41":"«Մի փոխատու երկու պարտապան ուներ. մեկը հինգ հարյուր դինար էր պարտք, մյուսը՝ հիսուն։","42":"Եվ երբ սրանք հատուցելու ոչինչ չունեին, երկուսին էլ պարտքը շնորհեց։ Արդ սրանցից ո՞րն ավելի շատ կսիրի նրան, ասա՛»։","43":"Սիմոնն էլ պատասխանեց. «Ինձ այնպես է թվում, թե նա, որին ավելի շատ շնորհվեց»։ Հիսուսն ասաց նրան. «Ուղի՛ղ դատեցիր»։","44":"Եվ դեպի կինը դառնալով՝ Սիմոնին ասաց. «Տեսնո՞ւմ ես այս կնոջը. ես քո տուն մտա, և դու իմ ոտքերին ջուր չլցրեցիր, բայց սա ոտքերս իր արտասուքներով թրջեց ու իր մազերով սրբեց։","45":"Դու ինձ համբույր չտվեցիր, իսկ սա այստեղ մտնելուցս ի վեր ոտքերս համբուրելուց չդադարեց։","46":"Դու իմ գլուխը յուղով չօծեցիր, իսկ սա իմ ոտքերն անուշահոտ յուղով օծեց։","47":"Դրա համար ասում եմ քեզ. սրա բազում մեղքերը ներված կլինեն, որովհետև շատ սիրեց. բայց ում որ քիչ ներվի, նա քիչ կսիրի»։","48":"Եվ այդ կնոջն ասաց. «Քո մեղքերը ներված են քեզ»։","49":"Նրա հետ սեղան նստողներն սկսեցին իրենց մտքում ասել. «Ո՞վ է սա, որ նույնիսկ մեղքերին է թողություն տալիս»։","50":"Եվ նա այդ կնոջն ասաց. «Քո հավատը քեզ փրկեց. գնա՛ խաղաղությամբ»։"},"8":{"1":"Դրանից հետո նա շրջում էր քաղաքից քաղաք և գյուղից գյուղ՝ քարոզելով և Աստծու արքայությունն ավետելով։ Նրա հետ էին նաև տասներկուսը,","2":"մի քանի կանայք, որոնք բժշկվել էին չար ոգիներից ու հիվանդություններից. Մարիամը, որ Մագդաղենացի էր կոչվում, որից յոթ դև էր դուրս եկել,","3":"Հովհաննան՝ Հերովդեսի տան տեսուչ Քուզայի կինը, Շուշանը և շատ ուրիշներ, որոնք իրենց ունեցվածքով ծառայում էին նրան։","4":"Երբ ժողովրդի մեծ բազմություն ու բազում քաղաքներից նրա մոտ եկածներ էին հավաքվել, առակով ասաց.","5":"«Սերմնացանը ելավ իր սերմը ցանելու։ Սերմանելիս մի մասը ճանապարհի եզերքին ընկավ, կոխկռտվեց, ու երկնքի թռչունները կերան։","6":"Ուրիշ մի մաս ապառաժի վրա ընկավ և բուսնելու ժամանակ խոնավություն չլինելու պատճառով չորացավ։","7":"Մեկ այլ մաս փշերի մեջ ընկավ, և փշերը նրա հետ բուսնեցին ու խեղդեցին այն։","8":"Եվ ուրիշ մի մաս բարեբեր ու պարարտ հողի վրա ընկավ և բուսնեց, հարյուրապատիկ պտուղ տվեց»։ Այս ասելիս բացականչեց. «Ով լսելու ականջ ունի, թող լսի»։","9":"Աշակերտները նրան հարցրին. «Այդ առակն ի՞նչ է նշանակում»։","10":"Նա ասաց. «Ձեզ տրված է գիտենալ արքայության խորհուրդները, բայց ուրիշների հետ առակներով եմ խոսում, որպեսզի նայելով չտեսնեն ու լսելով չիմանան (Ես. 6.9)։","11":"Իսկ առակը այս է նշանակում. սերմն Աստծու խոսքն է։","12":"Որոնք ճանապարհի եզերքին են, նրանք են, ովքեր լսում են, բայց հետո սատանան գալիս և խոսքը նրանց սրտից հանում է, որ չհավատան ու չփրկվեն։","13":"Որոնք ապառաժի վրա են, նրանք են, ովքեր երբ լսում են, խոսքն ուրախությամբ ընդունում են, սակայն դրանք արմատ չունեն. միառժամանակ հավատում են, բայց փորձության ժամանակ հեռանում են։","14":"Փշերի մեջ ընկնողները նրանք են, որ լսում են խոսքը, բայց հոգսերի, հարստության, կյանքի հաճույքների ներքո ընթանալով՝ խեղդվում են ու անպտուղ լինում։","15":"Իսկ այն պարարտ հողի մեջ եղողները նրանք են, որ բարի ու հոժար սրտով լսելով խոսքը՝ ընդունում են ու համբերությամբ պտուղ են տալիս։","16":"Ոչ ոք ճրագը չի վառի և ամանի տակ թաքցնի կամ մահճի տակ դնի, այլ աշտանակի վրա կդնի, որ ներս մտնողները լույսը տեսնեն։","17":"Որովհետև չկա ծածուկ բան, որ հայտնի չդառնա, ոչ էլ գաղտնի բան, որ չիմացվի ու չբացահայտվի։","18":"Ուրեմն ուշադի՛ր եղեք, թե ինչպե՛ս եք լսում. որովհետև ով ունի, նրան կտրվի, իսկ ով չունի, և այն, ինչ որ կարծում է, թե ունի, նրանից կվերցվի»։","19":"Հիսուսի մայրն ու նրա եղբայրները իր մոտ էին եկել ու բազմության պատճառով չէին կարողանում նրան մոտենալ։","20":"Իմաց տվեցին նրան ու ասացին. «Մայրդ ու եղբայրներդ դրսում կանգնել, ուզում են տեսնել քեզ»։","21":"Իսկ նա պատասխանեց նրանց և ասաց. «Իմ մայրն ու եղբայրները սրանք են, որ Աստծու խոսքը լսում են ու կատարում»։","22":"Մի օր Հիսուսն իր աշակերտների հետ նավ նստեց ու նրանց ասաց. «Լճի մյուս կողմն անցնենք»։ Եվ ճանապարհ ընկան։","23":"Երբ նավարկում էին, նա քնեց։ Եվ լճի վրա մրրիկ իջավ, ու նավը ջրով էր լցվում, և վտանգի մեջ էին։","24":"Մոտեցան, արթնացրին նրան ու ասացին. «Վարդապե՛տ, Վարդապե՛տ, կորչում ենք»։ Եվ նա վեր կացավ, սաստեց մրրիկին ու ջրի ալեկոծությանը, և հանդարտվեցին, ու խաղաղություն եղավ։","25":"Եվ նրանց ասաց. «Ո՞ւր է ձեր հավատը»։ Նրանք սարսափած զարմացան և միմյանց ասում էին. «Ո՞վ է արդյոք սա, որ հողմերին ու ջրերին էլ է հրաման տալիս, և իրեն հնազանդվում են»։","26":"Եվ նավարկեցին գերգեսացիների երկիրը, որ Գալիլեայի հանդիպակաց կողմում է։","27":"Երբ նա ցամաք ելավ, քաղաքից մի մարդ պատահեց նրան, որ դևեր ուներ։ Նա բավական ժամանակ հագուստ չէր հագել ու տան մեջ չէր ապրում, այլ գերեզմաններում։","28":"Հիսուսին տեսնելով՝ աղաղակեց, նրա առաջ ընկավ և բարձրաձայն ասաց. «Ի՞նչ ունես ինձ հետ, Հիսո՛ւս, Բարձրյա՛լ Աստծու Որդի, աղաչում եմ քեզ, ինձ մի՛ տանջիր»։","29":"Որովհետև պիղծ ոգուն հրամայում էր, որ այն մարդու միջից դուրս գա, քանզի շատ ժամանակ էր, ինչ բռնել էր նրան. շղթաներով ու ոտնակապերով կապված էր պահվում, բայց կապանքները կտրում ու դևի կողմից ամայի տեղեր էր տարվում։","30":"Հիսուսը նրան հարցրեց. «Անունդ ի՞նչ է»։ Նա ասաց. «Լեգեոն», որովհետև նրա մեջ շատ դևեր էին մտել։","31":"Եվ նրան խնդրում էին, որ իրենց չհրամայի անդունդը գնալ։","32":"Այնտեղ բազում թվով խոզերի մի երամակ կար, որ լեռան վրա արածում էր։ Եվ նրան խնդրում էին, որ թույլ տա իրենց նրանց մեջ մտնել, և թույլ տվեց նրանց։","33":"Դևերն այդ մարդու միջից դուրս ելան, խոզերի մեջ մտան, և երամակն այն գահավեժ տեղից դեպի լիճը խուժեց ու խեղդվեց։","34":"Երբ խոզարածներն այս պատահածը տեսան, փախան և քաղաքում ու ագարակներում պատմեցին։","35":"Եվ մարդիկ դուրս ելան պատահածը տեսնելու, եկան Հիսուսի մոտ ու գտան այն մարդուն, որից դևերը ելել էին, Հիսուսի ոտքերի մոտ նստած, հագնված ու զգաստացած, և վախեցան։","36":"Իսկ նրանք, ովքեր տեսել էին, նրանց պատմեցին, թե դիվահարն ինչպե՛ս էր փրկվել։","37":"Գերգեսացիների երկրի շրջակայքի ամբողջ բազմությունը նրան խնդրեց, որ իրենց մոտից հեռանա, որովհետև սաստիկ ահով էին բռնվել։ Նա, նավ նստելով, վերադարձավ։","38":"Իսկ այն մարդը, որից դևերը դուրս էին ելել, աղաչում էր նրա հետ լինել, բայց Հիսուսը արձակեց նրան ու ասաց.","39":"«Վերադարձի՛ր քո տուն ու պատմի՛ր, ինչ որ Աստված քեզ արեց»։ Նա գնաց ու ամբողջ քաղաքում քարոզում էր, ինչ որ Հիսուսն իրեն արեց։","40":"Երբ Հիսուսը վերադարձավ, ժողովուրդը ընդունեց նրան, որովհետև բոլորը սպասում էին նրան։","41":"Եվ ահա մի մարդ եկավ՝ Հայրոս անունով. նա ժողովրդապետ էր։ Հիսուսի ոտքերն ընկնելով՝ աղաչում էր նրան, որ իր տուն մտնի,","42":"որովհետև նրա տասներկու տարեկան մինուճար դուստրը մերձիմահ էր։ Երբ Հիսուսը գնում էր, ժողովուրդը նեղում էր նրան։","43":"Մի կին, որ տասներկու տարուց ի վեր արյունահոսության մեջ էր, իր ամբողջ ունեցվածքը բժիշկների վրա ծախսելով՝ չէր կարողացել ոչ մեկի կողմից բուժվել։","44":"Նա հետևից մոտեցավ, Հիսուսի հագուստի քղանցքին դիպավ, և նրա արյունահոսությունն իսկույն դադարեց։","45":"Եվ Հիսուսն ասաց. «Ո՞վ էր, որ ինձ դիպավ»։ Քանի որ բոլորը հերքում էին, Պետրոսն ու նրա հետ եղողներն ասացին. «Վարդապե՛տ, ժողովուրդն է քեզ սեղմում ու նեղում»։","46":"Սակայն Հիսուսն ասաց. «Մեկն ինձ դիպավ, որովհետև ես իմացա, որ ինձանից զորություն դուրս եկավ»։","47":"Եվ երբ կինը տեսավ, որ ծածուկ չմնաց, դողալով եկավ, նրա առաջ ընկավ և ամբողջ ժողովրդի առաջ նրան պատմեց, թե ի՛նչ պատճառով նրան դիպավ ու թե ինչպե՛ս իսկույն բժշկվեց։","48":"Հիսուսն ասաց նրան. «Դո՛ւստր, քո հավատը փրկեց քեզ, գնա՛ խաղաղությամբ»։","49":"Մինչ նա խոսում էր, ժողովրդապետի տնից մեկը եկավ ու նրան ասաց. «Աղջիկդ մեռավ, վարդապետին նեղություն մի՛ տուր»։","50":"Բայց Հիսուսը, լսելով, նրան պատասխանեց. «Մի՛ վախեցիր, միայն հավատա՛, և կփրկվի»։","51":"Երբ տուն էր մտնում, ոչ ոքի չթողեց իր հետ ներս մտնել, բացի Պետրոսից, Հակոբոսից ու Հովհաննեսից, աղջկա հորից ու մորից։","52":"Բոլորը լալիս էին ու նրա վրա ողբում։ Եվ նա ասաց. «Լաց մի՛ եղեք, որովհետև մեռած չէ, այլ քնած»։","53":"Բայց նրան ծաղրում էին, քանզի գիտեին, թե մեռել է։","54":"Իսկ նա, նրա ձեռքից բռնելով, ձայն տվեց և ասաց. «Մանո՛ւկ, վե՛ր կաց»։","55":"Եվ նրա հոգին վերադարձավ, ու նա իսկույն ոտքի կանգնեց։ Հիսուսը հրամայեց նրան ուտելու բան տալ։","56":"Նրա ծնողները զարմացած էին։ Հիսուսը պատվիրեց, որ եղածի մասին ոչ ոքի չասեն։"},"9":{"1":"Եվ իր տասներկու աշակերտներին կանչեց, նրանց զորություն և իշխանություն տվեց բոլոր դևերի վրա և հիվանդություններ բժշկելու։","2":"Եվ նրանց ուղարկեց Աստծու արքայությունը քարոզելու, հիվանդներին բժշկելու։","3":"Եվ նրանց ասաց. «Ճանապարհի համար ոչինչ չվերցնեք, ո՛չ գավազան, ո՛չ մախաղ, ո՛չ հաց, ո՛չ արծաթ, ո՛չ էլ երկուական վերարկու ունեցեք։","4":"Ո՛ր տունը մտնեք, այնտե՛ղ մնացեք ու այնտեղի՛ց գնացեք։","5":"Իսկ ովքեր ձեզ չընդունեն, ի վկայություն նրանց դեմ՝ այդ քաղաքից դուրս գալիս ձեր ոտքերից փոշին թափ տվեք»։","6":"Եվ նրանք ելան. շրջում էին գյուղից գյուղ՝ ավետարանելով ու ամեն տեղ բժշկություններ անելով։","7":"Հերովդես չորրորդապետը լսեց կատարված ամեն ինչի մասին ու զարմանում էր, քանի որ ոմանք ասում էին. «Հովհաննեսը մեռելներից հարություն է առել»,","8":"իսկ ոմանք էլ՝ «Եղիան է հայտնվել», ուրիշներն էլ՝ «Նախկին մարգարեներից մեկն է հարություն առել»։","9":"Հերովդեսն ասաց. «Հովհաննեսին ես գլխատել եմ. իսկ սա ո՞վ է, որի մասին ես այսպիսի բաներ եմ լսում»։ Եվ ուզում էր նրան տեսնել։","10":"Առաքյալները վերադարձան ու Հիսուսին պատմեցին, ինչ որ արել էին։ Նա, նրանց վերցնելով, առանձնացավ մի ամայի տեղ՝ մի քաղաքի մոտ, որ Բեթսայիդա էր կոչվում։","11":"Ժողովուրդը, իմանալով, նրա հետևից գնաց։ Հիսուսը նրանց ընդունեց. նրանց հետ խոսում էր Աստծու արքայության մասին։ Իսկ ովքեր բժշկվելու կարիք ունեին, բժշկում էր։","12":"Օրն սկսեց տարաժամել. տասներկուսը մոտեցան ու նրան ասացին. «Այդ ժողովրդին արձակի՛ր, որպեսզի շրջակա գյուղերն ու ագարակները գնան, իջևանեն և ուտելիք գտնեն, որովհետև այստեղ ամայի վայրում ենք»։","13":"Սակայն նրանց ասաց. «Դո՛ւք դրանց ուտելիք տվեք»։ Նրանք էլ ասացին. «Մենք հինգ հացից ու երկու ձկից ավելին չունենք, եթե չգնանք, այդ ամբողջ ժողովրդի համար ուտելիք չգնենք»։","14":"Որովհետև հինգ հազարի չափ մարդ կար։ Եվ նա իր աշակերտներին ասաց. «Դրանց խումբ-խումբ, հիսուն-հիսուն նստեցրե՛ք»։","15":"Այդպես էլ արեցին ու բոլորին նստեցրին։","16":"Վերցնելով հինգ հացն ու երկու ձուկը՝ դեպի երկինք նայեց, դրանք օրհնեց ու մաս-մաս արեց և աշակերտներին տվեց, որպեսզի ժողովրդի առաջ դնեն։","17":"Բոլորն էլ կերան ու հագեցան, և ավելացած կտորտանքներից տասներկու քթոց հավաքեցին։","18":"Երբ նա առանձին աղոթք էր անում, նրա հետ էին նաև աշակերտները։ Նրանց հարցրեց ու ասաց. «Ժողովուրդն իմ մասին ի՞նչ է ասում. ո՞վ եմ ես»։","19":"Նրանք պատասխանեցին ու ասացին. «Հովհաննես Մկրտիչը, մյուսները՝ \"Եղիան\", ուրիշներն էլ՝ \"Նախկին մարգարեներից մեկն է հարություն առել\"»։","20":"Եվ նրանց ասաց. «Իսկ դո՞ւք իմ մասին ինչ եք ասում. ո՞վ եմ ես»։ Պետրոսը պատասխանեց և ասաց. «Աստծու Քրիստոսը»։","21":"Նա խիստ պատվիրեց նրանց, որ այդ ոչ ոքի չասեն։","22":"Եվ ասաց. «Մարդու Որդին պետք է շատ չարչարվի, մերժվի երեցներից, քահանայապետներից ու դպիրներից, սպանվի և երրորդ օրը հարություն առնի»։","23":"Եվ բոլորին ասում էր. «Եթե մեկն ուզում է իմ հետևից գալ, թող իր անձն ուրանա, ամեն օր իր խաչն առնի ու իմ հետևից գա։","24":"Որովհետև ով ցանկանա իր անձը փրկել, այն կկորցնի, իսկ ով ինձ համար իր անձը կորցնի, նա այն կփրկի։","25":"Քանի որ մարդու համար ի՞նչ օգուտ է, որ այս ամբողջ աշխարհը շահի, բայց իր անձը կորցնի կամ վնասվի։","26":"Որովհետև ով ինձ ու իմ խոսքերն ամոթ համարի, Մարդու Որդին էլ նրան կամաչեցնի, երբ գա իր, Հոր և սուրբ հրեշտակների փառքով։","27":"Բայց ճշմարիտ եմ ասում ձեզ. այստեղ գտնվողների մեջ կան ոմանք, որոնք մահ չեն ճաշակի, մինչև որ Աստծու արքայությունը չտեսնեն»։","28":"Եվ այս խոսքերից մոտ ութ օր հետո, Պետրոսին, Հովհաննեսին ու Հակոբոսին վերցնելով, լեռը բարձրացավ աղոթք անելու։","29":"Եվ երբ նա աղոթում էր, նրա դեմքի կերպարանքն այլակերպվեց, և նրա հագուստն սպիտակափայլ դարձավ։","30":"Եվ ահա նրա հետ խոսում էին երկու մարդ, որ Մովսեսն ու Եղիան էին։","31":"Նրանք, փառքով երևալով, նրա վախճանի մասին էին խոսում, որ կատարվելու էր Երուսաղեմում։","32":"Բայց Պետրոսն ու նրա հետ եղողները խոր քնով էին անցել ու երբ զարթնեցին, տեսան նրա փառքը և այն երկու մարդկանց, որ կանգնած էին նրա մոտ։","33":"Եվ երբ նրանք հեռանում էին նրանից, Պետրոսը Հիսուսին ասաց. «Վարդապե՛տ, մեզ համար լավ է, որ այստեղ մնանք և երեք տաղավար շինենք. մեկը քեզ համար, մեկը՝ Մովսեսի, մեկն էլ՝ Եղիայի»։ Եվ չգիտեր, թե ի՛նչ էր խոսում։","34":"Ու երբ նա այս ասում էր, մի ամպ եկավ ու նրանց վրա հովանի արեց, ու վախեցան, երբ այդ ամպի մեջ մտան։","35":"Եվ ամպից ձայն եղավ, որ ասաց. «Դա՛ է իմ ընտրյալ Որդին, դրա՛ն լսեք»։","36":"Այդ ձայնը լինելու պահին միայն Հիսուսն էր, և նրանք լռեցին ու այդ օրերին ոչ ոքի ոչինչ չպատմեցին այն բաների մասին, ինչ տեսան։","37":"Հետևյալ օրը, երբ նրանք իջնում էին լեռից, շատ ժողովուրդ եկավ Հիսուսին ընդառաջ։","38":"Եվ ահա ժողովրդի միջից մի մարդ աղաղակեց ու ասաց. «Վարդապե՛տ, աղաչում եմ քեզ, նայի՛ր իմ որդուն, որովհետև իմ միակն է։","39":"Ահա ոգի է նրան բռնում, և նա հանկարծ գոռում է. նրան գետնով է տալիս՝ բերանից փրփուր հանելով, ու նրան ջախջախելուց հետո հազիվ հեռանում է նրանից։","40":"Ես քո աշակերտներին աղաչեցի, որ դրան հանեն, բայց չկարողացան»։","41":"Հիսուսն ասաց. «Ո՛վ անհավատ և մոլորված սերունդ, մինչև ե՞րբ պիտի ձեզ հետ լինեմ և հանդուրժեմ ձեզ։ Այստե՛ղ բեր քո որդուն»։","42":"Եվ նրան մոտենալիս դևը նրան գետնով տվեց ու ցնցեց։ Հիսուսը պիղծ ոգուն սաստեց, երեխային բժշկեց և նրան իր հորը տվեց։","43":"Եվ բոլորը զարմանում էին Աստծու մեծության վրա։ Եվ երբ ամենքը զարմանում էին այն բոլոր բաների վրա, ինչ Հիսուսը կատարում էր, իր աշակերտներին ասաց.","44":"«Ակա՛նջ արեք այս խոսքերին, որովհետև Մարդու Որդին մարդկանց ձեռքն է մատնվելու»։","45":"Բայց նրանք այդ խոսքը չէին հասկանում. դրա իմաստը նրանցից ծածկված էր, որ չհասկանան նրան, և դրա մասին նրան հարցնելուց վախենում էին։","46":"Նրանց մեջ մի վեճ սկսվեց, թե իրենցից ո՛վ է մեծը։","47":"Հիսուսը, նրանց սրտի մտքերն իմանալով, վերցնելով մի մանկան, նրան իր մոտ կանգնեցրեց։","48":"Եվ նրանց ասաց. «Ով այս մանկանն իմ անունով ընդունի, ի՛նձ ընդունած կլինի, իսկ ով ինձ ընդունի, ինձ ուղարկողի՛ն ընդունած կլինի, որովհետև ով ձեր մեջ ամենափոքրն է, նա՛ է մեծը»։","49":"Հովհաննեսը պատասխանեց և ասաց. «Վարդապե՛տ, տեսանք մեկին, որ քո անունով դևեր էր հանում, ու նրան արգելեցինք, որովհետև մեզ հետ չի շրջում»։","50":"Հիսուսը նրանց ասաց. «Մի՛ արգելեք նրան, որովհետև ով մեզ դեմ չէ, մեր կողմն է»։","51":"Երբ լրանում էին նրա օրերը աշխարհից վերանալու, նա որոշեց Երուսաղեմ գնալ։","52":"Եվ իրենից առաջ պատգամավորներ ուղարկեց. նրանք գնալով սամարացիների մի գյուղ մտան, որ նրա համար տեղ պատրաստեն։","53":"Բայց նրան չընդունեցին, որովհետև նա Երուսաղեմ էր ուղղվում։","54":"Նրա աշակերտները՝ Հակոբոսն ու Հովհաննեսը, այդ տեսնելով, ասացին. «Տե՛ր, ուզո՞ւմ ես, որ ասենք՝ երկնքից կրակ իջնի ու դրանց ոչնչացնի»։","55":"Իսկ նա դարձավ, սաստեց նրանց։","56":"Եվ ուրիշ գյուղ գնացին։","57":"Եվ մինչ նրանք գնում էին, ճանապարհին ոմն մեկը նրան ասաց. «Ես քո հետևից կգամ, ո՛ւր էլ որ գնաս»։","58":"Հիսուսը նրան ասաց. «Աղվեսները որջեր ունեն, երկնքի թռչունները՝ բույներ, բայց Մարդու Որդին տեղ չունի, որ գլուխը դնի»։","59":"Մեկ ուրիշի էլ ասաց. «Արի՛ իմ հետևից»։ Սա ասաց. «Տե՛ր, թո՛ւյլ տուր, որ նախ գնամ, իմ հորը թաղեմ»։","60":"Հիսուսը նրան ասաց. «Թող մեռելներն իրենց մեռելներին թաղեն, իսկ դու գնա՛, Աստծու արքայությո՛ւնը քարոզիր»։","61":"Մեկ ուրիշն էլ ասաց. «Տե՛ր, քո հետևից կգամ, միայն թե նախ թո՛ւյլ տուր ինձ, որ իմ տնեցիներին հրաժեշտ տամ»։","62":"Հիսուսը նրան ասաց. «Ոչ ոք, ով ձեռքը մաճի վրա է դնում ու հետ նայում, հարմար չէ Աստծու արքայության համար»։"},"10":{"1":"Դրանից հետո Տերն ընտրեց ուրիշ յոթանասուներկու հոգու և նրանց իրենից առաջ երկու-երկու ուղարկեց այն բոլոր քաղաքներն ու վայրերը, ուր ինքն էր գնալու։","2":"Եվ նրանց ասում էր. «Հունձը շատ է, բայց մշակները՝ քիչ. ուրեմն հնձի Տիրոջն աղաչե՛ք, որ իր հնձի համար մշակներ ուղարկի։","3":"Գնացե՛ք. ահա ես ձեզ ուղարկում եմ իբրև գառներ՝ գայլերի մեջ։","4":"Մի՛ վերցրեք ո՛չ քսակ, ո՛չ մախաղ, ո՛չ կոշիկ և ճանապարհին ոչ ոքի հետ զրույցի մի՛ բռնվեք։","5":"Ո՛ր տունն էլ մտնեք, նախ ասե՛ք. \"Խաղաղությո՛ւն այս տանը\"։","6":"Եվ եթե այնտեղ խաղաղասեր մարդ լինի, ձեր մաղթանքը նրան կհասնի, ապա թե ոչ, ձեզ կվերադառնա։","7":"Այդ տա՛նը մնացեք, նրանց ունեցածից կերե՛ք ու խմե՛ք, որովհետև մշակն իր վարձին արժանի է։ Տնից տուն մի՛ տեղափոխվեք։","8":"Եվ ո՛ր քաղաքը մտնեք, ու ձեզ ընդունեն, կերե՛ք, ինչ որ ձեր առաջ դնեն։","9":"Եվ այնտեղ եղած հիվանդներին բժշկե՛ք ու նրանց ասե՛ք. \"Աստծու արքայությունը մոտեցել է ձեզ\"։","10":"Բայց եթե մտնեք մի քաղաք, որտեղ ձեզ չընդունեն, նրա հրապարակները դուրս գալով՝ ասե՛ք.","11":"\"Նույնիսկ ձեր քաղաքի փոշին, որ նստել է մեր ոտքերին, ձեզ վրա ենք թափ տալիս, բայց ա՛յս իմացեք, որ Աստծու արքայությունը մոտեցել է ձեզ\"։","12":"Ասում եմ ձեզ, որ սոդոմացիների համար այն օրն ավելի հեշտ կլինի, քան այդ քաղաքի։","13":"Վա՛յ քեզ, Քորազի՛ն, վա՛յ քեզ, Բեթսայի՛դա, որովհետև եթե այն հրաշքները, որոնք ձեր մեջ կատարվեցին, Տյուրոսում ու Սիդովնում եղած լինեին, վաղուց քրձի ու մոխրի մեջ նստած ապաշխարած կլինեին։","14":"Տյուրոսի ու Սիդովնի համար դատաստանի օրն ավելի հեշտ կլինի, քան ձեզ համար։","15":"Եվ դու, Կափառնաո՛ւմ, որ մինչև երկինք ես բարձրացել, մինչև դժոխք պիտի իջնես։","16":"Ձեզ լսողն ի՛նձ է լսում, ու ձեզ մերժողն ի՛նձ է մերժում, իսկ ինձ մերժողն էլ ինձ ուղարկողի՛ն է մերժում»։","17":"Եվ յոթանասուներկուսը վերադարձան ուրախությամբ՝ ասելով. «Տե՛ր, նույնիսկ դևերն են մեզ հնազանդվում քո անունով»։","18":"Եվ նրանց ասաց. «Տեսնում էի սատանային, որ վայր է ընկել երկնքից փայլակի պես։","19":"Ահա ձեզ իշխանություն տվեցի ոտնակոխելու օձերին, կարիճներին և թշնամու ունեցած ողջ զորությունը, և ձեզ ոչինչ չի վնասի։","20":"Բայց մի՛ ուրախացեք, որ ոգիները հնազանդվում են ձեզ, այլ ուրախացե՛ք, որ ձեր անունները գրված են երկնքում»։","21":"Նույն ժամին Հիսուսը Սուրբ Հոգով ցնծաց ու ասաց. «Գոհանում եմ քեզնից, Հա՛յր, Տե՛ր երկնքի և երկրի, որ իմաստուններից ու գիտուններից այս բաները ծածկեցիր և մանուկներին հայտնեցիր։ Այո՛, ո՛վ Հայր, որովհետև այսպես քեզ հաճելի եղավ։","22":"Ամեն բան ինձ տրվեց իմ Հորից, և ոչ ոք չգիտի, թե ո՛վ է Որդին, բացի Հորից, և ոչ էլ՝ ո՛վ է Հայրը, բացի Որդուց, և ում որ Որդին կամենա հայտնել»։","23":"Եվ դառնալով դեպի աշակերտները՝ հատուկ նրանց ասաց. «Երանի այն աչքերին, որ տեսնում են այն, ինչ դուք եք տեսնում։","24":"Որովհետև ասում եմ ձեզ, որ շատ մարգարեներ ու թագավորներ ցանկացան տեսնել այն, ինչ դուք եք տեսնում, բայց չտեսան, և լսել այն, ինչ դուք եք լսում, բայց չլսեցին»։","25":"Եվ ահա մի օրենսգետ վեր կացավ և նրան փորձելու համար ասաց. «Վարդապե՛տ, ի՞նչ անեմ, որ հավիտենական կյանքը ժառանգեմ»։","26":"Հիսուսն ասաց նրան. «Օրենքում ի՞նչ է գրված, ինչպե՞ս ես կարդում»։","27":"Նա պատասխանեց և ասաց. «Պիտի սիրես քո Տեր Աստծուն քո ամբողջ սրտով, քո ամբողջ հոգով, քո ամբողջ զորությամբ ու քո ամբողջ մտքով (Բ Օր. 6.5) և քո մերձավորին, ինչպես քո անձը (Ղևտ. 19.18)»։","28":"Եվ նրան ասաց. «Ճիշտ պատասխանեցիր. դա արա՛ և կապրես»։","29":"Իսկ նա, ցանկանալով ինքն իրեն արդարացնել, Հիսուսին ասաց. «Իսկ ո՞վ է իմ մերձավորը»։","30":"Հիսուսն ասաց. «Մի մարդ Երուսաղեմից Երիքով էր իջնում և ավազակների ձեռքն ընկավ։ Նրանք էլ նրան մերկացրին, վիրավորեցին ու կիսամեռ թողեցին գնացին։","31":"Պատահմամբ նույն ճանապարհով մի քահանա էր իջնում, որը, նրան տեսնելով, շրջանցեց։","32":"Նույն կերպ մի ղևտացի էր այդտեղով անցնում և տեսնելով նրան՝ շրջանցեց։","33":"Եվ մի սամարացի, որ ճանապարհորդում էր, նույն տեղով եկավ, նրան տեսնելով՝ գթաց։","34":"Մոտեցավ, նրա վերքերը կապեց՝ վրան ձեթ ու գինի լցնելով, իր գրաստի վրա դնելով՝ նրան մի իջևանատուն տարավ ու խնամեց։","35":"Հաջորդ օրը երկու դինար հանեց, իջևանատիրոջը տվեց ու ասաց. \"Խնամի՛ր նրան և ինչ որ ավելի ծախսես, ես մյուս անգամ վերադառնալիս կվճարեմ քեզ\"։","36":"Քո կարծիքով այդ երեքից ո՞րն էր մերձավորը ավազակների ձեռքն ընկած այն մարդու համար»։","37":"Նա ասաց. «Նա, ով ողորմեց նրան»։ Ապա Հիսուսը նրան ասաց. «Գնա՛, դո՛ւ էլ այդպես արա»։","38":"Երբ գնում էին, Հիսուսը մի գյուղ մտավ, և մի կին, որի անունը Մարթա էր, նրան ընդունեց իր տանը։","39":"Նա մի քույր ուներ՝ Մարիամ անունով, որ նստեց Հիսուսի ոտքերի մոտ ու նրա խոսքերն էր լսում։","40":"Իսկ Մարթան շատ զբաղված էր սպասավորելով. նա եկավ ու ասաց. «Տե՛ր, քեզ հոգ չէ՞, որ քույրս ինձ մենակ թողեց ծառայելու։ Արդ ասա՛ դրան, որ ինձ օգնի»։","41":"Հիսուսը պատասխանեց ու նրան ասաց. «Մա՛րթա, Մա՛րթա, դու հոգս ես անում և շատ բաներով ես զբաղված։","42":"Բայց մի բան է հարկավոր. և Մարիամը լավ բաժինն է ընտրել, որ նրանից չպիտի վերցվի»։"},"11":{"1":"Եղավ, որ Հիսուսը ինչ-որ տեղ աղոթք էր անում ու երբ դադարեց, նրա աշակերտներից մեկը նրան ասաց. «Տե՛ր, մեզ աղոթե՛լ սովորեցրու, ինչպես Հովհաննեսն իր աշակերտներին սովորեցրեց»։","2":"Եվ նրանց ասաց. «Երբ աղոթեք, ասե՛ք. \"Հա՛յր մեր, թող սուրբ լինի քո անունը, քո արքայությունը թող գա։","3":"Մեր հանապազօրյա հացը տո՛ւր մեզ ամեն օր։","4":"Եվ ների՛ր մեզ մեր մեղքերը, որովհետև մենք էլ ներում ենք ամենքին, որ մեղավոր են մեր հանդեպ, և մի՛ տար մեզ փորձության\"»։","5":"Եվ նրանց ասաց. «Ձեզանից ո՞վ է, որ բարեկամ ունենա, կեսգիշերին նրա մոտ գնա ու ասի. \"Բարեկա՛մ, ինձ երեք հաց փո՛խ տուր,","6":"որովհետև իմ բարեկամը ճանապարհից ինձ մոտ է եկել, ու ես ոչինչ չունեմ, որ նրա առաջ դնեմ\",","7":"իսկ նա ներսից պատասխանի ու ասի. \"Ինձ նեղություն մի՛ տուր. դուռն արդեն փակված է, ու երեխաներս ինձ հետ անկողնում են. չեմ կարող վեր կենալ ու տալ քեզ\"։","8":"Ասում եմ ձեզ. եթե նրա բարեկամը լինելու համար էլ վեր չկենա ու չտա նրան, ապա գոնե նրա թախանձանքի համար վեր կկենա ու կտա նրան, ինչ որ պետք է։","9":"Եվ ես ասում եմ ձեզ. խնդրե՛ք, և կտրվի ձեզ, փնտրե՛ք և կգտնեք, դուռը բախե՛ք, ու ձեր առաջ կբացվի։","10":"Որովհետև ով խնդրում է, ստանում է, և ով փնտրում է, գտնում է, և ով դուռը բախում է, նրա առաջ բացվում է։","11":"Ձեզանից ո՞վ է այն հայրը, որից որդին եթե ձուկ ուզի, մի՞թե ձկան փոխարեն օձ կտա նրան։","12":"Եվ կամ ձու ուզի, մի՞թե նրան կարիճ կտա։","13":"Արդ եթե դուք, որ չար եք, գիտեք բարի պարգևներ տալ ձեր որդիներին, որքա՜ն առավել երկնավոր Հայրը Սուրբ Հոգին կտա նրանց, ովքեր խնդրում են իրենից»։","14":"Հիսուսը մի դև էր հանում, որով բռնված մարդը համր էր։ Երբ դևը դուրս ելավ, համրը խոսեց, և ժողովուրդը զարմացավ։","15":"Նրանցից ոմանք ասացին. «Դա դևերի իշխան Բեեղզեբուղի միջոցով է դևերին հանում»։","16":"Ուրիշներն էլ փորձելու համար նրանից երկնքից նշան էին խնդրում։","17":"Բայց նա, նրանց մտքերը իմանալով, ասաց նրանց. «Ամեն թագավորություն, որ ինքն իր մեջ է բաժանված, ավերվում է, և տունը, որ իր մեջ է բաժանված, կործանվում է։","18":"Եթե սատանան էլ ինքն իր մեջ բաժանվի, նրա թագավորությունն ինչպե՞ս կանգուն կմնա. որովհետև դուք ասում եք, թե ես Բեեղզեբուղի միջոցով եմ դևերին հանում։","19":"Եթե ես Բեեղզեբուղի միջոցով եմ դևերին հանում, ձեր որդիներն ո՞ւմ միջոցով են հանելու։ Դրա համար նրա՛նք կլինեն ձեր դատավորները։","20":"Բայց եթե ես Աստծու ձեռքով եմ դևերին հանում, ուրեմն Աստծու արքայությունը ձեզ վրա հասել է։","21":"Երբ զինված հզոր մարդը պահպանում է իր պալատը, նրա ունեցվածքը ապահովության մեջ է։","22":"Բայց եթե նրանից ավելի զորավորը գա ու նրան հաղթի, կհանի նրա զենքերը, որոնց վրա հույս էր դրել, ու նրա ավարն էլ կբաժանի։","23":"Ով ինձ հետ չէ, ինձ հակառակ է, և ով ինձ հետ չի հավաքում, ցրում է։","24":"Երբ պիղծ ոգին մարդու միջից դուրս է ելնում, անջրդի տեղերում է շրջում ու հանգիստ է փնտրում։ Եվ երբ չի գտնում, ասում է. \"Վերադառնամ իմ տունը, որտեղից ելա\"։","25":"Եվ գալիս, այն մաքրված ու հարդարված է գտնում։","26":"Այն ժամանակ գնում է և իրենից ավելի չար ևս յոթ ոգիներ է վերցնում, և մտնում, բնակվում են այնտեղ, և այն մարդու վերջն ավելի վատ է լինում, քան նախկինում էր»։","27":"Եվ երբ նա խոսում էր այս, ժողովրդի միջից մի կին ձայն բարձրացրեց ու ասաց. «Երանի՜ այն որովայնին, որ կրել է քեզ, և այն ստինքներին, որ սնել են քեզ»։","28":"Իսկ նա ասաց. «Երանի՜ նրանց, որ Աստծու խոսքը լսում են ու պահում այն»։","29":"Երբ ժողովուրդը կուտակվում էր, սկսեց ասել. «Այս սերունդը չար է, նշան է խնդրում, բայց նրան ուրիշ նշան չի տրվի, բացի Հովնան մարգարեի նշանից։","30":"Որովհետև ինչպես Հովնանը նինվեացիների համար նշան եղավ, այնպես էլ Մարդու Որդին այս սերնդի համար նշան կլինի։","31":"Հարավի թագուհին դատաստանի ժամանակ վեր կկենա այս սերնդի մարդկանց հետ ու նրանց կդատապարտի, որովհետև նա երկրի ծայրից եկավ Սողոմոնի իմաստությունը լսելու, և ահա այստեղ Սողոմոնից ավելի մեծը կա։","32":"Նինվեի մարդիկ դատաստանի ժամանակ պիտի վեր կենան այս սերնդի հետ ու պիտի դատապարտեն նրան, որովհետև նրանք Հովնանի քարոզությամբ ապաշխարեցին, իսկ ահա այստեղ Հովնանից է՛լ ավելի մեծը կա։","33":"Ոչ ոք ճրագը վառելով ծածուկ տեղ չի դնում, ոչ էլ գրվանի տակ, այլ աշտանակի վրա, որպեսզի ներս մտնողները լույսը տեսնեն։","34":"Մարմնի ճրագն աչքն է. երբ աչքդ մաքուր է, ամբողջ մարմինդ լուսավոր կլինի, բայց եթե չար է, մարմինդ խավար կլինի։","35":"Ուրեմն զգո՛ւյշ եղիր. գուցե այն լույսը, որ քո մեջ է, խավար լինի։","36":"Եթե ամբողջ մարմինդ լուսավոր է, և ոչ մի խավար մաս չկա, ամբողջը լուսավոր կլինի, ինչպես ճրագն է իր ճառագայթով լուսավորում քեզ»։","37":"Երբ նա խոսում էր այս, մի փարիսեցի նրան խնդրում էր, որ իր մոտ ճաշի։ Եվ նա մտավ ու սեղան նստեց։","38":"Փարիսեցին, տեսնելով, զարմացավ, որ ճաշից առաջ չլվացվեց։","39":"Տերը նրան ասաց. «Հիմա դուք՝ փարիսեցիներդ, բաժակի ու ափսեի արտաքին կողմն եք մաքրում, բայց ձեր ներքինը լի է հափշտակությամբ և չարությամբ։","40":"Անմիտնե՛ր, չէ՞ որ արտաքինը ստեղծողը ներքինն էլ է ստեղծել։","41":"Սակայն ձեր ունեցածից ողորմությո՛ւն տվեք, և ամեն բան ձեզ համար մաքուր կլինի։","42":"Բայց վա՛յ ձեզ՝ փարիսեցիներիդ, որ անանուխի, փեգենայի ու ամեն բանջարեղենի տասանորդ եք տալիս, իսկ Աստծու արդարությունն ու սերը զանց եք առնում. նախ այս պետք էր անել, իսկ դրանք զանց չառնել։","43":"Վա՛յ ձեզ՝ փարիսեցիներիդ, որ ժողովարաններում առաջին աթոռներն եք սիրում, իսկ հրապարակներում՝ ողջույնները։","44":"Վա՛յ ձեզ, որ գերեզմանների պես աննկատ եք, և մարդիկ չգիտեն, որ դրանց վրայով են քայլում»։","45":"Եվ օրենսգետներից մեկը պատասխանեց ու ասաց նրան. «Վարդապե՛տ, այդ ասելով մեզ էլ ես նախատում»։","46":"Նա ասաց. «Ձեզ՝ օրենսգետներիդ էլ վա՛յ, որովհետև մարդկանց դժվարակիր բեռներով եք բեռնում, իսկ դուք ինքներդ մատով անգամ այդ բեռներին չեք դիպչում։","47":"Վա՛յ ձեզ, որ շինում եք մարգարեների գերեզմանները, իսկ նրանց ձեր հայրերն են սպանել։","48":"Այդ կերպ վկայում եք, որ հավանություն եք տալիս ձեր հայրերի գործերին, որովհետև նրանք կոտորեցին նրանց, իսկ դուք նրանց գերեզմաններն եք շինում։","49":"Դրա համար Աստծու իմաստությունն ասել է. \"Նրանց մոտ մարգարեներ ու առաքյալներ կուղարկեմ, և նրանցից ոմանց պիտի սպանեն ու հալածեն\",","50":"որպեսզի բոլոր մարգարեների արյունը, որ աշխարհի սկզբից թափվել է, այս սերնդից պահանջվի։","51":"Աբելի արյունից մինչև Զաքարիայի արյունը, որ սեղանի և տաճարի միջև սպանվեց, այո՛, ասում եմ ձեզ, այս սերնդից պիտի պահանջվի։","52":"Վա՛յ ձեզ՝ օրենսգետներիդ, որ վերցրել եք գիտության բանալին. ինքներդ չեք մտել, մտնողներին էլ արգելել եք»։","53":"Երբ նա դուրս ելավ, դպիրներն ու փարիսեցիներն սկսեցին սաստիկ թշնամանք ցուցաբերել և նրան բազում հարցումներ անել։","54":"Նրա դեմ որոգայթ էին լարում՝ փորձելով նրա բերանից մի խոսք որսալ՝ ամբաստանելու համար։"},"12":{"1":"Այդ ընթացքում, երբ բյուրավոր ժողովուրդ էր կուտակվում՝ իրար կոխկռտելու աստիճան, նա սկսեց իր աշակերտներին ասել. «Նախ զգուշացե՛ք փարիսեցիների խմորից, որ կեղծավորությունն է։","2":"Որովհետև ծածուկ ոչինչ չկա, որ հայտնի չդառնա, և գաղտնի բան, որ չիմացվի։","3":"Ուստի ինչ որ խավարում ասացիք, լույսի մեջ կլսվի, և ինչ որ փակ սենյակներում շշնջացիք, տանիքների վրա կհայտարարվի։","4":"Բայց ասում եմ ձեզ՝ իմ բարեկամներին. մի՛ վախեցեք նրանցից, որ մարմինն են սպանում ու դրանից հետո ավելին չունեն անելու։","5":"Բայց ձեզ ցույց կտամ, թե ումի՛ց պետք է վախենաք։ Նրանի՛ց վախեցեք, ով սպանելուց հետո գեհենի մեջ նետելու իշխանություն ունի. այո՛, ասում եմ ձեզ, նրանի՛ց վախեցեք։","6":"Չէ՞ որ հինգ ճնճղուկը, որ երկու ասսարիոնով են վաճառում, նույնիսկ դրանցից մեկը Աստծու առաջ մոռացված չէ։","7":"Ձեր գլխի բոլոր մազերն էլ հաշվված են. ուրեմն մի՛ վախեցեք, քանի որ դուք ճնճղուկներից շատ ավելին արժեք։","8":"Ասում եմ ձեզ. ամեն ոք, ով ինձ մարդկանց առաջ խոստովանի, Մարդու Որդին էլ նրան կխոստովանի Աստծու հրեշտակների առաջ։","9":"Եվ ով ինձ ուրանա մարդկանց առաջ, նա էլ Աստծու հրեշտակների առաջ կուրացվի։","10":"Նա, ով Մարդու Որդու դեմ բան ասի, նրան կներվի, բայց ով Սուրբ Հոգուն հայհոյի, նրան չի ներվի։","11":"Երբ ձեզ տանեն ժողովարաններ, իշխանավորների ու կառավարիչների առաջ, հոգ մի՛ արեք, թե ինչպե՛ս կամ ի՛նչ եք պատասխանելու կամ ի՛նչ եք ասելու,","12":"որովհետև Սուրբ Հոգին նույն պահին ձեզ կսովորեցնի, թե ի՛նչ պետք է խոսել»։","13":"Ժողովրդի միջից մեկը նրան ասաց. «Վարդապե՛տ, իմ եղբորն ասա՛, որ ժառանգությունն ինձ հետ բաժանի»։","14":"Նա էլ ասաց նրան. «Մա՛րդ, ո՞վ ինձ ձեզ վրա դատավոր կամ բաժանարար կարգեց»։","15":"Եվ նրանց ասաց. «Տեսե՛ք և զգուշացե՛ք ագահությունից. որովհետև մարդու կյանքը նրա կուտակած ունեցվածքը չէ»։","16":"Եվ նրանց մի առակ պատմեց ու ասաց. «Մի հարուստ մարդու արտն առատ պտուղ տվեց։","17":"Նա ինքն իր մեջ մտածում էր ու ասում. \"Ի՞նչ անեմ. տեղ չունեմ, որ իմ պտուղներն այնտեղ հավաքեմ\"։","18":"Եվ ասաց. \"Այս կանեմ. իմ շտեմարանները կքանդեմ, ավելի մեծերը կշինեմ և իմ ամբողջ բերքն ու բարիքներն այնտեղ կամբարեմ։","19":"Եվ ինքս ինձ կասեմ՝ ո՛վ մարդ, շատ տարիների համար ամբարված բազում բարիքներ ունես. հանգստացի՛ր, կե՛ր, խմի՛ր, զվարճացի՛ր\"։","20":"Բայց Աստված նրան ասաց. \"Անմի՛տ, հենց այս գիշեր հոգիդ քեզանից պահանջելու են. ինչ որ պատրաստել ես, ո՞ւմն է լինելու\"։","21":"Նույնպես է նաև նա, ով իր անձի համար գանձ է դիզում, բայց Աստծո՛վ չէ հարուստ»։","22":"Իր աշակերտներին ասաց. «Դրա համար ասում եմ ձեզ. ձեր կյանքի համար հոգ մի՛ արեք, թե ի՛նչ եք ուտելու, ոչ էլ ձեր մարմնի համար, թե ի՛նչ եք հագնելու։","23":"Հոգին ուտելիքից առավել է, մարմինն էլ՝ հագուստից։","24":"Նայե՛ք ագռավներին, որ ո՛չ ցանում են, ո՛չ էլ հնձում, որոնք ո՛չ շտեմարաններ ունեն, ո՛չ էլ ամբարներ, և Աստված կերակրում է նրանց. դուք թռչուններից որքա՜ն առավել արժեք ունեք։","25":"Ձեզանից ո՞վ կարող է մտահոգվելով իր հասակի վրա մի կանգուն ավելացնել։","26":"Արդ եթե ամենափոքր բանի մեջ անկարող եք, ինչո՞ւ եք ուրիշ բաների համար հոգս անում։","27":"Նայե՛ք շուշաններին՝ ինչպե՛ս են մեծանում. ո՛չ ջանք են թափում, ո՛չ էլ մանում են։ Բայց ասում եմ ձեզ. Սողոմոնն էլ իր ամբողջ փառքի մեջ դրանցից մեկի նման չհագնվեց։","28":"Իսկ եթե Աստված այդպես հագցնում է հանդի խոտը, որ այսօր կա ու վաղը կրակի մեջ է գցվում, ապա որքա՜ն առավել ձեզ, թերահավատնե՛ր։","29":"Եվ դուք մի՛ փնտրեք, թե ի՛նչ եք ուտելու կամ ի՛նչ եք խմելու, և մի՛ անհանգստացեք,","30":"որովհետև այդ ամենը աշխարհի հեթանոսներն են փնտրում, բայց ձեր Հայրը գիտե, որ դրանք ձեզ պետք են։","31":"Սակայն Աստծու արքայությո՛ւնը փնտրեք, և այդ բոլորը ավելիով կտրվի ձեզ։","32":"Մի՛ վախեցիր, փոքրի՛կ հոտ, որովհետև ձեր Հայրը հաճեց տալ ձեզ արքայությունը։","33":"Վաճառե՛ք ձեր ունեցվածքը և ողորմությո՛ւն տվեք, ձեզ համար չհնացող քսակնե՛ր պատրաստեք, որ հարատև գանձ է երկնքում, ուր գողը չի մոտենում, ոչ էլ ցեցն է ապականում։","34":"Որովհետև որտեղ ձեր գանձն է, այնտեղ էլ ձեր սրտերը կլինեն։","35":"Թող ձեր գոտիները մեջքներիդ կապված լինեն, ու ճրագները՝ վառված։","36":"Եվ դուք այն մարդկանց նմա՛ն եղեք, որոնք իրենց տիրոջն են սպասում, թե նա հարսանիքից ե՛րբ կվերադառնա, որպեսզի երբ գա ու դուռը բախի, իսկույն բացեն։","37":"Երանի՜ այն ծառաներին, որոնց արթուն կգտնի տերը, երբ գա։ Ճշմարիտ եմ ասում ձեզ, որ գոտին մեջքին կկապի ու նրանց սեղան կնստեցնի և կանցնի ծառայելու։","38":"Եվ եթե գիշերվա երկրորդ կամ երրորդ պահին գա ու այդպես գտնի, երանելի են նրանք։","39":"Բայց ա՛յս էլ իմացեք, որ եթե տանտերն իմանար, թե գողը ո՛ր ժամին կգար, թույլ չէր տա իր տուն սողոսկել։","40":"Արդ դո՛ւք էլ պատրաստ եղեք, որովհետև Մարդու Որդին կգա այն ժամին, երբ չեք սպասում»։","41":"Եվ Պետրոսն ասաց. «Տե՛ր, այդ առակը մե՞զ համար ասացիր, թե՞ բոլորի համար»։","42":"Տերն ասաց. «Ուրեմն, ո՞վ է այն հավատարիմ ու իմաստուն տնտեսը, որին տերն իր ծառաների վրա վերակացու է կարգել՝ նրանց ժամանակին կերակուր տալու համար։","43":"Երանի՜ այն ծառային, ում տերը երբ գա, այդպես անելիս կգտնի նրան։","44":"Ճշմարիտ եմ ասում ձեզ, որ նրան իր բոլոր ունեցվածքների վրա կկարգի։","45":"Բայց եթե այդ ծառան իր սրտում ասի՝ \"Իմ տերն ուշանում է գալ\", ու սկսի ծառաներին և աղախիններին ծեծել, ուտել, խմել ու հարբել,","46":"այդ ծառայի տերը կգա այն օրը, երբ ինքը չի սպասում, և այն ժամին, որ ինքը չգիտի, ու նրան երկու կես կանի և նրա բաժինն անհավատարիմների հետ կդնի։","47":"Իսկ այն ծառան, որ իր տիրոջ կամքն իմանալով՝ ոչինչ չի պատրաստի և ոչ էլ նրա կամքը կատարած կլինի, շատ խիստ կպատժվի։","48":"Իսկ նա, ով չիմանալով է ծեծի արժանի բան արել, քիչ կպատժվի։ Նրան, ում շատ է տրված, նրանից շատ կպահանջվի, և ում շատ է վստահվել, նրանից է՛լ ավելին կպահանջեն»։","49":"«Ես եկել եմ, որ աշխարհի վրա կրակ գցեմ, և ինչքա՜ն եմ ուզում, որ այն արդեն իսկ բորբոքված լինի։","50":"Բայց ես մի մկրտություն ունեմ մկրտվելու և որքա՜ն եմ տագնապում, մինչև որ այն կատարվի։","51":"Կարծում եք, թե աշխարհի վրա խաղաղություն հաստատելո՞ւ եմ եկել։ Ո՛չ, ասում եմ ձեզ, այլ՝ բաժանում։","52":"Որովհետև այսուհետև մի տան մեջ հինգ հոգին բաժան-բաժան կլինեն. երեքը՝ երկուսի դեմ, երկուսն էլ՝ երեքի դեմ։","53":"Հայրը որդուց կբաժանվի, և որդին՝ հորից, մայրը՝ աղջկանից, ու աղջիկը՝ մորից, սկեսուրը՝ հարսից, և հարսը՝ իր սկեսուրից (հմմտ. Միք. 7.6)»։","54":"Ժողովրդին էլ ասաց. «Երբ տեսնում եք՝ արևմուտքից ամպ է ելնում, իսկույն ասում եք՝ անձրև է գալու, և այդպես է լինում։","55":"Եվ երբ հարավային քամին է փչում, ասում եք՝ շոգ է լինելու, և այդպես է լինում։","56":"Կեղծավորնե՛ր, երկրի ու երկնքի նշանները քննել գիտեք, բայց այս ժամանակն ինչպե՞ս չեք քննում։","57":"Ինչո՞ւ ինքներդ չեք դատում այն, ինչ ճշմարիտ է։","58":"Երբ քո հակառակորդի հետ իշխանավորի մոտ ես գնում, ճանապարհին ջանա՛, որպեսզի հաշտվես նրա հետ, որովհետև գուցե քեզ դատավորի մոտ քարշ տա, դատավորը քեզ բանտապահին հանձնի, բանտապահն էլ բանտ գցի։","59":"Ասում եմ քեզ. այնտեղից դուրս չես գա, մինչև վերջին լուման էլ չվճարես»։"},"13":{"1":"Նույն ժամանակ ոմանք եկան ու պատմեցին այն գալիլեացիների մասին, որոնց Պիղատոսը սպանեց զոհաբերություն մատուցելու ժամին և այդ կերպ նրանց արյունը խառնեց զոհաբերված կենդանիների արյան հետ։","2":"Հիսուսը նրանց ասաց. «Կարծում եք, թե այդ գալիլեացիները, որ այդպիսի բաներ քաշեցին, ավելի մեղավո՞ր էին մյուս գալիլեացիներից։","3":"Ո՛չ, ասում եմ ձեզ. բայց եթե չապաշխարեք, բոլորդ էլ այդպես կկորչեք։","4":"Կամ այն տասնութ հոգին, որոնց վրա Սիլովամում աշտարակը փլվեց ու սպանեց նրանց։ Կարծում եք, թե նրանք Երուսաղեմում բնակվողներից ավելի հանցավո՞ր էին։","5":"Ո՛չ, ասում եմ ձեզ. բայց եթե չապաշխարեք, բոլորդ էլ այդպես կկորչեք»։","6":"Այս առակն էլ ասաց. «Մի մարդ իր այգում մի թզենի էր տնկել։ Գնաց նրա վրայից պտուղ հավաքելու, բայց չգտավ։","7":"Եվ այգեպանին ասաց. \"Ահա երեք տարի է, ինչ գալիս եմ այդ թզենու վրայից պտուղ հավաքելու, բայց չեմ գտնում. կտրի՛ր այն, ինչո՞ւ հողը զբաղեցնի\"։","8":"Իսկ նա պատասխանեց. \"Տե՛ր, այս տարի էլ թող դրան, մինչև որ չորս կողմը փորեմ ու գոմաղբ լցնեմ։","9":"Թերևս պտուղ տա, ապա թե ոչ եկող տարի կկտրես այն\"»։","10":"Հիսուսը շաբաթ օրը ժողովարաններից մեկում ուսուցանում էր։","11":"Եվ ահա մի կին կար, որ տասնութ տարուց ի վեր տառապում էր չար ոգուց. կծկված էր և բոլորովին չէր կարողանում ուղիղ կանգնել։","12":"Հիսուսը, նրան տեսնելով, իր մոտ կանչեց նրան ու ասաց. «Ո՛վ կին, քո հիվանդությունից ազատված ես»։","13":"Եվ ձեռքը նրա վրա դրեց. նա իսկույն ուղղվեց ու փառաբանում էր Աստծուն։","14":"Իսկ ժողովրդապետը, շատ բարկացած, որ Հիսուսը շաբաթ օրով բժշկեց, ժողովրդին ասաց. «Վեց օր կա, որոնց ընթացքում պետք է գործել. արդ այդ օրերի՛ն եկեք բուժվելու, այլ ոչ թե շաբաթ օրը»։","15":"Տերը նրան ասաց. «Կեղծավո՛ր, ձեզանից ամեն մեկը շաբաթ օրն իր եզը կամ էշը մսուրից չի՞ արձակում, տանում ջուր տալիս։","16":"Իսկ սա, Աբրահամի դուստր լինելով, որին սատանան ահա տասնութ տարի է, ինչ կապել էր, պետք չէ՞ր, որ շաբաթ օրն այդ կապանքից արձակվեր»։","17":"Եվ երբ նա այս ասաց, նրա բոլոր հակառակորդները ամոթահար եղան։ Եվ ամբողջ ժողովուրդն ուրախանում էր այն փառավոր գործերի համար, որ կատարվում էին նրա կողմից։","18":"Եվ ասաց. «Ինչի՞ է նման Աստծու արքայությունը, ինչի՞ նմանեցնեմ այն։","19":"Այն նման է մանանեխի հատիկի, որը մի մարդ առավ, իր պարտեզի մեջ ցանեց։ Մեծացավ ու մեծ ծառ դարձավ, և երկնքի թռչունները բույն էին դնում նրա ճյուղերի վրա»։","20":"Եվ դարձյալ ասաց. «Ինչի՞ նմանեցնեմ Աստծու արքայությունը։","21":"Այն նման է խմորի, որ մի կին վերցրեց ու երեք չափ ալյուրի մեջ թաթախեց, մինչև որ ամբողջը խմորվեց»։","22":"Հիսուսը շրջում էր քաղաքից քաղաք ու գյուղից գյուղ և ուսուցանում էր։ Եվ ճանապարհ էր ընկել դեպի Երուսաղեմ։","23":"Մեկը նրան ասաց. «Տե՛ր, մի՞թե փրկվողները քիչ են»։ Իսկ նա ասաց նրանց.","24":"«Ջանացեք նե՛ղ դռնով ներս մտնել, որովհետև, ասում եմ ձեզ, շատերը կուզենան մտնել, բայց չեն կարողանա։","25":"Երբ ժամանակը գա, տանտերը կելնի, դուռը կփակի, և դրսում կանգնած՝ կսկսեք դուռը բախել ու ասել. \"Տե՛ր, Տե՛ր, բա՛ց մեզ համար\"։ Եվ նա պատասխանելով կասի ձեզ. \"Չգիտեմ, թե որտեղի՛ց եք\"։","26":"Այն ժամանակ կսկսեք ասել. \"Մենք քո առաջ կերանք ու խմեցինք, և դու մեր հրապարակներում ուսուցանեցիր\"։","27":"Եվ կասի. \"Ձեզ ասում եմ. ես ձեզ չեմ ճանաչում, թե որտեղի՛ց եք, հեռացե՛ք ինձանից, բոլո՛ր անիրավություն գործողներդ։","28":"Այնտեղ կլինի լաց և ատամների կրճտոց, երբ Աբրահամին, Իսահակին, Հակոբին ու բոլոր մարգարեներին տեսնեք Աստծու արքայության մեջ, իսկ ձեզ՝ դուրս շպրտված։","29":"Եվ արևելքից, արևմուտքից, հյուսիսից ու հարավից կգան, Աստծու արքայության սեղանին կնստեն։","30":"Եվ ահա այդ ժամանակ վերջինները առաջիններ կլինեն, և առաջինները՝ վերջիններ»։","31":"Նույն օրը մի քանի փարիսեցիներ մոտեցան ու նրան ասացին. «Ե՛լ և գնա՛ այստեղից, որովհետև Հերովդեսն ուզում է քեզ սպանել»։","32":"Եվ նրանց ասաց. «Գնացեք այն աղվեսին ասե՛ք, որ այսօր և վաղը դևեր եմ հանում և բժշկություններ կատարում և երրորդ օրը կավարտեմ։","33":"Եվս երկու օր և երրորդ օրը կշարունակեմ իմ ճանապարհը, որովհետև մարգարեն Երուսաղեմից դուրս չի սպանվի։","34":"Երուսաղե՜մ, Երուսաղե՜մ՝ մարգարեներին կոտորող ու քեզ մոտ ուղարկվածներին քարկոծող. քանի՜ անգամ ցանկացա քո որդիներին հավաքել, ինչպես հավն է իր ձագերին թևերի տակ հավաքում, բայց չկամեցաք։","35":"Ահա ձեր տունը կավերվի, բայց ճշմարիտ եմ ասում ձեզ. այլևս ինձ չեք տեսնի, մինչև ժամանակը գա, որ ասեք. \"Օրհնյա՜լ է Տիրոջ անունով եկողը\" (Սաղ. 118.26)»։"},"14":{"1":"Երբ նա մի շաբաթ օր փարիսեցիների իշխանավորներից մեկի տուն մտավ հաց ուտելու, նրանք հսկում էին նրան։","2":"Եվ ահա նրա առաջ մի ջրգողյալ մարդ կար։","3":"Հիսուսը օրենսգետներին ու փարիսեցիներին ասաց. «Շաբաթ օրը բժշկություն անելն օրինավո՞ր է, թե՞ ոչ»։","4":"Նրանք լռեցին. Հիսուսը բժշկեց նրան ու արձակեց։","5":"Եվ նրանց ասաց. «Ձեզանից ո՞ւմ էշը կամ եզը ջրհորն ընկնի, և նա իսկույն չհանի նրան շաբաթ օրով»։","6":"Եվ այդ բանի համար չկարողացան պատասխանել նրան։","7":"Եվ հրավիրված այն մարդկանց էլ մի առակ պատմեց՝ տեսնելով, թե ինչպե՛ս են առաջին տեղերն ընտրում, ու նրանց ասաց.","8":"«Երբ մեկի կողմից հարսանիքի ես հրավիրվում, առաջին բազմոցին մի՛ նստիր. գուցե քեզանից առավել պատվավոր մեկը նրա կողմից հրավիրված լինի։","9":"Եվ նա, որ քեզ ու նրան հրավիրեց, գա ու քեզ ասի՝ \"Սրան տե՛ղ տուր\", այն ժամանակ կսկսես ամոթով վերջին տեղը գրավել։","10":"Այլ երբ հրավիրվես, գնա վերջի՛ն տեղը նստիր, որպեսզի երբ քեզ հրավիրողը գա ու քեզ ասի՝ \"Բարեկա՛մ, ավելի վերև՛ նստիր\", այն ժամանակ քեզ հետ նստողների առաջ քեզ փառք կլինի։","11":"Որովհետև ամեն ոք, ով իր անձը բարձրացնում է, կխոնարհեցվի, իսկ ով իր անձը խոնարհեցնում է, կբարձրացվի»։","12":"Եվ իրեն հրավիրողին էլ ասաց. «Երբ ճաշ կամ ընթրիք ես տալիս, քո բարեկամներին մի՛ կանչիր, ո՛չ էլ քո եղբայրներին, ո՛չ էլ քո ազգականներին, ո՛չ էլ քո հարուստ հարևաններին. միգուցե նրանք էլ փոխարենը քեզ հրավիրեն, և հատուցում լինի քեզ։","13":"Այլ երբ հյուրասիրություն ես անում, կանչի՛ր աղքատներին, խեղերին, կաղերին, կույրերին։","14":"Եվ երանելի կլինես, որ բան չունեն, որ փոխարենը քեզ հատուցեն, որովհետև արդարների հարության ժամանակ քեզ հատուցում կլինի»։","15":"Երբ սեղանակիցներից մեկն այս բաները լսեց, նրան ասաց. «Երանի՜ նրան, ով Աստծու արքայության մեջ հաց կուտի»։","16":"Հիսուսն ասաց նրան. «Մի մարդ մեծ ընթրիք սարքեց և շատերի հրավիրեց։","17":"Ընթրիքի ժամանակ իր ծառային ուղարկեց, որ հրավիրվածներին ասի. \"Եկե՛ք, որովհետև ամեն ինչ արդեն պատրաստ է\"։","18":"Եվ բոլորն սկսեցին մեկ-մեկ հրաժարվել։ Առաջինը նրան ասաց. \"Ագարակ եմ գնել, պետք է գնամ այն տեսնեմ. խնդրում եմ քեզ, ինձ հրաժարվա՛ծ համարիր\"։","19":"Մյուսն ասաց. \"Հինգ լուծ եզ եմ գնել, գնում եմ, որ դրանք փորձեմ. խնդրում եմ քեզ, ինձ հրաժարվա՛ծ համարիր\"։","20":"Մյուսն էլ ասաց. \"Կին եմ առել, դրա համար չեմ կարող գալ\"։","21":"Ծառան եկավ, այս բաները պատմեց իր տիրոջը։ Այն ժամանակ տանտերը, բարկացած, իր ծառային ասաց. \"Շուտ գնա՛ քաղաքի հրապարակներն ու փողոցները և աղքատներին, խեղերին, կաղերին ու կույրերին այստե՛ղ բեր\"։","22":"Ծառան ասաց. \"Տե՛ր, ինչ հրամայեցիր, եղավ, և դեռ էլի տեղ կա\"։","23":"Եվ տերը ծառային ասաց. \"Դո՛ւրս արի ճանապարհներն ու արահետները և ստիպի՛ր, որ գան, որպեսզի իմ տունը լցվի։","24":"Որովհետև ասում եմ ձեզ, որ հրավիրված այն մարդկանցից ոչ մեկն իմ ընթրիքից չի ճաշակի\"»։","25":"Նրա հետ ժողովրդի մեծ բազմություններ էին գնում, և դառնալով՝ ասաց նրանց.","26":"«Եթե մեկն ինձ մոտ գա, բայց չհրաժարվի իր հորից ու մորից, կնոջից ու զավակներից, եղբայրներից ու քույրերից, նույնիսկ իր կյանքից, նա չի կարող իմ աշակերտը լինել։","27":"Եվ ով իր խաչը չվերցնի ու իմ հետևից չգա, նա չի կարող իմ աշակերտը լինել։","28":"Որովհետև ձեզանից ո՞վ է, որ կամենա աշտարակ շինել և նախ չնստի, ծախսը չհաշվի, թե ավարտելու համար բավական միջոց ունի՞։","29":"Գուցե երբ հիմքը գցի և չկարողանա ավարտել, բոլոր տեսնողներն սկսեն նրան ծաղրել","30":"ու ասել. \"Այս մարդն սկսեց կառուցել, բայց չկարողացավ ավարտել\"։","31":"Կամ ո՞ր թագավորն է, որ այլ թագավորի դեմ պատերազմելու գնալիս չի նստում նախ խորհուրդ անում, թե տասը հազարով կարո՞ղ է դեմ կանգնել նրան, ով քսան հազարով է իր վրա գալիս։","32":"Ապա թե ոչ, պատգամավոր կուղարկի ու կխնդրի, որ խաղաղություն հաստատի, քանի դեռ նա հեռու է։","33":"Արդ, այդպես էլ ձեզանից ամեն մեկը, եթե իր ամբողջ ունեցվածքից չհրաժարվի, չի կարող իմ աշակերտը լինել։","34":"Աղը լավ բան է. բայց եթե աղը իր համը կորցնի, ինչո՞վ այն կրկին ձեռք կբերի։","35":"Ո՛չ հողի համար է պիտանի, ո՛չ էլ գոմաղբի համար, արդ դուրս կգցեն այն։ Ով լսելու ականջ ունի, թող լսի»։"},"15":{"1":"Բոլոր մաքսավորներն ու մեղավորները մոտենում էին նրան, որ լսեին։","2":"Փարիսեցիներն ու դպիրները տրտնջում էին ու ասում. «Սա մեղավորներին ընդունում է ու նրանց հետ ուտում»։","3":"Եվ նա այս առակն ասաց նրանց.","4":"«Ձեզանից ո՞վ հարյուր ոչխար ունենա և եթե դրանցից մեկը կորցնի, իննսունինը անապատում չի թողնի և կորածի հետևից չի գնա, մինչև որ այն գտնի։","5":"Եվ երբ գտնի, ուրախացած նրան իր ուսերին կդնի","6":"և տուն գալով՝ բարեկամներին ու հարևաններին կկանչի ու նրանց կասի. \"Ինձ հետ ուրախացե՛ք, որովհետև իմ կորած ոչխարը գտա\"։","7":"Ասում եմ ձեզ, որ այդպես էլ երկնքում ուրախություն կլինի մեկ մեղավորի համար, որ ապաշխարի, քան իննսունինը արդարների համար, որոնք ապաշխարության կարիք չունեն։","8":"Կամ ո՞ր կինը, որ տասը դրամ ունենա և եթե մեկ դրամ կորցնի, ճրագ չի վառի, տունն ավլի ու ուշադիր փնտրի, մինչև գտնի։","9":"Եվ երբ գտնի, բարեկամներին ու հարևաններին կկանչի ու կասի. \"Ինձ հետ ուրախացե՛ք, որովհետև գտա դրամը, որ կորցրել էի\"։","10":"Ասում եմ ձեզ. այդպես էլ Աստծու հրեշտակների մոտ ուրախություն կլինի մեկ ապաշխարած մեղավորի համար»։","11":"Դարձյալ ասաց. «Մի մարդ երկու որդի ուներ։","12":"Նրանցից կրտսերը հորն ասաց. \"Հա՛յր, տո՛ւր ինձ ունեցվածքիցդ ինձ հասնող բաժինը\"։ Եվ նա ունեցվածքը բաժանեց նրանց։","13":"Մի քանի օր հետո կրտսեր որդին ամեն ինչ հավաքեց, հեռու երկիր գնաց ու այնտեղ իր ունեցածը վատնեց՝ անառակությամբ ապրելով։","14":"Եվ երբ ամբողջն սպառեց, այդ երկրում սաստիկ սով եղավ, ինքն էլ սկսեց չքավոր դառնալ։","15":"Եվ գնաց, այդ երկրի քաղաքացիներից մեկին դիմեց, և սա նրան իր ագարակն ուղարկեց, որ խոզ արածեցնի։","16":"Նա ցանկանում էր իր որովայնը լցնել եղջերենու պտուղներով, որ խոզերն էին ուտում, բայց ոչ ոք նրան չէր տալիս։","17":"Եվ սթափվելով՝ ասաց. \"Քանի՜ վարձկաններ հորս մոտ առատ հաց ունեն, իսկ ես այստեղ սովամահ կորչում եմ։","18":"Վեր կենամ հորս մոտ գնամ ու նրան ասեմ. \"Հա՛յր, մեղանչեցի երկնքի ու քո առաջ։","19":"Այլևս քո որդին կոչվելու արժանի չեմ. ինձ քո վարձկաններից մե՛կն արա\"։","20":"Եվ վեր կացավ իր հոր մոտ եկավ։ Ու երբ նա դեռ հեռու էր, հայրը նրան տեսավ և գթաց. վազեց, նրա վզովն ընկավ ու համբուրեց նրան։","21":"Եվ որդին նրան ասաց. \"Հա՛յր, մեղանչեցի երկնքի ու քո առաջ։ Այլևս քո որդին կոչվելու արժանի չեմ\"։","22":"Հայրն իր ծառաներին ասաց. \"Իսկույն բերե՛ք լավագույն պատմուճանը ու հագցրե՛ք նրան, մատին մատանի՛ դրեք և ոտքերին՝ կոշիկներ։","23":"Բերե՛ք պարարտ եզը, մորթե՛ք. ուտենք, ուրախ լինենք,","24":"որովհետև իմ այս որդին մեռած էր ու կենդանացավ, կորած էր ու գտնվեց\"։ Եվ սկսեցին զվարճանալ։","25":"Իսկ նրա ավագ որդին դաշտում էր։ Մինչ գալիս էր, մոտեցավ տանը, երգերի ու պարերի ձայն լսեց։","26":"Իր մոտ կանչելով ծառաներից մեկին՝ հարցրեց, թե ի՛նչ է այդ։","27":"Նա էլ ասաց նրան. \"Եղբայրդ եկել է, հայրդ էլ պարարտ եզ մորթեց, որովհետև նրան ողջ և առողջ ընդունեց\"։","28":"Նա բարկացավ ու չէր ուզում ներս մտնել, բայց հայրը, դուրս ելնելով, աղաչում էր նրան։","29":"Իսկ նա հորն ասաց. \"Ահա այսքան տարի է, ինչ ծառայում եմ քեզ և քո հրամանները երբեք չեմ անտեսել, բայց ինձ երբեք մի ուլ չտվեցիր, որ իմ բարեկամների հետ ուրախություն անեմ։","30":"Իսկ երբ քո այդ որդին եկավ, որ քո ունեցվածքը պոռնիկների հետ կերավ, նրա համար պարարտ եզ մորթեցիր\"։","31":"Հայրն ասաց նրան. \"Որդյա՛կ, դու միշտ ինձ հետ ես, և ամեն ինչ, որ իմն է, քոնն է։","32":"Բայց պետք է ուրախ լինել ու խնդալ, որովհետև քո այս եղբայրը մեռած էր ու կենդանացավ, կորած էր ու գտնվեց\"»։"},"16":{"1":"Հիսուսն աշակերտներին ասաց. «Մի հարուստ մարդ կար, որ մի տնտես ուներ։ Նրանից գանգատվեցին հարուստին, իբր նրա ունեցվածքը վատնում է։","2":"Եվ նրան կանչեց ու ասաց. \"Այս ի՞նչ եմ լսում քո մասին. հաշի՛վ տուր քո տնտեսության վերաբերյալ, որովհետև այլևս տնտես չես կարող լինել\"։","3":"Տնտեսն իր մտքում ասաց. \"Ի՞նչ եմ անելու, քանի որ իմ տերը տնտեսությունն իմ ձեռքից վերցնում է. հերկել չեմ կարող, մուրալ ամաչում եմ։","4":"Գիտեմ, թե ինչ կանեմ, որպեսզի ինձ իրենց տներն ընդունեն, երբ տնտեսությունից հանվեմ\"։","5":"Եվ իր տիրոջ պարտապաններին մեկ առ մեկ իր մոտ կանչեց և առաջինին ասաց. \"Իմ տիրոջն ինչքա՞ն ես պարտք\"։","6":"Նա ասաց. \"Հարյուր մար ձեթ\"։ Նրան ասաց. \"Ա՛ռ մուրհակդ, նստի՛ր ու անմիջապես գրի՛ր՝ հիսուն\"։","7":"Հետո մյուսին ասաց. \"Դո՞ւ ինչքան ես պարտք\"։ Նա էլ ասաց. \"Հարյուր քոռ ցորեն\"։ Եվ նրան ասաց. \"Ա՛ռ մուրհակդ ու գրի՛ր՝ ութսուն\"։","8":"Եվ տերը գովեց անիրավ տնտեսին, որ հնարամտությամբ է գործել, որովհետև այս աշխարհի որդիները, իրենց նմանների հետ կապի մեջ լինելով, լույսի որդիներից ավելի հնարամիտ են։","9":"Եվ ես ձեզ ասում եմ. անիրավ մամոնայից ձեզ համար բարեկամնե՛ր սարքեք, որ երբ այն պակասի, հավիտենական բնակարանների մեջ ձեզ ընդունեն։","10":"Քիչ բանի մեջ հավատարիմը շատի մեջ էլ է հավատարիմ, և քիչ բանի մեջ անիրավը շատի մեջ էլ է անիրավ։","11":"Արդ եթե անիրավ մամոնայի մեջ հավատարիմ չեղաք, ո՞վ ձեզ ճշմարիտը կվստահի։","12":"Եթե օտարին պատկանողի մեջ հավատարիմ չեղաք, ձեզ պատկանողը ո՞վ կտա ձեզ։","13":"Ոչ մի ծառա չի կարող երկու տիրոջ ծառայել, որովհետև կա՛մ մեկին կատի, մյուսին կսիրի, կա՛մ մեկին կպատվի, մյուսին կարհամարհի։ Չեք կարող ծառայել և՛ Աստծուն, և՛ մամոնային»։","14":"Այս բոլոր բաները լսում էին փարիսեցիները, որ արծաթասեր էին ու ծաղրում էին նրան։","15":"Եվ նրանց ասաց. «Դուք եք, որ մարդկանց առաջ ձեզ արդար եք ցույց տալիս, բայց Աստված գիտե ձեր սրտերը, որովհետև մարդկանց առաջ բարձրն Աստծու առաջ պիղծ է։","16":"Օրենքն ու մարգարեները մինչև Հովհաննեսն են. նրանից հետո քարոզվում է Աստծու արքայությունը, և ամեն ոք շտապում է այնտեղ մտնել։","17":"Սակայն ավելի հեշտ է, որ երկինքն ու երկիրը անցնեն, քան օրենքի մի փոքր նշանագիրն անգամ չիրագործվի։","18":"Ամեն ոք, ով արձակում է իր կնոջը և ուրիշին առնում, շնանում է, և ով ամուսնու կողմից արձակված կին է առնում, շնանում է։","19":"Մի հարուստ մարդ կար, որ ծիրանի ու բեհեզ էր հագնում և ամեն օր շքեղ խնջույք էր անում։","20":"Մի աղքատ մարդ էլ կար՝ Ղազարոս անունով, որ վերքերով ծածկված՝ նրա դռան առաջ ընկած էր","21":"և ցանկանում էր հագենալ այն փշրանքներով, որ թափվում էին հարուստի սեղանից. շներն էլ գալիս էին, լիզում նրա վերքերը։","22":"Երբ աղքատը մեռավ, հրեշտակները նրան Աբրահամի գոգը տարան. հարուստն էլ մեռավ ու թաղվեց։","23":"Եվ դժոխքում, մինչ տանջանքների մեջ էր, բարձրացրեց իր աչքերը, հեռվից տեսավ Աբրահամին, Ղազարոսին էլ՝ նրա գրկում։","24":"Նա աղաղակեց ու ասաց. \"Հա՛յր Աբրահամ, ողորմի՛ր ինձ և ուղարկի՛ր Ղազարոսին, որ իր մատի ծայրը ջրով թրջի և լեզուս հովացնի, որովհետև այս կրակի բոցի մեջ տանջվում եմ\"։","25":"Իսկ Աբրահամն ասաց. \"Որդյա՛կ, հիշի՛ր, որ դու ստացար քո բարիքները քո կյանքի ընթացքում, իսկ Ղազարոսն էլ՝ չարիքները։ Հիմա սա այստեղ մխիթարվում է, իսկ դու տանջվում ես։","26":"Եվ այդ բոլորից բացի, մեր ու ձեր միջև մեծ անդունդ է հաստատված, որպեսզի այստեղից ձեզ մոտ անցնել ուզողները չկարողանան, ոչ էլ այդտեղից մեզ մոտ անցնեն\"։","27":"Եվ ասաց. \"Ուրեմն աղաչում եմ քեզ, հա՛յր, որ դրան իմ հոր տուն ուղարկես,","28":"որովհետև ես հինգ եղբայր ունեմ. թող նրանց վկայություն տա, որ նրանք էլ տանջանքի այս վայրը չգան\"։","29":"Աբրահամը նրան ասաց. \"Նրանք Մովսեսին ու մարգարեներին ունեն. թող նրանց լսեն\"։","30":"Իսկ նա ասաց. \"Ո՛չ, հա՛յր Աբրահամ. բայց եթե մեռելներից մեկը նրանց մոտ գնա, կապաշխարեն\"։","31":"Եվ նրան ասաց. \"Եթե Մովսեսին ու մարգարեներին չեն լսում, չեն էլ համոզվի, եթե մեռելներից մեկը հարություն առնի\"»։"},"17":{"1":"Հիսուսն ասաց իր աշակերտներին. «Անկարելի է, որ գայթակղություններ չգան, բայց վա՛յ նրան, ում միջոցով կգան։","2":"Նրա համար ավելի լավ է, եթե իր պարանոցից մի երկանաքար կախվի, ու ծովը գցվի, քան թե այս փոքրերից մեկին գայթակղեցնի։","3":"Ձեր անձերի համա՛ր զգուշացեք։ Եղբայրական անհիշաչարություն Եթե քո եղբայրը քո դեմ մեղանչի, նրան հանդիմանի՛ր, ու եթե ապաշխարի, նրան ների՛ր։","4":"Եթե քո դեմ օրը յոթ անգամ մեղանչի ու յոթ անգամ քեզ մոտ դառնա և ասի՝ զղջում եմ, ների՛ր նրան»։","5":"Եվ առաքյալները Տիրոջն ասացին. «Ավելացրո՛ւ մեր հավատը»։","6":"Տերն ասաց. «Եթե մանանեխի հատիկի չափ հավատ ունենաք և այս թթենուն ասեք՝ \"Պոկվի՛ր ու ծովի մե՛ջ տնկվիր\", նա ձեզ կհնազանդվի։","7":"Բայց ձեզանից ո՞վ, որ մի հողագործ կամ հովիվ ծառա ունենա ու երբ դաշտից տուն մտնի, նրան իսկույն կասի. \"Եկ սեղա՛ն նստիր\"։","8":"Այլ նրան չի՞ ասի. \"Պատրաստի՛ր, ինչ որ ընթրելու եմ, գոտի կապած՝ ինձ ծառայի՛ր, մինչև ուտեմ ու խմեմ, հետո դու էլ կուտես ու կխմես\"։","9":"Մի՞թե ծառային պետք է շնորհակալ լինի, որ իրեն հրամայված այդ գործերն անի։","10":"Այդպես էլ դուք, երբ ձեզ հրամայված բոլոր բաներն անեք, ասե՛ք. \"Մենք անպիտան ծառաներ ենք. ինչ որ պարտավոր էինք անել, արեցինք\"»։","11":"Երբ նա Երուսաղեմ էր գնում, Սամարիայի ու Գալիլեայի միջով էր անցնում։","12":"Եվ մի գյուղ մտնելիս նրան տասը բորոտներ հանդիպեցին, որոնք հեռու կանգնեցին","13":"և բարձրաձայն ասացին. «Հիսո՛ւս, Վարդապե՛տ, ողորմի՛ր մեզ»։","14":"Երբ տեսավ, նրանց ասաց. «Գնացե՛ք, ձեզ քահանաների՛ն ցույց տվեք»։ Եվ նրանք գնալիս մաքրվեցին։","15":"Նրանցից մեկը, երբ տեսավ, որ բժշկվեց, վերադարձավ՝ բարձրաձայն փառաբանելով Աստծուն։","16":"Նա երեսնիվայր ընկավ Հիսուսի ոտքերի առաջ և գոհություն էր հայտնում, և ինքը սամարացի էր։","17":"Հիսուսը պատասխանեց և ասաց. «Չէ՞ որ տասն էլ մաքրվեցին, արդ այն ինը որտե՞ղ են։","18":"Վերադարձողներ չգտնվեցի՞ն Աստծուն փառք տալու համար, բացի այս այլազգուց»։","19":"Եվ նրան ասաց. «Վեր կաց գնա՛, քո հավատը փրկեց քեզ»։","20":"Երբ փարիսեցիների կողմից հարց տրվեց, թե Աստծու արքայությունը ե՛րբ է գալու, նրանց պատասխանեց ու ասաց. «Աստծու արքայությունը տեսանելի նշանով չի գալու,","21":"ոչ էլ կասեն. \"Ահա այստեղ է կամ ահա այնտեղ է\". որովհետև ահա Աստծու արքայությունը հենց ձեր ներսում է»։","22":"Իսկ աշակերտներին ասաց. «Կգան օրեր, երբ կուզենաք Մարդու Որդու օրերից մեկը տեսնել ու չեք տեսնի։","23":"Ձեզ կասեն. \"Ահա այստեղ է կամ ահա այնտեղ է\"։ Չգնաք ու չհետևեք։","24":"Որովհետև ինչպես ճայթող կայծակն է փայլատակում հորիզոնի մի ծայրից մյուսը, այնպես էլ կլինի Մարդու Որդին իր օրը։","25":"Բայց նախ պետք է, որ նա շատ չարչարվի և այս սերնդի կողմից մերժվի։","26":"Եվ ինչպես որ Նոյի օրերին եղավ, այնպես էլ Մարդու Որդու օրերին կլինի։","27":"Ուտում էին, խմում, կին էին առնում և մարդու գնում մինչև այն օրը, երբ Նոյը տապան մտավ, ջրհեղեղը եկավ ու բոլորին կորստյան մատնեց։","28":"Նույն ձևով, ինչպես Ղովտի օրերին էլ եղավ. ուտում էին, խմում, առնում էին, վաճառում, տնկում էին, կառուցում։","29":"Եվ այն օրը, երբ Ղովտը Սոդոմից դուրս ելավ, երկնքից հուր ու ծծումբ տեղաց և բոլորին կորստյան մատնեց։","30":"Նույն կերպ էլ այն օրը կլինի, երբ Մարդու Որդին հայտնվի։","31":"Այդ օրն ով տանիքին լինի, իսկ կարասին՝ տան մեջ, թող չիջնի դրանք վերցնելու. դաշտում եղողն էլ թող հետ չդառնա։","32":"Հիշե՛ք Ղովտի կնոջը։","33":"Ով իր անձը փրկել ուզենա, այն կկորցնի, իսկ ով այն կորցնի, կփրկվի։","34":"Ասում եմ ձեզ. այդ գիշերը երկու հոգի մի անկողնում կլինեն. մեկը կվերցվի, մյուսը կթողնվի։","35":"Երկու կին միասին աղալիս կլինեն. մեկը կվերցվի, մյուսը կթողնվի»։","37":"Եվ պատասխանեցին նրան ու ասացին. «Որտե՞ղ, Տե՛ր»։ Հիսուսն էլ ասաց նրանց. «Որտեղ մարմինն է, արծիվներն այնտեղ էլ կհավաքվեն»։"},"18":{"1":"Նրանց մի առակ էլ ասաց այն մասին, որ պետք է ամեն ժամ աղոթել ու չվհատվել։","2":"Եվ ասաց. «Մի քաղաքում մի դատավոր կար, որ Աստծուց չէր վախենում և մարդկանցից չէր ամաչում։","3":"Այդ քաղաքում մի այրի կար, որ նրա մոտ էր գալիս ու ասում. \"Իմ հակառակորդի դիմաց արդարադա՛տ եղիր իմ հանդեպ\"։","4":"Եվ նա երկար ժամանակ չէր կամենում. դրանից հետո իր մտքում ասաց. \"Թեև Աստծուց չեմ վախենում և մարդկանցից էլ չեմ ամաչում,","5":"սակայն քանի որ այս այրին ինձ հոգնեցնում է, նրա դատն անեմ, որ անվերջ չգա ինձ ձանձրացնի\"»։","6":"Եվ Տերն ասաց. «Լսե՛ք, թե անիրավ դատավորն ի՛նչ է ասում։","7":"Իսկ Աստված մի՞թե իր ընտրյալներին արդարություն չի անի, որոնք գիշեր-ցերեկ աղաղակում են նրան, նույնիսկ եթե ուշացնում է։","8":"Ասում եմ ձեզ. շուտով նրանց հանդեպ արդարություն կանի։ Սակայն երբ Մարդու Որդին գա, երկրի վրա արդյոք հավատ կգտնի՞»։","9":"Ոմանց էլ, որոնք համոզված էին, որ իրենք արդար են, և ուրիշներին արհամարհում էին, այս առակն ասաց.","10":"«Երկու մարդ տաճար ելան աղոթելու. մեկը՝ փարիսեցի, մյուսը՝ մաքսավոր։","11":"Փարիսեցին, առանձին կանգնած, այս աղոթքն էր անում. \"Ո՛վ Աստված, շնորհակալ եմ քեզանից, որ ես ուրիշ մարդկանց պես չեմ, ինչպես հափշտակողները, անիրավները, շնացողները և կամ ինչպես այս մաքսավորը։","12":"Շաբաթը երկու անգամ ծոմ եմ պահում և տասանորդ եմ տալիս այն ամենից, ինչ ունեմ\"։","13":"Իսկ մաքսավորը, հեռու կանգնած, չէր էլ կամենում աչքերը երկինք բարձրացնել, այլ ծեծում էր իր կուրծքը և ասում. \"Ո՛վ Աստված, ողորմի՛ր ինձ՝ մեղավորիս\"։","14":"Ասում եմ ձեզ, որ մաքսավորը արդարացած իջավ իր տուն, որովհետև ամեն ոք, ով ինքն իրեն բարձրացնում է, կխոնարհվի, իսկ ով ինքն իրեն խոնարհեցնում է, կբարձրացվի»։","15":"Մանուկներին էլ էին նրա մոտ բերում, որպեսզի նրանց դիպչի։ Աշակերտները, այդ տեսնելով, սաստում էին նրանց։","16":"Բայց Հիսուսը մանուկներին իր մոտ կանչեց ու ասաց. «Թո՛ւյլ տվեք մանուկներին ինձ մոտ գալ և մի՛ արգելեք նրանց, քանի որ Աստծու արքայությունն այդպիսիներինն է։","17":"Ճշմարիտ եմ ասում ձեզ. ով Աստծու արքայությունն ինչպես մի մանուկ չընդունի, նա այնտեղ չի մտնի»։","18":"Մի իշխանավոր հարցրեց նրան ու ասաց. «Բարի՛ Վարդապետ, ի՞նչ անեմ, որ հավիտենական կյանքը ժառանգեմ»։","19":"Հիսուսը նրան ասաց. «Ինձ ինչո՞ւ ես \"բարի\" անվանում. ոչ ոք բարի չէ, բացի մեկից՝ Աստծուց։","20":"Պատվիրանները գիտես՝ \"Մի՛ շնանա, մի՛ սպանիր, մի՛ գողացիր, սուտ մի՛ վկայիր, պատվի՛ր քո հորն ու մորը\" (Ելք 20.14, 13, 15-16, 12, Բ Օր. 5.18, 17, 19-20, 16)»։","21":"Նա էլ ասաց. «Այդ բոլորն իմ մանկությունից պահել եմ»։","22":"Երբ Հիսուսը այս լսեց, նրան ասաց. «Քեզ տակավին մի բան է պակասում. ինչ ունես, վաճառի՛ր ու աղքատների՛ն բաժանիր և երկնքում գանձ կունենաս. և արի՛ ու ի՛նձ հետևիր»։","23":"Նա էլ, այս լսելով, տրտմեց, որովհետև չափազանց հարուստ էր։","24":"Հիսուսը, նրան տրտմած տեսնելով, ասաց. «Ինչքա՜ն դժվարությամբ Աստծու արքայություն կմտնեն նրանք, որոնք հարստություն ունեն։","25":"Ավելի հեշտ է, որ ուղտն ասեղի ծակով անցնի, քան հարուստն Աստծու արքայություն մտնի»։","26":"Եվ նրանք, որ լսեցին, ասում էին. «Իսկ ո՞վ կարող է փրկվել»։","27":"Նա ասաց. «Ինչ որ անհնար է մարդկանց համար, Աստծու համար հնարավոր է»։","28":"Պետրոսն ասաց. «Ահա մենք ամեն ինչ թողեցինք ու քո հետևից եկանք»։","29":"Իսկ նա ասաց նրանց. «Ճշմարիտ եմ ասում ձեզ. չկա մեկը, որ Աստծու արքայության համար տուն կամ ծնողներ, կամ եղբայրներ, կամ կին, կամ զավակներ թողած լինի","30":"և բազմապատիկը չստանա այս ներկա ժամանակում և հավիտենական կյանք՝ այն գալիք աշխարհում»։","31":"Իր հետ վերցնելով տասներկուսին՝ ասաց նրանց. «Ահա ելնում ենք Երուսաղեմ, և մարգարեների միջոցով Մարդու Որդու մասին բոլոր գրվածները պիտի կատարվեն,","32":"որովհետև պիտի մատնվի հեթանոսներին, պիտի ծաղրվի, նախատվի, և նրա վրա պիտի թքեն։","33":"Ձաղկելով պիտի սպանեն նրան, և երրորդ օրը հարություն պիտի առնի»։","34":"Նրանք այս բաներից ոչինչ չհասկացան, և այս խոսքը նրանցից ծածկված էր, ու ասածները չէին հասկանում։","35":"Երբ նա Երիքովին էր մոտենում, մի կույր, ճանապարհին նստած, մուրում էր։","36":"Երբ ժողովրդի անցնելը լսեց, հարցրեց, թե այդ ի՛նչ է։","37":"Նրան հայտնեցին, որ Հիսուս Նազովրեցին է անցնում։","38":"Եվ նա աղաղակեց ու ասաց. «Հիսո՛ւս, Դավթի՛ որդի, ողորմի՛ր ինձ»։","39":"Նրանք, որ առջևից էին գնում, նրան սաստում էին, որ լռի. իսկ նա ավելի էր աղաղակում. «Դավթի՛ որդի, ողորմի՛ր ինձ»։","40":"Հիսուսը կանգ առավ ու հրամայեց, որ նրան իր մոտ բերեն։ Երբ իրեն մոտեցավ, նրան հարցրեց ու ասաց.","41":"«Ի՞նչ ես ուզում, որ անեմ քեզ համար»։ Նա ասաց. «Տե՛ր, ուզում եմ տեսնել»։","42":"Հիսուսը նրան ասաց. «Տե՛ս. քո հավատը քեզ փրկեց»։","43":"Եվ իսկույն տեսավ ու գնում էր նրա հետևից՝ Աստծուն փառաբանելով։ Եվ ամբողջ ժողովուրդը, տեսնելով, գովաբանում էր Աստծուն։"},"19":{"1":"Հիսուսը մտավ Երիքով և անցնում էր նրա միջով։","2":"Եվ ահա մի մարդ՝ Զակքեոս անունով, որ մաքսապետ էր և հարուստ,","3":"ուզում էր տեսնել, թե ով է Հիսուսը, բայց բազմության պատճառով չէր կարողանում, որովհետև կարճահասակ էր։","4":"Առաջ վազելով՝ մի ժանտաթզենու վրա բարձրացավ, որպեսզի նրան տեսնի, որովհետև այդտեղով էր անցնելու։","5":"Երբ այդ տեղը եկավ, Հիսուսը վեր նայեց ու նրան ասաց. «Զակքեո՛ս, շտապի՛ր, իջի՛ր, որովհետև այսօր պետք է քո տանը մնամ»։","6":"Նա շտապ իջավ ու նրան ուրախությամբ ընդունեց։","7":"Բոլորը, տեսնելով, տրտնջում էին ու ասում. «Մեղավոր մարդու մոտ մտավ հանգիստ առնելու»։","8":"Զակքեոսը կանգնեց ու Տիրոջն ասաց. «Տե՛ր, իմ ունեցվածքի կեսն աղքատներին կտամ ու եթե մեկին զրպարտությամբ զրկել եմ, քառապատիկ կվճարեմ»։","9":"Հիսուսը նրան ասաց. «Այսօր այս տան համար փրկություն եղավ, որովհետև սա ևս Աբրահամի որդի է,","10":"որովհետև Մարդու Որդին եկել է կորածին փնտրելու ու փրկելու»։","11":"Եվ մինչ նրանք լսում էին այս բաները, մի առակ էլ հավելեց, որովհետև Երուսաղեմին էր մոտենում, և նրանք կարծում էին, թե Աստծու արքայությունը շուտով հայտնվելու է։","12":"Արդ ասաց. «Մի ազնվական մարդ հեռու երկիր գնաց, որպեսզի իր թագավորությունը ստանա ու վերադառնա։","13":"Կանչելով իր տասը ծառաներին՝ նրանց տասը մնաս տվեց ու ասաց. \"Շահարկե՛ք, մինչև գամ\"։","14":"Բայց նրա համաքաղաքացիները ատում էին նրան. պատգամավորներ ուղարկեցին նրա հետևից և ասացին. \"Չենք ուզում, որ դա մեզ վրա թագավորի\"։","15":"Եվ նա, թագավորությունը ստացած, վերադարձավ ու ասաց, որ կանչեն այն ծառաներին, որոնց արծաթ էր տվել, որպեսզի իմանա, թե ով ի՛նչ է շահել։","16":"Առաջինը եկավ ու ասաց. \"Տե՛ր, քո մնասը տասը մնաս շահ բերեց\"։","17":"Նրան ասաց. \"Լա՛վ, բարի՛ ծառա, քանի որ քիչ բանում հավատարիմ եղար, տասը քաղաքի վրա իշխանությո՛ւն ունեցիր\"։","18":"Երկրորդը եկավ ու ասաց. \"Տե՛ր, քո մնասը հինգ մնաս շահ բերեց\"։","19":"Նրան էլ ասաց. \"Դու էլ հինգ քաղաքի վրա՛ եղիր\"։","20":"Մյուսն էլ եկավ ու ասաց. \"Տե՛ր, ահա քո մնասը, որ թաշկինակի մեջ փաթաթած պահում էի։","21":"Վախենում էի քեզանից, որովհետև դու խիստ մարդ ես. վերցնում ես, ինչ որ չես դրել, և հնձում ես, ինչ որ չես ցանել\"։","22":"Եվ նրան ասաց. \"Քո բերանով եմ քեզ դատելու, չա՛ր ծառա։ Գիտեիր, որ ես խիստ մարդ եմ, վերցնում եմ, ինչ որ չեմ դրել, հնձում եմ, ինչ որ չեմ ցանել.","23":"այդ ինչո՞ւ իմ արծաթը լումայափոխներին չտվեցիր, որ ես երբ գայի, այն շահով հետ առնեի\"։","24":"Եվ ներկա գտնվողներին ասաց. \"Վերցրե՛ք դրանից մնասը ու տվե՛ք տասը մնաս ունեցողին\"։","25":"Նրան ասացին. \"Տե՛ր, նա արդեն տասը մնաս ունի\"։","26":"\"Ասում եմ ձեզ, որ ամեն ունեցողի կտրվի, իսկ չունեցողից, ինչ էլ որ ունի, կվերցվի։","27":"Իսկ իմ այն թշնամիներին, որոնք չէին ուզում, որ ես իրենց վրա թագավորեմ, այստե՛ղ բերեք ու իմ առաջ սպանե՛ք\"»։","28":"Եվ երբ այս ասաց, առաջացավ, որ Երուսաղեմ ելնի։","29":"Երբ մոտեցավ Բեթփագեին ու Բեթանիային՝ Ձիթենյաց կոչվող լեռան մոտ, իր աշակերտներից երկուսին ուղարկեց","30":"ու ասաց. «Գնացե՛ք դիմացի գյուղը ու այնտեղ մտնելիս մի կապած ավանակ կգտնեք, որի վրա երբեք ոչ մի մարդ չի նստել. արձակե՛ք այն ու բերե՛ք։","31":"Եվ եթե մեկը ձեզ հարցնի՝ \"Ինչո՞ւ եք արձակում\", նրան այսպե՛ս ասեք՝ \"Տերը դրա կարիքն ունի\"»։","32":"Երբ ուղարկվածները գնացին, գտան այնպես, ինչպես իրենց ասել էր։","33":"Մինչ նրանք ավանակն էին արձակում, նրա տերերը նրանց ասացին. «Ավանակն ինչո՞ւ եք արձակում»։","34":"Նրանք ասացին. «Տերը դրա կարիքն ունի»։","35":"Եվ այն բերեցին Հիսուսի մոտ, իրենց հագուստներն էլ ավանակի վրա գցեցին և Հիսուսին վրան նստեցրին։","36":"Մինչ նա գնում էր, իրենց հագուստները փռում էին ճանապարհի վրա։","37":"Եվ երբ նա արդեն Ձիթենյաց լեռան զառիվայրին մոտեցավ, աշակերտների ամբողջ բազմությունն ուրախությամբ սկսեց բարձր ձայնով Աստծուն օրհնել այն բոլոր հրաշքների համար, որ տեսել էր։","38":"Եվ ասում էին. «Օրհնյա՜լ է Տիրոջ անունով եկող թագավորը (Սաղ. 118.26). խաղաղությո՜ւն երկնքում, ու փա՜ռք Բարձրյալին»։","39":"Փարիսեցիներից ոմանք բազմության միջից ասացին նրան. «Վարդապե՛տ, աշակերտներիդ սաստի՛ր»։","40":"Նա պատասխանեց ու ասաց. «Ասում եմ ձեզ, որ եթե դրանք լռեն, քարերն են աղաղակելու»։","41":"Եվ երբ մոտեցավ, քաղաքը տեսնելով՝ լաց եղավ նրա վրա","42":"ու ասաց. «Գոնե այսօր դու էլ իմանայիր ինչպե՛ս խաղաղություն գտնել։ Բայց հիմա այն քո աչքերից ծածկված է։","43":"Որովհետև քեզ վրա օրեր պիտի գան, ու թշնամիներդ շուրջդ պիտի պատնեշապատեն և քեզ պաշարեն, ամեն կողմից քեզ պիտի նեղեն։","44":"Քեզ զավակներիդ հետ հիմնահատակ պիտի անեն և քարդ քարի վրա չպիտի թողնեն, քանի որ չճանաչեցիր ժամանակը, երբ քեզ այցելության եկավ Տերը»։","45":"Հիսուսը, տաճար մտնելով, սկսեց դուրս հանել վաճառողներին ու գնողներին։","46":"Նրանց ասաց. «Գրված է. \"Իմ տունն աղոթքի տուն պիտի լինի\" (Ես. 56.7), իսկ դուք այն ավազակների որջի եք վերածել»։","47":"Եվ ամեն օր տաճարում ուսուցանում էր նրանց, իսկ քահանայապետները, դպիրներն ուզում էին նրան կորստյան մատնել։","48":"Եվ միջոց չէին գտնում, որովհետև ամբողջ ժողովուրդը, նրանով տարված, լսում էր։"},"20":{"1":"Այդ օրերին, երբ նա տաճարում ուսուցանում էր ժողովրդին և քարոզում, մի օր քահանայապետներն ու դպիրները երեցների հետ միասին վրա հասան","2":"և նրան ասացին. «Ասա՛ մեզ, այդ բաներն ի՞նչ իշխանությամբ ես անում, կամ ո՞վ է քեզ այդ իշխանությունը տվողը»։","3":"Եվ նա պատասխանեց նրանց ու ասաց. «Ես էլ ձեզ մի բան հարցնեմ, ու ինձ ասացե՛ք.","4":"Հովհաննեսի մկրտությունը երկնքի՞ց էր, թե՞ մարդկանցից»։","5":"Նրանք իրար մեջ խորհուրդ արեցին ու ասացին. «Եթե ասենք՝ երկնքից, կասի՝ \"Հապա ինչո՞ւ նրան չհավատացիք\",","6":"իսկ եթե ասենք՝ մարդկանցից, ամբողջ ժողովուրդը մեզ կքարկոծի, որովհետև համոզված է, որ Հովհաննեսը մարգարե է»։","7":"Եվ պատասխանեցին, որ չգիտեն, թե որտեղի՛ց է։","8":"Հիսուսը նրանց ասաց. «Ես էլ ձեզ չեմ ասի, թե ի՛նչ իշխանությամբ եմ այս բաներն անում»։","9":"Եվ սկսեց ժողովրդին այս առակն ասել. «Մի մարդ այգի տնկեց, այն մշակներին տվեց ու ինքը երկար ժամանակով օտարության գնաց։","10":"Երբ ժամանակը հասավ, մշակների մոտ մի ծառայի ուղարկեց, որ այգու պտղից իրեն տան. բայց մշակները նրան ծեծեցին ու դատարկ հետ ուղարկեցին։","11":"Դարձյալ մի ուրիշ ծառայի ևս ուղարկեց. նրանք սրան էլ ծեծեցին, անարգեցին ու դատարկ հետ ուղարկեցին։","12":"Եվ դարձյալ մի երրորդի էլ ուղարկեց. նրանք սրան էլ վիրավորելով դուրս հանեցին։","13":"Այգու տերն ասաց. \"Ի՞նչ անեմ. իմ սիրելի որդուն ուղարկեմ, գուցե նրան տեսնելով՝ ամաչեն\"։","14":"Բայց երբ մշակները նրան տեսան, իրար հետ խորհուրդ արեցին ու ասացին. \"Սա է ժառանգը. եկեք սրան սպանենք, որպեսզի ժառանգությունը մերը լինի\"։","15":"Եվ այգուց դուրս հանեցին նրան ու սպանեցին։ Արդ այգու տերը ի՞նչ կանի նրանց։","16":"Կգա և այն մշակներին կորստյան կմատնի, այգին էլ ուրիշներին կտա»։ Լսողներն ասացին. «Քա՛վ լիցի»։","17":"Իսկ նա նայեց նրանց ու ասաց. «Արդ, ի՞նչ են նշանակում գրված հետևյալ խոսքերը. \"Այն քարը, որ շինարարներն արհամարհեցին, անկյունաքար դարձավ\" (Սաղ. 118.22)։","18":"Այս քարի վրա ամեն ընկնող կփշրվի, և ում վրա որ այն ընկնի, նրան կջարդի»։","19":"Եվ քահանայապետներն ու դպիրները նույն պահին ուզում էին նրան ձերբակալել, բայց ժողովրդից վախեցան, որովհետև հասկացան, որ այն առակն իրենց մասին ասաց։","20":"Եվ դարանամուտ լինելով՝ լրտեսներ ուղարկեցին, որոնք արդար էին ձևանում, որպեսզի նրան խոսքով բռնեին՝ նրան կուսակալի իշխանությանը մատնելու համար։","21":"Եվ նրան հարցրին ու ասացին. «Վարդապե՛տ, գիտենք, որ շիտակ ես խոսում ու ուսուցանում և երեսպաշտություն չես անում, այլ ճշմարտությամբ Աստծու ճանապարհն ես ուսուցանում։","22":"Օրինավո՞ր է մեզ կայսրին հարկ տալ, թե՞ ոչ»։","23":"Նրանց խորամանկությունը հասկանալով՝ նրանց ասաց.","24":"«Ցո՛ւյց տվեք ինձ դինարը։ Ո՞ւմ պատկերն ու գիրն ունի սա»։ Պատասխանեցին. «Կայսրի»։","25":"Եվ նա ասաց նրանց. «Ուրեմն կայսրինը կայսրի՛ն տվեք, իսկ Աստծունը՝ Աստծուն»։","26":"Եվ չկարողացան ժողովրդի առաջ նրան խոսքով բռնել ու նրա պատասխանի վրա զարմանալով՝ լռեցին։","27":"Սադուկեցիներից ոմանք, որոնք հակառակվում են՝ ասելով, թե հարություն գոյություն չունի, նրան հարցրին","28":"ու ասացին. «Վարդապե՛տ, Մովսեսը մեզ գրել է. \"Եթե մեկի կին ունեցող եղբայրն անզավակ մեռնի, նրա եղբայրը թող այդ կնոջն առնի և իր եղբոր համար զավակ բերի\" (Բ Օր. 25.5)։","29":"Արդ, յոթ եղբայրներ կային. առաջինը կին առավ ու առանց զավակի մեռավ։","30":"Եվ երկրորդն առավ այն կնոջը, նա էլ առանց զավակի մեռավ։","31":"Երրորդն էլ նրան առավ. այսպես այն յոթն էլ զավակներ չթողեցին ու մեռան։","32":"Վերջում այն կինն էլ մեռավ։","33":"Արդ հարության ժամանակ նրանցից ո՞ւմ կինը կլինի. չէ՞ որ այն յոթն էլ նրան կին առան»։","34":"Եվ Հիսուսը պատասխանեց նրանց ու ասաց. «Այս աշխարհի մարդիկ են կին առնում ու մարդու գնում։","35":"Իսկ նրանք, որոնք արժանի կլինեն մեռելներից հարություն առնելու և նոր աշխարհում ապրելու, ո՛չ կին կառնեն, ո՛չ էլ մարդու կգնան։","36":"Եվ ոչ էլ կարող են մեռնել, որովհետև հրեշտակների նման են ու Աստծու որդիներ են, քանզի հարության որդիներն են։","37":"Իսկ որ մեռելները հարություն կառնեն, Մովսեսն էլ մորենու դրվագի մեջ ցույց տվեց, ինչպես որ Տիրոջ մասին ասաց. \"Աբրահամի Աստված և Իսահակի Աստված և Հակոբի Աստված\" (Ելք 3.6)։","38":"Իսկ Աստված մեռելներինը չէ, այլ ողջերինը, որովհետև նրա համար բոլորն էլ ողջ են»։","39":"Դպիրներից ոմանք ասացին. «Վարդապե՛տ, լա՛վ ասացիր»։","40":"Եվ այլևս չէին համարձակվում նրան ոչ մի բան հարցնել։","41":"Հիսուսը նրանց ասաց. «Ինչպե՞ս են ասում, թե Քրիստոսը Դավթի որդին է,","42":"քանի որ Դավիթն ինքը Սաղմոսների գրքում ասում է. \"Տերն իմ Տիրոջն ասաց. \"Իմ աջ կո՛ղմը նստիր,","43":"մինչև որ քո թշնամիներին ոտքերիդ պատվանդան դնեմ\" (Սաղ. 110.1)։","44":"Արդ, եթե Դավիթը նրան Տեր է կոչում, ապա ինչպե՞ս նրա որդին կլինի»։","45":"Երբ ամբողջ ժողովուրդը լսում էր, իր աշակերտներին ասաց.","46":"«Զգուշացե՛ք դպիրներից, որոնք ցանկանում են փառավոր պատմուճաններով շրջել ու սիրում են հրապարակներում ողջույններ ստանալը, ժողովարաններում՝ առաջին աթոռները և ընթրիքների ժամանակ՝ առաջին տեղերը,","47":"որոնք այրիների ունեցվածքն են լափում, ցուցադրաբար երկար աղոթք են անում. նրանք ավելի խիստ են դատապարտվելու»։"},"21":{"1":"Հիսուսը նայեց, տեսավ հարուստներին, որոնք իրենց ընծաները գանձանակն էին գցում։","2":"Տեսավ նաև մի աղքատ այրի կնոջ, որն այնտեղ երկու լումա գցեց։","3":"Եվ ասաց. «Ճշմարիտ եմ ասում ձեզ, որ այս աղքատ այրին բոլորից ավելի գցեց,","4":"որովհետև նրանք բոլորն իրենց ավելացածից գցեցին Աստծու ընծաների մեջ, իսկ սա իր չքավորությունից իր ամբողջ ապրուստը, ինչ որ ուներ, գցեց»։","5":"Երբ ոմանք տաճարի մասին ասում էին՝ «Գեղեցիկ քարերով ու ընծաներով է զարդարված», ասաց.","6":"«Այդ ամենը, որ տեսնում եք, պիտի քանդվի, օրեր պիտի գան, որ այդտեղ քարը քարի վրա չի թողնվի»։","7":"Եվ նրան հարցրին. «Վարդապե՛տ, դրանք ե՞րբ են լինելու, ի՞նչ նշան է լինելու, երբ որ սրանք լինեն»։","8":"Նա ասաց. «Զգո՛ւյշ եղեք, չխաբվեք, որովհետև իմ անունով շատերը կգան ու կասեն, թե՝ \"Ես եմ\" և՝ \"Ժամանակը մոտեցել է\"։ Նրանց հետևից մի՛ գնացեք։","9":"Իսկ երբ պատերազմների ու խռովությունների մասին լսեք, մի՛ զարհուրեք, որովհետև պետք է նախ դրանք լինեն։ Բայց վերջը շուտ չի գալու»։","10":"Այն ժամանակ նրանց ասաց. «Ազգը ազգի դեմ կելնի, թագավորությունը՝ թագավորության դեմ։","11":"Մեծ երկրաշարժեր և տարբեր տեղերում սով ու ժանտախտ կլինեն, երկնքից արհավիրքներ ու մեծամեծ նշաններ կլինեն։","12":"Բայց այս բոլորից առաջ ձեզ կձերբակալեն ու կհալածեն, ժողովարաններին ու բանտերին կմատնեն և թագավորների ու կուսակալների առաջ կտանեն իմ անվան համար։","13":"Եվ դա ձեզ համար առիթ կլինի վկայության։","14":"Արդ ձեր սրտի մե՛ջ դրեք, որ պատասխան տալու համար նախապես չպատրաստվեք,","15":"որովհետև ես խոսք ու իմաստություն կտամ ձեզ, որոնց ձեր բոլոր հակառակորդները չեն կարողանա հակաճառել, ոչ էլ ընդդիմանալ։","16":"Եվ կմատնվեք ծնողներից ու եղբայրներից, ազգականներից ու բարեկամներից, և ձեզանից ոմանց կսպանեն։","17":"Իմ անվան պատճառով բոլորը ձեզ կատեն։","18":"Բայց ձեր գլխից մի մազ չի կորչի։","19":"Եվ ձեր համբերությամբ ձեր հոգիները կփրկեք։","20":"Երբ Երուսաղեմը զորքերով շրջապատված տեսնեք, այն ժամանակ իմացե՛ք, որ նրա ավերումը մոտ է։","21":"Այն ժամանակ նրանք, որ Հրեաստանում են, թող լեռները փախչեն, իսկ նրանք, որ քաղաքի մեջ են, թող հեռանան, և նրանք, որ գյուղերում են, թող քաղաք չմտնեն։","22":"Որովհետև այդ օրերը վրեժխնդրության օրեր են, որպեսզի բոլոր գրվածները կատարվեն։","23":"Բայց այն օրերին վա՛յ հղիներին և ստնտուներին, որովհետև երկրի վրա մեծ նեղություն է լինելու, և այդ ժողովրդի վրա՝ բարկություն։","24":"Սրով կընկնեն և բոլոր ազգերի մեջ գերի կտարվեն, և Երուսաղեմը հեթանոսների կողմից ոտնակոխ կլինի, մինչև որ հեթանոսների ժամանակները լրանան։","25":"Արեգակի, լուսնի ու աստղերի վրա նշաններ կլինեն. երկրի վրա ազգերը կխռովվեն և կտագնապեն ծովի ալեկոծումից և շառաչյունից։","26":"Մարդկանց սրտերը կնվաղեն վախից ու տագնապից, որ ամբողջ աշխարհի վրա գալու են. քանի որ երկնքի զորությունները պիտի շարժվեն։","27":"Եվ այն ժամանակ Մարդու Որդուն ամպերի վրա (Դան. 7.13) զորությամբ ու մեծ փառքով գալիս կտեսնեն։","28":"Եվ երբ այս բաներն սկսեն լինել, վե՛ր նայեք ու ձեր գլուխները բարձրացրե՛ք, որովհետև ձեր փրկությունը մոտ է»։","29":"Եվ նրանց մի առակ ասաց. «Նայե՛ք թզենուն ու բոլոր ծառերին։","30":"Երբ արդեն բողբոջում են, տեսնելով՝ ինքներդ իմանում եք, որ ամառը մոտ է։","31":"Այդպես էլ դուք, երբ այս բոլոր բաները կատարված տեսնեք, իմացե՛ք, որ Աստծու արքայությունը մոտ է։","32":"Ճշմարիտ եմ ասում ձեզ, որ այս բոլորը տեղի կունենան այնքան ժամանակ, որքան ապրում է այս սերունդը։","33":"Երկինքն ու երկիրը կանցնեն, բայց իմ խոսքերը չեն անցնի։","34":"Զգո՛ւյշ եղեք ձեր անձերի համար. գուցե ձեր սրտերը ծանրանան զեխությամբ, հարբեցողությամբ և այս կյանքի հոգսերով, ու այդ օրը հանկարծակի ձեզ վրա հասնի։","35":"Որովհետև այն որոգայթի պես կհասնի բոլորի վրա, ովքեր բնակվում են ամբողջ երկրի երեսին։","36":"Ուրեմն արթո՛ւն կացեք ու ամեն ժամ աղոթե՛ք, որ արժանի լինեք փրկվելու այն ամենից, որ տեղի է ունենալու, և կանգնելու Մարդու Որդու առաջ»։","37":"Ցերեկները տաճարում ուսուցանում էր, իսկ գիշերները դուրս էր գալիս ու մնում Ձիթենյաց կոչվող լեռան վրա։","38":"Եվ ամբողջ ժողովուրդը վաղ առավոտից գնում էր տաճար՝ նրան լսելու։"},"22":{"1":"Մոտեցավ Բաղարջակերաց տոնը, որ Զատիկ է կոչվում։","2":"Քահանայապետներն ու դպիրները առիթ էին փնտրում, թե նրան ինչպե՛ս սպանեն, որովհետև ժողովրդից վախենում էին։","3":"Եվ սատանան մտավ Իսկարիովտացի կոչված Հուդայի մեջ, որ տասներկուսի թվում էր։","4":"Նա գնաց, քահանայապետների և իշխանավորների հետ խոսեց, թե նրան ինչպե՛ս մատնի նրանց։","5":"Նրանք ուրախացան ու խոստացան արծաթ տալ նրան։","6":"Նա էլ խոստացավ ու հարմար առիթ էր փնտրում, որ ամբոխից հեռու Հիսուսին մատնի նրանց։","7":"Եվ եկավ Բաղարջակերաց տոնը, երբ պետք էր զատկական գառը մորթել։","8":"Հիսուսը Պետրոսին և Հովհաննեսին ուղարկեց ու ասաց. «Գնացե՛ք, մեզ համար զատկական ընթրիքը պատրաստե՛ք, որ ուտենք»։","9":"Նրանք ասացին. «Որտե՞ղ ես կամենում, որ պատրաստենք»։","10":"Նա էլ ասաց նրանց. «Ահա երբ քաղաք մտնեք, ձեզ մի մարդ կպատահի, որ ջրի կուժ է տանում. գնացե՛ք նրա հետևից այն տունը, ուր ինքը կմտնի։","11":"Եվ տանտիրոջն ասե՛ք. \"Վարդապետը քեզ ասում է. \"Որտե՞ղ է այն օթևանը, ուր ես իմ աշակերտների հետ զատկական ընթրիքը պիտի ուտեմ\"։","12":"Եվ նա ձեզ հարդարված մի մեծ վերնատուն ցույց կտա. այնտեղ էլ կպատրաստեք»։","13":"Նրանք գնացին, գտան, ինչպես որ իրենց ասել էր, ու զատկական ընթրիքը պատրաստեցին։","14":"Երբ ժամը հասավ, նա սեղան նստեց, տասներկու առաքյալներն էլ՝ նրա հետ։","15":"Նրանց ասաց. «Շատ ցանկացա իմ չարչարվելուց առաջ այս զատկական ընթրիքը ձեզ հետ ուտել։","16":"Որովհետև, ասում եմ ձեզ, սրանից այլևս երբեք չեմ ուտելու, մինչև որ այն կատարվի Աստծու արքայության մեջ»։","17":"Եվ բաժակը վերցրեց, գոհություն հայտնեց ու ասաց. «Առե՛ք դա ու ձեր մեջ բաժանե՛ք։","18":"Քանզի, ասում եմ ձեզ, որթատունկի բերքից այլևս չեմ խմելու, մինչև որ Աստծու արքայությունը չգա»։","19":"Եվ հացը վերցնելով՝ գոհություն հայտնեց, կտրեց ու նրանց տվեց և ասաց. «Այս է իմ մարմինը, որ ձեզ համար է տրվում. այս արե՛ք ի հիշատակ ինձ»։","20":"Նույն կերպ էլ ընթրիքից հետո բաժակը վերցրեց ու ասաց. «Այս բաժակը նոր ուխտն է իմ արյունով, որ ձեզ համար է թափվում։","21":"Սակայն ահա ինձ մատնողի ձեռքն ինձ հետ սեղանի վրա է։","22":"Մարդու Որդին գնում է, ինչպես որ սահմանված է. բայց վա՛յ այն մարդուն, որի ձեռքով կմատնվի»։","23":"Եվ նրանք սկսեցին իրար մեջ հարցնել, թե արդյոք իրենցից ո՛վ է, որ անելու է այդ։","24":"Նրանց մեջ նաև վեճ ծագեց, թե իրենցից ո՛վ է մեծ համարվելու։","25":"Հիսուսն ասաց նրանց. «Ազգերի թագավորները տիրում են նրանց վրա, և նրանց վրա իշխանություն անողները բարերար են կոչվում։","26":"Բայց դուք այդպես չլինեք, այլ ձեր միջի մեծը թող կրտսերի պես լինի, իսկ առաջնորդը՝ սպասավորի պես։","27":"Որովհետև ո՞վ է մեծ՝ սեղան նստո՞ղը, թե՞ սպասավորը. չէ՞ որ սեղան նստողը։ Բայց ես ձեր մեջ սպասավորի պես եմ։","28":"Եվ դուք եք, որ իմ փորձությունների ժամանակ միշտ ինձ հետ էիք մնում։","29":"Եվ ես խոստանում եմ ձեզ, ինչպես որ իմ Հայրն էլ ինձ խոստացավ տալ արքայությունը,","30":"որ իմ արքայության մեջ իմ սեղանին կուտեք ու կխմեք և կնստեք աթոռներին՝ Իսրայելի տասներկու ցեղերին դատելու»։","31":"Եվ Տերն ասաց. «Սիմո՜ն, Սիմո՜ն, ահա սատանան ուզեց ձեզ ցորենի պես մաղել։","32":"Բայց ես քեզ համար աղոթեցի, որ քո հավատը չպակասի. իսկ դու երբ այն վերագտնես, եղբայրներիդ հաստատո՛ւն պահիր»։","33":"Նա էլ նրան ասաց. «Տե՛ր, ես պատրաստ եմ քեզ հետ բանտ ու նույնիսկ մահվան գնալու»։","34":"Եվ նա ասաց. «Ասում եմ քեզ, Պետրո՛ս, այսօր աքաղաղը դեռ չկանչած՝ դու երեք անգամ կուրանաս, որ ինձ ճանաչում ես»։","35":"Եվ նրանց ասաց. «Երբ ձեզ առանց քսակի, մախաղի ու կոշիկների ուղարկեցի, մի՞թե որևէ բանի կարոտ եղաք»։ Նրանք էլ ասացին՝ ոչնչի։","36":"Ապա նրանց ասաց. «Բայց հիմա քսակ ունեցողը թող իր հետ վերցնի, նույնը թող անի նաև մախաղ ունեցողը, իսկ չունեցողը թող իր հագուստը վաճառի և իր համար սուր գնի։","37":"Որովհետև, ասում եմ ձեզ, այս գրվածքն էլ պետք է իմ հանդեպ կատարվի՝ \"Անօրենների շարքը դասվեց\" (Ես. 53.12). որովհետև ինչ որ իմ մասին գրված է, կատարվում է»։","38":"Նրանք ասացին. «Տե՛ր, ահա այստեղ երկու սուր կա»։ Եվ ասաց նրանց՝ բավական են։","39":"Հիսուսը ելավ, իր սովորության համաձայն Ձիթենյաց լեռը գնաց. աշակերտները հետևեցին նրան։","40":"Երբ այնտեղ հասավ, նրանց ասաց. «Աղոթե՛ք, որ փորձության մեջ չընկնեք»։","41":"Ինքը նրանցից մի քարընկեցի չափ հեռացավ և ծունկի իջած աղոթում էր","42":"և ասում. «Հա՛յր, եթե կամենում ես, այս բաժակը հեռացրո՛ւ ինձանից. սակայն ոչ թե իմ, այլ քո կամքը թող լինի»։","43":"Եվ նրան երկնքից հրեշտակ երևաց ու զորացնում էր նրան,","44":"և նա, սաստիկ տագնապի մեջ լինելով, ավելի եռանդուն էր աղոթում։ Նրա քրտինքը դարձավ արյան կաթիլների պես, և թափվեցին գետնին։","45":"Աղոթքից վեր կենալով՝ եկավ իր աշակերտների մոտ և տրտմությունից քնած գտավ նրանց։","46":"Եվ նրանց ասաց. «Ինչո՞ւ եք քնում. վե՛ր կացեք, աղոթե՛ք, որ փորձության մեջ չընկնեք»։","47":"Մինչ նա խոսում էր, հայտնվեց մի ամբոխ, և Հուդա կոչվածը՝ այն տասներկուսից մեկը, առաջնորդում էր նրանց։ Եվ մոտեցավ Հիսուսին, որ համբուրի նրան։","48":"Հիսուսը նրան ասաց. «Հուդա՛, Մարդու Որդուն համբույրո՞վ ես մատնում»։","49":"Երբ նրա հետ եղողները տեսան, թե ի՛նչ է լինելու, նրան ասացին. «Տե՛ր, սրով զարկե՞նք»։","50":"Նրանցից մեկը քահանայապետի ծառային զարկեց ու նրա աջ ականջը կտրեց։","51":"Հիսուսը պատասխանեց. «Թողե՛ք, եղածը բավ է»։ Եվ նրա ականջին դիպավ ու բժշկեց նրան։","52":"Հիսուսն իր վրա եկած քահանայապետներին, տաճարի իշխանավորներին ու երեցներին ասաց. «Սրերով ու մահակներով ինչպես մի ավազակի վրա՞ ելաք։","53":"Ես ամեն օր տաճարում ձեզ հետ էի, և ինձ վրա ձեռք չերկարեցիք. բայց հիմա ձե՛ր ժամն է և խավարի իշխանությունը»։","54":"Եվ նրան բռնելով՝ տարան, քահանայապետի տուն մտցրին։ Պետրոսը հեռվից հետևում էր նրան։","55":"Երբ բակում կրակ էին վառել ու չորս կողմը նստել, Պետրոսն էլ նրանց մեջ նստեց։","56":"Մի աղախին, նրան կրակի մոտ նստած տեսնելով, նայեց նրան ու ասաց. «Սա էլ էր նրա հետ»։","57":"Բայց նա ուրացավ և ասաց այն կնոջը. «Ո՛վ կին, ես նրան չեմ ճանաչում»։","58":"Եվ քիչ հետո մեկ ուրիշը նրան տեսավ ու ասաց. «Դու էլ նրանցից ես»։ Իսկ Պետրոսն ասաց. «Ո՛վ մարդ, ես չեմ»։","59":"Եվ երբ մի ժամ էլ անցավ, մեկ ուրիշը պնդում էր ու ասում. «Ճշմարիտ որ սա էլ նրա հետ էր, որովհետև գալիլեացի է»։","60":"Պետրոսն ասաց այն մարդուն. «Ո՛վ մարդ, չգիտեմ, թե ի՛նչ ես ասում»։ Եվ իսկույն, երբ նա դեռ խոսում էր, աքաղաղը կանչեց։","61":"Տերը դարձավ, նայեց Պետրոսին. Պետրոսը հիշեց Տիրոջ խոսքը, որ ասել էր իրեն. «Մինչև աքաղաղի կանչելը երեք անգամ ինձ կուրանաս»։","62":"Եվ Պետրոսը, դուրս ելնելով, դառնապես լաց եղավ։","63":"Հիսուսին պահող մարդիկ նրան ծաղրում էին ու ծեծում։","64":"Նրա երեսը ծածկել ու հարցնում էին՝ ասելով. «Մարգարեացի՛ր՝ ո՞վ է, որ քեզ խփեց»։","65":"Ուրիշ շատ բաներ էլ էին հայհոյանքով ասում նրան։","66":"Երբ առավոտ եղավ, հավաքվեց ժողովրդի ծերակույտը՝ քահանայապետներն ու դպիրները, Հիսուսին իրենց ատյան տարան ու ասացին. «Եթե դու ես Քրիստոսը, ասա՛ մեզ»։","67":"Եվ նրանց ասաց. «Եթե ձեզ ասեմ, դուք չեք հավատա։","68":"Իսկ եթե ձեզ հարցնեմ, ինձ պատասխան չեք տա։","69":"Բայց սրանից հետո Մարդու Որդին ամենազոր Աստծու աջ կողմում կնստի (Սաղ. 110.1)»։","70":"Եվ բոլորն ասացին. «Ուրեմն դո՞ւ ես Աստծու Որդին»։ Ինքն էլ նրանց ասաց. «Դուք եք ասում, որ ես եմ»։","71":"Նրանք էլ ասացին. «Մեզ էլ ի՞նչ վկայություն է հարկավոր, երբ մենք ինքներս լսեցինք նրա բերանից»։"},"23":{"1":"Եվ նրանց ամբողջ բազմությունը վեր կացավ, ու նրան Պիղատոսի մոտ տարան։","2":"Եվ սկսեցին նրան ամբաստանել ու ասել. «Գտանք սրան, որ մոլորեցնում էր ժողովրդին և արգելում կայսրին հարկ տալ՝ ինքն իր մասին ասելով, թե Քրիստոս թագավորն է»։","3":"Բայց Պիղատոսը նրան հարցրեց. «Դո՞ւ ես հրեաների թագավորը»։ Նա պատասխանեց նրան և ասաց. «Դո՛ւ ասացիր»։","4":"Պիղատոսը քահանայապետներին ու ժողովրդին ասաց. «Ես այս մարդու մեջ ոչ մի հանցանք չեմ գտնում»։","5":"Սակայն նրանք պնդում էին ու ասում. «Ժողովրդին ըմբոստության է մղում՝ ամբողջ Հրեաստանում՝ Գալիլեայից մինչև այստեղ, ուսուցանելով»։","6":"Երբ Պիղատոսը լսեց, հարցրեց, թե այդ մարդը գալիլեացի՞ է։","7":"Եվ իմանալով, որ Հերովդեսի տերությունից է, նրան ուղարկեց Հերովդեսի մոտ, որն այդ օրերին Երուսաղեմում էր։","8":"Հերովդեսը, Հիսուսին տեսնելով, շատ ուրախացավ, որովհետև երկար ժամանակ էր՝ ուզում էր նրան տեսնել, քանի որ նրա մասին լսել էր և հույս ուներ նրա կողմից արված որևէ նշան տեսնել։","9":"Եվ նրան բազում հարցեր էր տալիս, բայց նա ոչինչ չէր պատասխանում նրան։","10":"Քահանայապետներն ու դպիրները կանգնած էին ու նրան խիստ ամբաստանում էին։","11":"Հերովդեսն էլ իր զինվորների հետ անարգեց նրան. ծաղրելով նրան՝ մի շքեղ զգեստ հագցրեց և հետ ուղարկեց Պիղատոսի մոտ։","12":"Պիղատոսն ու Հերովդեսն այդ օրը միմյանց հետ բարեկամացան, որովհետև նախկինում իրար հետ թշնամության մեջ էին։","13":"Պիղատոսը կանչեց քահանայապետներին, իշխանավորներին ու ժողովրդին","14":"և նրանց ասաց. «Դուք այս մարդուն ինձ մոտ եք բերել իբրև ժողովրդին մոլորեցնողի, և ահա ձեր առաջ հարցաքննելով՝ այս մարդու մեջ ոչ մի հանցանք չգտա այն բաների վերաբերյալ, որոնցով դուք ամբաստանում եք նրան։","15":"Եվ ոչ էլ Հերովդեսը, որովհետև ձեզ տվեցի, որ նրա մոտ տանեք։ Եվ դա ահա մահապատժի արժանի ոչինչ չի գործել։","16":"Արդ նրան կգանահարեմ ու կարձակեմ»","17":"(որովհետև անհրաժեշտ էր, որ տոնի առիթով նրանց համար մի մարդ արձակեր)։","18":"Իսկ նրանք ամբողջ բազմությամբ աղաղակում էին ու ասում. «Վերցրո՛ւ դրան ու մեզ համար Բարաբբայի՛ն արձակիր»","19":"(որը քաղաքում տեղի ունեցած մի խռովության ու սպանության համար բանտարկվել էր)։","20":"Պիղատոսը դարձյալ դիմեց նրանց՝ կամենալով Հիսուսին արձակել։","21":"Իսկ նրանք աղաղակում էին ու ասում. «Խա՛չը հանիր, խա՛չը հանիր դրան»։","22":"Նա երրորդ անգամ ասաց նրանց. «Սա ի՞նչ չար բան է արել. սրա մեջ մահվան արժանի որևէ հանցանք չգտա. սրան կգանահարեմ ու կարձակեմ»։","23":"Բայց նրանք բարձր ձայնով ստիպում էին ու պահանջում, որ նա խաչը հանվի։ Եվ նրանց ու քահանայապետների աղաղակը ուժեղանում էր։","24":"Եվ Պիղատոսը վճռեց, որ նրանց պահանջը լինի։","25":"Նրանց համար արձակեց խռովության ու սպանության պատճառով բանտ նետվածին, որին էլ պահանջում էին, իսկ Հիսուսին նրանց կամքին մատնեց։","26":"Եվ երբ նրան տանում էին, Սիմոն Կյուրենացի անունով մեկին բռնեցին, որ արտից էր գալիս. խաչը նրա վրա դրեցին, որ Հիսուսի հետևից տանի։","27":"Նրա հետևից ժողովրդի և կանանց մեծ բազմություն էր գնում, որոնք կոծում ու ողբում էին նրան։","28":"Հիսուսը դարձավ նրանց ու ասաց. «Երուսաղեմի՛ դուստրեր, ինձ վրա լաց մի՛ եղեք, այլ ձե՛զ և ձեր զավակների՛ վրա լաց եղեք։","29":"Որովհետև ահա օրեր կգան, երբ կասեն. \"Երանի՜ ամուլներին ու այն որովայններին, որոնք չծնեցին, և այն ստինքներին, որ չսնեցին\"։","30":"Այն ժամանակ կսկսեն լեռներին ասել՝ \"Մեզ վրա՛ ընկեք\", ու բլուրներին՝ \"Ծածկե՛ք մեզ\" (Ովս. 10.8)։","31":"Որովհետև եթե դալար փայտին են այսպես անում, ապա չորին ի՜նչ կլինի»։","32":"Ուրիշ երկու չարագործների էլ էին տանում, որպեսզի նրա հետ սպանեն։","33":"Եվ երբ այն տեղը եկան, որ Գագաթ էր կոչվում, այնտեղ նրան խաչեցին. և չարագործներին էլ. մեկին՝ աջ կողմը, մյուսին՝ ձախ կողմը։","34":"Հիսուսն ասաց. «Հա՛յր, ների՛ր նրանց, որովհետև չգիտեն, թե ի՛նչ են անում»։ Եվ նրա զգեստները բաժանելու համար վիճակ գցեցին։","35":"Իսկ ժողովուրդը կանգնած նայում էր։ Իշխանավորներն էլ ծաղրում էին ու ասում. «Ուրիշներին փրկեց, թող իրեն էլ փրկի, եթե դա է Քրիստոսը՝ Աստծու ընտրյալը»։","36":"Զինվորներն էլ էին նրան ծաղրում. մոտ գալով՝ նրան քացախ էին տալիս","37":"ու ասում. «Եթե հրեաների թագավորը դու ես, ինքդ քեզ փրկի՛ր»։","38":"Նրա վերևում մի գիր կար՝ հունարեն, լատիներեն ու եբրայերեն տառերով՝ «ԱՅՍ Է ՀՐԵԱՆԵՐԻ ԹԱԳԱՎՈՐԸ»։","39":"Եվ կախված այն չարագործներից մեկը նրան հայհոյում էր ու ասում. «Դու չե՞ս Քրիստոսը. փրկի՛ր ինքդ քեզ և մեզ»։","40":"Իսկ մյուսը պատասխանեց՝ նրան հանդիմանելով, ու ասաց. «Աստծուց չե՞ս վախենում, դու, որ նույն պատիժն ես կրում։","41":"Մեզ համար արդարացի է, քանզի արժանի հատուցումն ենք ստանում մեր կատարած գործերի համար, իսկ սա ոչ մի վատ բան չի արել»։","42":"Եվ Հիսուսին ասաց. «Տե՛ր, հիշի՛ր ինձ, երբ քո թագավորությամբ գաս»։","43":"Եվ Հիսուսը նրան ասաց. «Ճշմարիտ եմ ասում քեզ. դու այսօր ինձ հետ դրախտում կլինես»։","44":"Վեցերորդ ժամին մոտ էր. և ամբողջ երկրի վրա խավար եղավ մինչև իններորդ ժամը։","45":"Եվ արեգակը խավարեց, ու տաճարի վարագույրը մեջտեղից պատռվեց։","46":"Եվ Հիսուսը բարձրաձայն կանչեց ու ասաց. «Հա՛յր, հոգիս քո ձեռքն եմ ավանդում» (Սաղ. 31.5)։ Այս ասելով՝ հոգին ավանդեց։","47":"Հարյուրապետը, տեղի ունեցածը տեսնելով, Աստծուն փառք տվեց ու ասաց. «Հիրավի՜ այս մարդն արդար էր»։","48":"Եվ ամբողջ ժողովուրդը, որ այս տեսարանը դիտելու համար էր եկել, եղած բաները տեսնելով, ծեծում էր կուրծքը և վերադառնում։","49":"Նրա բոլոր ծանոթները կանգնել էին հեռվում, նաև այն կանայք, որոնք Գալիլեայից նրա հետևից էին եկել, տեսնում էին այս բաները։","50":"Եվ ահա մի մարդ կար, անունը՝ Հովսեփ, որ խորհրդի անդամ էր, բարի և արդար մարդ","51":"(սա նրանց մտադրության ու գործերի հետ համաձայնության չէր եկել). հրեաների Արիմաթեա քաղաքից էր և ինքն էլ էր սպասում Աստծու արքայությանը։","52":"Նա Պիղատոսի մոտ գնաց և Հիսուսի մարմինը խնդրեց։","53":"Եվ նրան ցած իջեցնելով՝ կտավով պատանեց ու վիմափոր գերեզմանի մեջ դրեց, ուր երբեք ոչ մի մարդ չէր դրվել։","54":"Օրն ուրբաթ էր. շաբաթն էր լուսանում։","55":"Եվ այն կանայք, որ Գալիլեայից նրա հետ էին եկել, հետևեցին Հովսեփին, տեսան գերեզմանը, և թե ինչպես նրա մարմինը այնտեղ դրվեց։","56":"Վերադարձան, խունկեր և յուղեր պատրաստեցին, բայց շաբաթ օրը, պատվիրանի համաձայն, հանգստացան։"},"24":{"1":"Բայց միաշաբաթի օրը՝ վաղ առավոտյան, կանայք գերեզման եկան ու այն խունկերը բերեցին, որ պատրաստել էին. ուրիշ կանայք էլ էին նրանց հետ։","2":"Եվ քարը գերեզմանից մի կողմ գլորված գտան։","3":"Երբ ներս մտան, Տեր Հիսուսի մարմինը չգտան։","4":"Եվ երբ դրա վրա շփոթվել էին, ահա նրանց հայտնվեցին երկու մարդ՝ լուսավոր զգեստներով։","5":"Երբ նրանք զարհուրեցին ու երեսները գետին խոնարհեցին, նրանց ասացին. «Ի՞նչ եք ողջին մեռածների մեջ փնտրում։","6":"Այստեղ չէ, այլ հարություն է առել։ Հիշե՛ք՝ նա ձեզ հետ ինչպե՛ս խոսեց, երբ Գալիլեայում էր։","7":"Ասում էր, որ Մարդու Որդին պետք է մեղավոր մարդկանց ձեռքը մատնվի, խաչվի և երրորդ օրը հարություն առնի»։","8":"Եվ նրա խոսքերը հիշեցին։","9":"Գերեզմանից վերադարձան ու այս բոլոր բաները պատմեցին տասնմեկին և բոլոր մյուսներին։","10":"Եվ նրանք էին Մարիամ Մագդաղենացին, Հովհաննան, Հակոբոսի մայր Մարիամն ու նրանց հետ ուրիշներ էլ, որոնք այս բաները պատմում էին առաքյալներին։","11":"Եվ նրանց խոսքերը սրանց ականջին ցնորք թվացին, և նրանց չէին հավատում։","12":"Բայց Պետրոսը վեր կացավ, գերեզման վազեց ու կռանալով՝ կտավներն առանձին դրված տեսավ. և տուն գնաց՝ տեղի ունեցածի վրա իր մտքում զարմանալով։","13":"Այդ նույն օրը նրանցից երկուսը գնում էին մի գյուղ, որի անունը Էմմաուս էր, որը Երուսաղեմից վաթսուն ասպարեզ էր հեռու։","14":"Նրանք միմյանց հետ խոսում էին այդ բոլոր պատահած բաների մասին։","15":"Եվ երբ նրանք խոսում ու վիճում էին, ինքը՝ Հիսուսը, մոտեցավ ու նրանց հետ գնում էր։","16":"Բայց նրանց աչքերը բռնված էին, որպեսզի նրան չճանաչեին։","17":"Եվ նրանց ասաց. «Այդ ի՞նչ բաներ են, որ քայլելիս միմյանց հետ վիճում եք ու տրտմած եք»։","18":"Եվ նրանցից մեկը՝ Կղեոպաս անունով, պատասխանեց ու նրան ասաց. «Դու մենա՞կ ես Երուսաղեմում ապրում և չգիտես այս օրերին այնտեղ պատահածների մասին»։","19":"Եվ նա ասաց նրանց. «Ո՞ր բաները»։ Նրանք էլ ասացին. «Հիսուս Նազովրեցու մասին, որ մի մարգարե մարդ էր՝ զորավոր գործերով Աստծու և ամբողջ ժողովրդի առաջ։","20":"Ինչպե՛ս մեր քահանայապետներն ու իշխանավորները նրան մահվան դատապարտեցին և խաչը հանեցին։","21":"Իսկ մենք հույս ունեինք, թե նա է փրկելու Իսրայելը. բայց այս ամենով հանդերձ՝ այս երրորդ օրն է, ինչ այս բաները եղան։","22":"Սակայն մեր միջից մի քանի կանայք էլ, որ վաղ առավոտյան գերեզման էին գնացել, մեզ զարմացրին։","23":"Նրա մարմինը չգտնելով՝ եկան ու ասացին, որ հրեշտակների տեսիլք են տեսել, որոնք ասում էին, թե նա ողջ է։","24":"Մեզանից ոմանք գերեզման գնացին և հենց այնպես գտան, ինչպես որ ասել էին կանայք, բայց նրան չտեսան»։","25":"Եվ նա ասաց նրանց. «Ո՛վ անմիտներ և թուլասիրտներ, որ դժվարանում եք հավատալ այն ամենին, ինչ որ մարգարեները ասացին։","26":"Չէ՞ որ Քրիստոսը պետք է այս չարչարանքները կրեր ու փառքի մեջ մտներ»։","27":"Եվ սկսելով Մովսեսից ու բոլոր մարգարեներից՝ նրանց բացատրում էր այն ամենը, ինչ Սուրբ Գրքում իր մասին գրված էր։","28":"Երբ մոտեցան այն գյուղին, ուր գնում էին, Հիսուսը ձևացրեց, թե ավելի հեռու տեղ է գնում։","29":"Եվ նրանք ստիպեցին նրան ու ասացին. «Մեզ հե՛տ մնա, որովհետև երեկոյան դեմ է, օրն էլ վերջանում է»։ Եվ նա գյուղ մտավ, որ նրանց հետ մնա։","30":"Եվ երբ նրանց հետ սեղան նստեց, հաց վերցնելով՝ օրհնեց, կտրեց ու նրանց տվեց։","31":"Եվ նրանց աչքերը բացվեցին, ու նրան ճանաչեցին, և նա աներևութացավ նրանցից։","32":"Եվ միմյանց ասացին. «Չէ՞ որ մեր սրտերը մեր մեջ վառվում էին, երբ ճանապարհին մեզ հետ խոսում էր և Սուրբ Գիրքն էր մեզ բացատրում»։","33":"Նույն պահին վեր կացան, վերադարձան Երուսաղեմ և հավաքված գտան տասնմեկին ու նրանց հետ եղողներին։","34":"Նրանք ասում էին. «Արդարև Տերը հարություն է առել ու երևացել է Սիմոնին»։","35":"Նրանք էլ պատմում էին այն, ինչ եղավ ճանապարհին, ու թե ինչպե՛ս իրեն ճանաչել տվեց նրանց՝ հաց կտրելու ժամանակ։","36":"Եվ երբ նրանք այս էին խոսում, Հիսուսն ինքը կանգնեց նրանց մեջ ու ասաց. «Խաղաղությո՜ւն ձեզ»։","37":"Նրանք զարհուրելով ու վախենալով կարծում էին, թե ոգի են տեսնում։","38":"Բայց նա ասաց նրանց. «Ինչո՞ւ եք շփոթվել, ինչո՞ւ են ձեր սրտերում կասկածներ առաջանում։","39":"Տեսե՛ք իմ ձեռքերն ու ոտքերը, որովհետև ես ինքս եմ. շոշափե՛ք ինձ ու տեսե՛ք, որովհետև ոգին մարմին ու ոսկորներ չունի. ինչպես տեսնում եք, ես ունեմ»։","40":"Այս ասելով՝ նրանց ցույց տվեց ձեռքերն ու ոտքերը։","41":"Եվ քանի որ ուրախությունից դեռ չէին հավատում ու զարմացած էին, նրանց ասաց. «Այստեղ ուտելիք ունե՞ք»։","42":"Նրանք խորոված ձկան կտոր տվեցին նրան ու մեղրախորիսխ։","43":"Եվ վերցնելով՝ նրանց առաջ կերավ։","44":"Եվ նրանց ասաց. «Սրանք են այն խոսքերը, որ խոսեցի ձեզ հետ, քանի դեռ ձեզ հետ էի, թե պետք է կատարվեն Մովսեսի օրենքում, մարգարեների գրքերում ու սաղմոսներում իմ մասին բոլոր գրվածները»։","45":"Այն ժամանակ նրանց միտքը բացեց, որ Սուրբ Գիրքը հասկանան։","46":"Եվ նրանց ասաց. «Գրված է. այսպես պետք է Քրիստոսը չարչարվեր ու երրորդ օրը մեռելներից հարություն առներ,","47":"և նրա անունով, Երուսաղեմից սկսած, բոլոր ազգերի մեջ ապաշխարություն ու մեղքերի թողություն քարոզվեր։","48":"Դուք էլ վկաներն եք այս բաների։","49":"Ահա ես իմ Հոր խոստումը ձեզ եմ ուղարկում, իսկ դուք նստե՛ք Երուսաղեմ քաղաքում, մինչև վերևից զորություն ստանաք»։","50":"Եվ նրանց մինչև Բեթանիա հանեց և ձեռքերը բարձրացնելով՝ օրհնեց նրանց։","51":"Եվ մինչ նրանց օրհնում էր, բաժանվեց նրանցից ու երկինք էր բարձրանում։","52":"Իսկ նրանք երկրպագեցին Հիսուսին և մեծ ուրախությամբ վերադարձան Երուսաղեմ։","53":"Եվ ամեն ժամ տաճարում էին. Աստծուն էին գովաբանում և օրհնում։ Ամեն։"}};
